window.__D("text/hemshech-ayin-beis/c002",{"p":[[3601330308,"<h3>בס\"ד. ליל ב' דחה\"ס, תער\"ג</h3>\n<b>בסכות</b> תשבו כו' כל האזרח בישראל ישבו בסכות, וצ\"ל מה\"ע כל האזרח בישראל ישבו הלא כבר נא' בסכות תשבו ומהו עוד כל האזרח כו'. ובמד\"ר אי' א\"ל הקב\"ה לאברהם אתה אמרת והשענו תחת העץ חייך שאני פורע לבניך במדבר בישוב ולעתיד, במדבר פרש ענן למסך בישוב בסכות תשבו ולע\"ל וסוכה תהי' לצל יומם. וצ\"ל מה\"ע והשענו תחת העץ ומהו בסכות תשבו שצ\"ל שזהו למע' מענין והשענו כו' שהרי השכר ודאי גבוה מהפעולה כו'. וגם הלא העושה סוכתו תחת האילן פסולה ולמדו ממ\"ש בסכו' תשבו ולא תחת האילן, הרי שבסכות תשבו הוא ענין אחר ממ\"ש והשענו כו', וצ\"ל מה\"ע בסכות תשבו כו'. ולהבין כ\"ז ילה\"ק משנת\"ל ההפרש בין האו\"מ להאו\"פ, דאו\"פ בא בהתחלקו' בעולמו' הן בעולמו' שלמע' מאצי' ובעולמו' אבי\"ע כו', והאו\"מ הוא בבחי' א\"ס ובל\"ג שאין בו התחלקו' כלל דהגם שיש מקיפים כללים ומקיפים מ\"מ הכל בבחי' א\"ס בלי התחלקות כלל כו'.\nפ) <b>אמנם</b> עדיין צ\"ל והלא יש ע\"ס דעיגולי', וכמ\"ש בע\"ח בתחלתו דכשם שיש ע\"ס דיושר כמו\"כ יש ע\"ס דעיגולים עיגול הכתר ועיגול החכ' עד עיגול המל', הרי לכאו' יש התחלקו' ע\"ס גם בעיגולים היינו בהאור שבבחי' א\"ס ובל\"ג כו'. ולכאו' צ\"ל שהן מחולקים במדריגתן מאחר שהן בבחי' כתר וחכ' ובינה כו' ה\"ז התחלקו' מדרי' כו', וממילא גם המקיפי' הן במדרי' מחולקו', מאחר שכל מקיף יש בו ע\"ס, וכמו המקיף כללי דא\"ק יש בו ע\"ס וכמ\"ש בע\"ח דבא\"ק יש ע\"ס דיושר וע\"ס דעיגולים, וכן בכתר דאצי' יש ע\"ס בבחי' כתר גופא לבד מה שהכתר"],[3601330309,"כולל הע\"ס דיושר כו', וכן בכתר דברי' כו'. ומאחר שבכל מקיף יש ע\"ס שלכאו' הן במדרי' מחולקו' ממילא גם המקיפים הן בבחי' התחלקו' כו', וה\"ז סותר למשנת\"ל שהאו\"מ אין בו התחלקו' שהוא בבחי' א\"ס ממש כו'. ומבו' בע\"ח שם שהעיגולי' יש בהם מעלה ומטה שהעיגול העליון סובב ומקיף להעיגול שלמטה ממנו וכמו עיגול הכתר מקיף לעיגול החכ' והוא מעולה ממנו כו', עד שעיגול המל' שהוא הפנימי מכולם והוא גרוע מכולם, וכמש\"ש דביושר הפנימי מכולם משובח מכולם והחיצוני המלביש כולם גרוע מכולם, ובאו\"מ להיפך שהחיצוני הסובב כולם משובח מכולם והפנימי גרוע מכולם כו', הרי כמו שיש מעומ\"ט ביושר כמו\"כ יש מעומ\"ט גם בעיגולים וסובבים ומקיפים זל\"ז כו'. אמנם זה אינו סותר עדיין לעיקר הענין שעיגולי' הוא בבחי' א\"ס, שהרי נת\"ל שיש כמה בחי' כתרים ומקיפים מבחי' כתר דא\"ק עד כתר דעשי' והכל הוא בבחי' כתר, דהשתל' הכתרים זמ\"ז דהיינו שהכל הוא בבחי' א\"ס כו'. וכמו הרצון דעשי' הוא אותו הרצון ממש שבאצי' כו', וכמשנת\"ל פע\"ט ההפרש בין שכל המעשי לעצמו' החכ' שהוא\nכמהות אחר, משא\"כ הרצון בעשי' אינו מהות אחר כו'. ומה שנק' עיגול עליון ועיגול תחתון אין זה שהן בבחי' מעומ\"ט בעצם מהותם ומדריגתן כו', כ\"א בבחי' האור והגילוי שבעיגול העליון מאיר האור ביותר מבעיגול התחתון ולכן הוא סובב ומקיף את התחתון כו'. ובאמת בכל עיגול ועיגול יש בו מעלה ומטה באופן הנ\"ל שיש עיגול עליון ועיגול תחתון, כמו\"כ בעיגול העליון גופא יש בו חלק עליון וחלק תחתון, שבעליונו של העיגול מאיר האור יותר וכשהולך ומתפשט אין האור מאיר בגילוי כ\"כ כו'. וכמ\"ש במ\"א בענין התיקון על חטא ועון שהפגם הוא בב' ענינים, הא' בחי' סילוק האור והב' יניקת החיצונים ביותר מכפי החוק הקצוב כו', שהרי ע\"פ חוק הקצוב להם ע\"פ מא' קהמ\"ד מקבלים חיות מצומצם ואחיזתם הוא רק באחורי העור דמל' כנודע וע\"י החטא אחיזתם במדרי' עליונה יותר, וגם נצוצות דקדושה נבלעים בהם כו'. וצ\"ל התיקון ג\"כ בב' ענינים אלו הא' לדחות ולהעביר יניקת החיצונים (וגם לברר וליקח מהם החיות הנמשך להם כו'), והב' המשכת האורות בכלים כו', שכ\"ז הוא ע\"י המשכת האו\"מ\nוכנודע דאו\"מ דוחה יניקת החיצונים, וגם המשכת האו\"פ הוא ע\"י המשכת האו\"מ שזהו שרשו ומקורו כו'. אמנם בכדי להעביר יניקת החיצונים הוא מחלק העליון של המקיף לפי שצריכים אור גדול יותר דכל הגבוה גבוה ביותר יורד למטה מטה ביותר כו', ובכדי שיומשך האור במקום אחיזת החיצונים לדחותם צ\"ל ממדרי' גבוה יותר כו', ובפרט שצריכים ליקח את החיות שנבלע בהם, וע\"כ צריכים אור גדול שהניצוצו' יהיו נמשכי' אליו, כמו הנר הנמשך אל האבוקה וכל שהאבוקה גדולה יותר נמשך אלי' הניצוץ גם כשהיא בריחוק כו', ובכדי שיהי' המשכת האורות בכלים הוא מחלק התחתון של המקיף שהוא בערך יותר אל האו\"פ כו'. ונמצא שבהעיגול גופא יש בו מעלה ומטה בבחי' ריבוי ומיעוט האור כו'. אך לא זהו עיקר ענין מעלה ומטה בבחי' ריבוי ומיעוט האור, שהרי גם באו\"פ נת\"ל דעיקר ענין מעלה ומטה הוא שהמדרי' העליונה היא בבחי' מעלה בעצם מדריגתה, וכמו שהחכ' בעצם מדריגתה היא בבחי' מעלה לגבי בינה כו' וכמשנת\"ל באורך, אבל הריבוי ומיעוט אין זה עיקר ענין מעומ\"ט גם באו\"פ כו', שהרי גם בחי'\nמיעוט האור הוא אותו מהות האור שבבחי' ריבוי כו'. וכמו בחו\"ב בחי' המעומ\"ט שבבחי' ריבוי ומיעוט הוא שבנקודת ההשכלה מאיר"],[3601330310,"גילוי אור רב והוא שמאיר שם הדקות והעילוי של השכלי ובהשגת הענין מתעלם האור כו', הרי כ\"ז מ\"מ מהות א' שהכל הוא בחי' שכלי, שהרי גם נקודת ההשכלה היא בחי' שכלי כו'. ואינו דומה להמעומ\"ט דחו\"ב שבעצם מדריגתן דחכ' הוא בחי' ראי' והתאמתות וההנחה שבנקודת ההשכלה, ובינה היא רק השגה לבד שבזה הם מחולקי' בעצם מהותם כו'. אבל בבחי' ריבוי ומיעוט שבהם ה\"ה מהות א' רק שבנקודת ההשכלה האור בריבוי ובהשגה האור במיעוט, אבל עצם מהותם א' הוא, וממילא יכול להיות התרחבות בבחי' המיעוט שיהי' ג\"כ בבחי' ריבוי אור כו'. וכמו בבינה אחר רוחב ההשגה שמשיג את הענין לאשורו הרי בנקודת התמצית מאיר האור ג\"כ בגילוי אור רב כמו בנקודת ההשכלה כו', ועם היות דבנקודת ההשכלה האור בדקות יותר לפי שזהו עדיין קודם שבא להשגה ונקודת התמצית הוא שבאה מההשגה כו', הרי נגד זה יש יתרון בנקודת התמצית בזכות ובהירות האור כו', כמ\"ש במ\"א ונת\"ל פל\"ג, הרי שיכול להיות התרחבות כו', והיינו לפי שהוא אותו המהות כו'. דבזה שהן מחולקים בעצם מהותם הנה במדרי' התחתונה לא\nיהי' לעולם המהות דהמדרי' העליונה כו', והיינו דבחי' התאמתות דחכ' לא יהי' בבינה כמה שיהי' התרחבות האור דבינה כו', רק שע\"י הקדמת ההשגה כשבא אל נקודת התמצית וע\"י העמקת הדעת בהנקודה איך ומה היא יכול לבוא לידי התאמתות בהענין כו' כמ\"ש במ\"א, ואז כשבא לידי בחי' ההתאמתות ה\"ה למע' מהשגה כו', והיינו לפי שאינו אותו המהות כו' (וגם מ\"ש באוצ\"ח דכשם שפנימיות אבא פנימיות עתיק כמו\"כ פנימיות בינה פנימיות עתיק, י\"ל דמ\"מ בכ\"א הוא כמהותו, דבאבא הוא כמהות בחי' ומדרי' החכ' ובבינה כפי מהות ומדרי' הבינה (וי\"ל דעתיק שהוא בחי' תחתונה שבמאציל וכנודע דעתיק הוא ל' העתקה כו' ה\"ז בחי' שלימות העצמית, ובא בכל מדרי' כפי מהותה, והיינו שמשלים בבחי' שלימות עצמי כל מדרי' כפי מהותה וכמו ואנת הוא שלימו דכולהו כו'), וע\"ד המבו' במ\"א דפנימיות חכ' ופנימיות בינה הן ב' היחודים דה' אחד מלמטלמ\"ע ומלמעלמ\"ט כו' ועמ\"ש באמ\"ב בענין יורה ומלקוש כו'). אבל בבחי' ריבוי ומיעוט שבהם יכול להיות שבהמיעוט יאיר האור בבחי' ריבוי כנ\"ל והיינו לפי שהוא אותו המהות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ועדיין צ\"ל והלא יש ע\"ס גם בעיגולים עיגול הכתר ועיגול החכ', גם יש בהם מעלה ומטה, וגם בכל עיגול יש מעומ\"ט, דבתיקון הפגמים מחלק העליון שבעיגול הוא דחיית יניקת החיצונים ונטילת החיות הנבלע בהם, ומחלק התחתון הוא מילוי חסרון האו\"פ, אך י\"ל דמעומ\"ט זה הוא בריבוי ומיעוט, וכבר נת' דגם באו\"פ עיקר המעומ\"ט הוא בעצם מדריגתן, דבזה בחי' הבינה לא תהי' לעולם במדרי' החכ' (וגם בפנימיותם שהוא כמו פנימיות עתיק י\"ל שמחולקים), אבל בריבוי ומיעוט אין זה מעומ\"ט, ויכול להיות ריבוי האור בבינה כמו בחכ', וכמו בנקודת התמצית.</span>\nפא) <b>וזהו</b> דאי' בע\"ח בההפרש באופני הגילוים באצי' והגילוי שמאצי' לבי\"ע, דאוא\"ס מאיר בכתר וחכ' בקירוב מקום כו' ובז\"א דרך חלון ובמל' דרך נקב ומאצי' לברי' דרך מסך כו'. דההפרש בזה הוא דבמדרי' דאצי' הכל הוא בחי' אותו מהות אור רק שהוא בבחי' מיעוט כו', וע\"כ גם בבחי' מל' שהאור בדרך"],[3601330311,"נקב לבד ובבחי' מיעוט הרבה, מ\"מ מאחר שהוא אותו מהות האור הרי ביכולת להרחיב הנקב ויהי' האור בריבוי כמו דרך חלון כו'. וכמו אור השמש המאיר דרך נקב מאחר שהוא מהות אור השמש שמאיר דרך הנקב יכולים להרחיבו להיות כמו חלון כו'. אבל כאשר ההמשכה היא דרך מסך הרי גם כשירבה האור מעבר למסך מ\"מ יהי' הגילוי שאחר המסך בבחי' אור של תולדה לבד כו'. והענין הוא משום דגם בבחי' מיעוט האור יש בו בהעלם בחי' ריבוי האור רק שבגילוי הוא בבחי' מיעוט האור שזה יכול התחתון לקבל כו'. וכמו בהשפעת השכל מן המשפיע אל המקבל הרי מה שבא בגילוי אל המקבל הוא רק חיצוניו' השכל דהפנימיו' אינו יכול לקבל, ובאמת הרי יש בזה פנימיו' השכל ג\"כ שז\"ע לעולם ישנה אדם לתלמידו בדרך קצרה, שאין הכוונה שלא ישפיע לו את אור השכל בשלימות כ\"א שיהי' בבחי' מועט המחזיק את המרובה, והוא שבהעלם יש בזה כל הפנימיו', רק מה שנגלה אל המקבל הוא החיצוניו' לבד כו', וזהו דקאים אינש אדעתי' דרבי' לאחר מ' שנין שע\"י היגיעה אח\"כ בהשכל הנשפע לו ה\"ה בא על הפנימיו' שבזה כו'.\n<b>וכמו\"כ</b> הוא בבחי' הריבוי ומיעוט למע' שבחי' מיעוט האור הוא שבגילוי מאיר רק בחי' החיצוניו' ובבחי' צמצום כו', אבל בהעלם יש בזה גם בחי' הפנימיו' כו'. וצ\"ל שכן הוא גם במוחין ומדות דהגם שהמדות הן מובדלים בבחי' המציאות ובבחי' הישות שלהם מבחי' המוחין (וכמו שנת\"ל פל\"ג דכל ענין המדות הו\"ע הרגש עצמו כו'), ולכן מבחי' הגילוי דמוחין א\"א להיות מציאות המדות כו' וכמשנת\"ל, מ\"מ צ\"ל שיש בזה בהעלם גם בחי' הגילוי שבמוחין שהרי המדה היא באה מההתבוננו' דוקא, שז\"ע האה' שע\"פ טו\"ד שלולא ההתבוננו' לא תהי' האה' וע\"י ההתבוננו' דוקא נולדה האהבה כו', וע\"כ הגם שזהו לאחר שנתעלם אור המוחין זהו מפני שבעת גילוי המוחין אינו שייך לבחי' המורגש דמדות, ולאחר שמתעלם אור המוחין ה\"ה בא לבחי' המורגש דמדות כו', מ\"מ יש בהמדות מאור המוחין מאחר שזהו עילת המדה כו'. וכמו בפסק דין שבא לאחר אריכות הפלפול בסברות וטעמי' הרי יש בהפסק דין בהעלם כל אריכות הפלפול, הגם שבעת שמתעסק בהשגת הסברות והטעמי' ובפלפול הענין ה\"ה למע' עדיין מהמדה היינו הפס\"ד\nבפו\"מ, מ\"מ הרי בפס\"ד יש בהעלם כל האריכות כו'. כמו\"כ בהמדה יש בה בהעלם אריכות ההתבוננו' שממנה באה כו' (וגם מה שמדות שע\"פ השכל הן באופן אחר מהמדות טבעיים שמתעוררים שלא ע\"פ השכל, ה\"ז גילוי המוחין במדות והיינו שבהמדה נראה ונגלה בחי' השכל שהיא מדה שכליות כו'), ובשעת ההתבוננו' יש ג\"כ התפעלו' המדו' שהו\"ע התפעלו' שכלי, ואח\"כ בהתפעל' המדה יש בזה מבחי' המוחין כו'. וכנודע דכל השגה אלקי' יש מדה פרטיות הבאה מהשגה זו כו', וע\"כ בעת ההשגה יש התפעלו' המדה בשכל, רק שאז המוחין בהתגלות והמדה היא בהעלם, ובעת התפעלות המדה יש בה ג\"כ בחי' אור המוחין רק שהמדה היא בהתגלו' והמוחין בהעלם כו'. ואור המוחין שבא בהמדה הוא החיות שבהמדה שזהו חיות המוחין לא חיות המדה מצ\"ע, דחיות המדה מצ\"ע היא בבחי' התלהבות כו', ובהמדות שע\"פ טו\"ד החיות שבהם היא מבחי' המוחין כו'. ולבד זאת דאור המוחין הוא בבחי' מקיף על המדות בעת התפעלות המדות, והו\"ע הרגש האור אלקי המושג שצ\"ל בעת התעוררו' והתפעלו' המדות, הנה החיות שבהתפעלו' המדה גופא הוא החיות של ההשגה האלקי', שבההשג' וההתבוננו' יש בה חיות ותענוג, והחיות הזה הוא שמאיר"],[3601330312,"ומורגש בהמדה כו'. והראי' שהרי כאשר מתעלם אור המוחין לגמרי והמדה נשארה עכ\"פ (שז\"ע עו\"ע שהעלול נשאר גם לאחר הפסק העילה כו') אין בה חיות כו', רק שהיא אז בתוקף יותר שזהו מצד המדה בעצם כו' וכמ\"ש במ\"א, אבל חיות לא יש בה כו', ובכדי להיות חיות בהמדה זהו דוקא ע\"י התחדשות ההתבוננו' והשגה כו'. הרי שבהמדה יש גילוי אור מהמוחין ובהעלם יש בה כל האריכות רק שנעלם מאד (לפי שבעצם הם מהותים נבדלים ולא כמו בעו\"ע במוחין גופא מהמשפיע אל המקבל שהחיצוניו' היא ג\"כ מוחין ואין הפנימיו' שבה בהעלם כ\"כ כו'), וגם שהרי בגדלות המדות הרי מאיר אור המוחין בגילוי ממש, והן המדות שבאים בדרך ממילא מהמוחין, והוא בבחי' פנימיו' המוחין וההשגה בעצם הענין האלקי שמתפשט האור ומאיר בגילוי בלב, שהמדו' מתפעלי' ממילא מהמוחין ובהתפעלות בלתי מורגשת כו'. והו\"ע גדלות המוחין והמדות כו' וכמ\"ש במ\"א. הרי שבהמדות בבחי' גדלות שבהם יכול להיות גילוי המוחין, א\"כ מובן שאפשר להיות התרחבות המדות להיות בהם גילוי המוחין, והיינו מפני שגם בבחי' קטנות המדות\nיש בהם בחי' המוחין בהעלם כו' (וסדר העבודה תחלה צ\"ל העבודה בבחי' חיצוניו' המוחין וחיצוניו' המדות דהיינו בחי' חיצוניו' הלב, ועי\"ז דוקא בא אח\"כ לבחי' פנימיות הלב וגם לבחי' תעלומו' הלב שזהו מבחי' פנימיו' בינה ופנימיות חכ' כו', והו\"ע הלב מבין והלב רואה וכמ\"ש ולבי ראה כו'). ומכ\"ז מובן למע' דגם בבחי' או\"פ הענין דריבוי ומיעוט האור אין זה בחי' התחלקו' ממש, משום שבהמיעוט יש בו בהעלם גם בחי' הריבוי כו', ומכ\"ש בבחי' האו\"מ שאין זה התחלקות כו'. די\"ל דבאו\"פ בחי' מיעוט האור הוא בחי' חלישות עכ\"פ כו', וע\"ד בחי' מיעוט האור דתיקון שהוא בבחי' חלישות ונק' רך כקנה כו'. וכנודע דקשה כארז ורך כקנה זהו בחי' תהו ותיקון דבתהו שהי' ריבוי האור הוא קשה כו', ובתיקון שנעשה מיעוט האור ה\"ה בבחי' חלישות שז\"ע רך כקנה כו' (והגם שאינו דומה לגמרי דבתיקון החלישות הוא ע\"י שהאור בא בבחי' התחלקות פרטים והיינו מה שכל מדרי' נתחלקה לריבוי פרטים, וכאן אין זה בבחי' התחלקות פרטי', וכמו חלישות המדות לגבי המוחין שזהו רק מצד מיעוט האור לבד\nלא מצד מה שהמדה גופא מתחלקת למדרי' פרטים כו'. הנה בתיקון ג\"כ בכדי שיהי' התחלקו' האור למדרי' פרטים, צ\"ל המיעוט בכללות האור שזהו בחי' החלישות בכלל הנעשה ע\"י ש' מ\"ה דתיקון להיות האור בבחי' מיעוט, ועי\"ז יוכל להיות ההתחלקו' כו'. וכמו\"כ כאן בחי' המיעוט בכלל הוא בחי' חלישות כו'), דלהיות דכללות ענין או\"פ הוא בחי' גילוי וכאשר הגילוי הוא במיעוט, הגם שיש בזה בהעלם בחי' ריבוי האור מ\"מ ה\"ז נחשב כפי מדרי' בחי' הגילוי דוקא. וכמו בחי' חיצוניו' המוחין הגם שבהעלם יש בזה בחי' הפנימי מ\"מ ה\"ז בכל הפרטים כפי מדרי' חיצוניו' המוחין כו'. שהרי יש הפרש גדול בין פנימיו' המוחין לחיצוניו' המוחין בענין ההתפשטו' וההתלבשו' שבהם דבחי' פנימיו' המוחין מתפשטי' ומאירים גם בלב והוא שמהות המוחין עצמן מאירים בלב כו', משא\"כ בחיצוניו' המוחין שאין מהות ההשגה מתפשטת בלב כ\"א רק הארה לבד כו', ובד\"כ מה שנמשך בלב הוא הבכן לבד כו' וכמ\"ש במ\"א. וכן בהתלבשו' שלהם הרי פנימיות המוחין שמתלבשים במדות היינו בגדלו' המדות שהן כמהות מוחין בלתי\nמורגשים כו', וחיצוניות המוחין מתלבשים במדות מורגשים בבחי' יש כו', הרי שעם היות שבחיצוניו' המוחין יש בחי' הפנימיו' מ\"מ ה\"ז בכל הפרטים כפי בחי'"],[3601330313,"החיצוניו' כו'. וז\"ע החלישות שבהאור דלהיות שהגילוי הוא בבחי' מיעוט ה\"ה בבחי' התפשטות והתלבשות וכה\"ג הכל כפי בחי' המיעוט כו', משא\"כ באו\"מ הגם שהוא בבחי' מיעוט ה\"ז בבחי' התוקף ממש כמו בבחי' ריבוי האור כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו דבאצי' הגם שמתמעט האור ממדרי' למדרי' מ\"מ יכול להיות בזה התרחבות, משא\"כ מאצי' לבי\"ע, והענין הוא משום דבמיעוט יש בו בהעלם בחי' הריבוי, וכמו בחיצוניות השכל הנשפע להמקבל יש בחי' הפנימיות וכן גם במדות יש בהם בחי' המוחין גם כשנעשית מדה מורגשת, וזהו החיות של המדה, ובגדלות המדות יש גילוי המוחין, הרי שאין זה התחלקות באמת גם באו\"פ וכ\"ש באו\"מ, דבאו\"פ המיעוט הוא בחי' חלישות האור עכ\"פ, ולכן בכל עניניו הוא כפי בחי' המיעוט, ובהאו\"מ המיעוט הוא בתוקף כמו הריבוי.</span>\nפב) <b>ויובן</b> זה מענין התמימות דידוע דעיקר ענין התמימות הוא בנקודת הרצון שבעצם הנפש שלמע' מטו\"ד כו', דבד\"כ ענין התמימות הוא בהעצמי דוקא לא בההתפשטות, דענין התמימות היינו שהוא תמים ושלם (גאנץ) ואינו מתנענע אנה ואנה שזהו בהעצמי דוקא, כי ההתפשטות היא בבחי' תנועה ובבחי' התחלקות לפי שבהתפשטות יש פנים לכאן ופנים לכאן, אבל בהעצמי אין בו התחלקות כו', וזהו שענין התמימו' שהוא תמימות ושלימות בכל דבר הוא בהעצמי דוקא כו'. וכמו\"כ בחי' הביטול שבתמימות (דזה שהתמימות הוא שהוא שלם ותמים בכל דבר ואינו מתנענע כו', זהו מצד הביטול וההנחה שבו כו') הוא בעצם נקודת הרצון שלמע' מטו\"ד כו'. וז\"ע מ\"ש תמים תהי' עם ה' אלקיך וארז\"ל פסחים דקי\"ג ע\"ב מנין שאין שואלים בכלדיים שנא' תמים תהי' כו' ופרש\"י תמים תהי' להיות בוטח בכל קורות ונולדות הבאות לך, והיינו שלא ילך בתחבולות והתחכמות יתירה כ\"א לבטוח בה', ובזה יש ב' אופני' הא' שיעשה כלי לברכת ה' וכמו וברכך ה' אלקיך בכל אשר תעשה שצריך לעשות כלי, אבל לא יחשוב את הכלי\nלעיקר ולא יניח מוחו ולבו בזה, ומכ\"ש שלא יתנהג בזה בהתחכמות יתירה שז\"ע מותרי מוחין כו', כ\"א לבטוח בה' דברכת ה' היא תעשיר והוא הנותן לך כח כו', וכמ\"ש בלק\"ת ד\"ה כי תצא דרוה\"ב בענין וגלחה את ראשה כו'. וממילא לא יהי' לו מניעה ועיכוב מזה בתורה ותפלה כו', שהרי גם בעלי עסקים מחוייבים בלימוד התורה עכ\"פ פרק א' שחרית ופרק א' ערבית ובתפלה בזמנה כו', וכאשר בוטח בה' דהוא הנותן לך כח כו' לא יהי' לו שום מניעה ועיכוב כו'. וזהו בבחי' ביטול והנחת עצמותו למעלה מטו\"ד, כי השכל הגשמי מחייב באופן אחר, והיינו לחשוב שזהו מקור פרנסתו ושצריך לעסוק בזה במוחו ולבו כו', ולפעמים יש בזה נסיונות כאשר נראה לו ע\"פ השכל שבהכרח לעשות כך וכך גם בדרך תחבולה והתחכמות כו', והוא מונע א\"ע מזה מפני הבטחון שה' הוא המפרנס כו', וכן לפעמים דוקא בעת זמן התפלה או בזמן הקבוע לעסק התורה אז מזדמן איזה התעסקות בעסק, דלהניח זה ולא יביט על שום דבר ה\"ז נסיון כו', רק כשבוטח בה' יכול הוא לעמוד בנסיון כו'. ואופן הב' הוא שיש ענינים שאינו צריך\nלהיות עשיית כלי ג\"כ (או שהכלי היא לפ\"ע כפי הצורך לו בההשפעה או בהישועה מלמעלה כו' ועמ\"ש בהקדמת ד\"ח). והענין הוא דכתיב טוב לחסות בה' מבטוח באדם ומשמע מזה שטוב ג\"כ לבטוח באדם רק שיותר טוב"],[3601330314,"לבטוח בה', ואינו מובן איך טוב לבטוח באדם ח\"ו. אך הענין הוא דבאדם הכוונה על אדם העליון כמ\"ש בלק\"ת ע\"פ זה והיינו בבחי' ממכ\"ע, ועז\"א שטוב יותר לבטוח בה' בחי' סוכ\"ע כו', וע\"כ או' רק טוב לחסות מפני שצ\"ל גם לבטוח באדה\"ע וכמ\"ש שם בלק\"ת הענין בעבודה וגם בגשמיות שצריך האדם להתנהג ע\"פ הטבע, אבל יותר טוב הוא לחסות בה' כו'. והענין הוא דהנה ידוע שיש ב' מיני הנהגות מלמעלה והוא ענין עילת העילות וסיבת הסיבות, עה\"ע הוא בחי' ממכ\"ע ומשם נמשכי' הדברים שהולכין כסדרן שע\"פ הטבע וכענין הטבע בגימט' אלקים כו', וסבה\"ס הוא בחי' סוכ\"ע ומשם נמשכים הדברים שהן כעין סבה שלא עפ\"י הטבע וכמו כי היתה סיבה מעם ה', ויש כמה דברים שהאדם צריך להניח על הנהגת ה' לבדו ושלא לעשות שום דבר כ\"א לבטוח בה' שבטח יעזור השי\"ת בדרך סבה כו' (וכאשר רואין שההנהגה צ\"ל באופן כזה אין זה בכלל אין סומכין על הנס כו'). ועז\"נ תמים תהי' כי לזה צריך תמימות יותר היינו ביטול לגמרי למעלה ממה שנראה לעין השכל האנושי כו', דשכל אנושי אינו מחייב כלל שלא לעשות\nשום דבר גם בדרך כלי כו', וצריך להיות לזה ביטול גדול ביותר שלא לעשות שום דבר רק לבטוח כו'. ולכן תמים עדיף מצדיק וכמ\"ש רש\"י פ' נח ע\"פ כי אותך ראיתי צדיק והוא מהגמ' עירובין די\"ח ע\"ב, דצדיק הוא מבחי' אור ישר בחי' ממכ\"ע ותמים בחי' סוכ\"ע כו'. וברבות שמות אי' תמים תהי' שנתממו עמו בסיני ואמרו כל אשר דבר ה' נעשה, נמצא זה שהקדימו נעשה לנשמע נק' תמים, וידוע שזהו ביטול שלמע' מטו\"ד כו'. ונמצא דענין התמימות הוא בעצם נקודת רצון הנפש בבחי' ביטול שלמעלה מטו\"ד כו'. ויש ענין התמימות בכל הציור קומה גם במוח ולב, וענין התמימות במוחין הוא שהשכלתו והשגתו תמיד הוא לטוב וההיפך מזה אינו עולה בדעתו כלל, וכמו שיש יושר בשכל דהיינו שמשכיל ומשיג כפי אמיתות הענין ולא יעקם בשכלו, כמו\"כ יש ענין התמימות במוחין, שמפני נתינתו ומסירתו להדבר השכלותיו והשגותיו הוא רק בטובת ועילוי הענין ואמיתית הענין ואינו נופל לו מחשבה והשגה אחרת כלל כו'. ובכלל זה הוא ג\"כ שלא יתאונן לעולם דענין ההתאוננות הוא מפני ששכלו מחייב באופן אחר וע\"כ\nמתאונן כו', והתמים בשכלו לא יתאונן לעולם מפני שאינו חושב באופן אחר כלל כו'. וכן יש תמימות בלב הנק' ערנשטקייט והוא שתוכו כברו ולבבו שלם בדבר ולא ישונה לעולם ולא יטה לימין ושמאל כו', והוא בלא התפעלות אבל הוא תמים ושלם כו', דבהתפעלות הלב שמצד הטו\"ד יכול להשתנות כו' (ורק התפעלות עצמי הוא באמיתות ממש ואינה משתנה כו', והיינו כאשר יש התגלות עצמי באמת ואם אינו אמיתי ישתנה ויתחלף תיכף כו', והתפעלות שע\"פ טו\"ד ג\"כ משתנה כו'), והתמים בלב הוא שאינו מתפעל אבל הוא תמים ושלם (גאנץ און ערנשט וואס עם ארט ארט און וואס עם ארט ניט ארט ניט ואינו מרומה לא לעצמו ולא לזולתו כו'), ולא ישונה לפי שהוא מצד עצם נקודת הרצון שאינו משתנה לעולם כו'. וכן יש תמימות במעשה הנק' תמים במעשיו וכמ\"ש איש תם וישר שהוא סו\"מ וע\"ט בפו\"מ בבחי' התמימות שלא ישונה לעולם ואינו נוגע לו הזמן והמקום, שמפני תוקף הדבר והתמימות שבנפשו שכך צריך לעשות ואינו שייך כלל באופן אחר, ע\"כ בכל זמן ובכל מקום שהוא ה\"ה עושה כן בלי שום שינוי כלל, ולא יחוש\nמשום מנגד ומסית להדיחו ח\"ו מצד עוצם התוקף בנפשו כו', עד שגם אינו נחשב אצלו לנסיון כלל מאחר שאופן אחר ח\"ו אינו שייך"],[3601330315,"כלל כו' (ואין זה מצד התוקף לבד כ\"א מפני שסיבת התוקף הוא מצד התמימות שהו\"ע הביטול כו' ע\"כ אינו מתפעל משום דבר כו'), וידוע דנעוץ תחלתן בסופן כי המעשה הוא סוף ושרשו בראש ותחלת הכל שהוא נקודת הרצון, שזהו עיקר האמת דמדת התמימות שבא בסוף מעשה בפו\"מ בתמימות העשי' בתוקף מבלי יטה כלל כו' (ונודע דאמת ר\"ת ראש תוך סוף והו\"ע הרצון שזהו ראש הכל, והתמימו' במוח ולב שנק' תוך והתמימות במעשה שנק' סוף כו', והכל אמת בעצם נקודת הרצון בכל הכחות עד סוף מעשה כו', ואפשר שלגבי הרצון הכל כמעשה יחשב כו'). וזהו אז אתם א' תם דשרש ומקור התמימות הוא ברצון שלמעלה מהדעת, שבלתי נוטה כלל מנקודת רצונו הפשוט ותמים ותוקף התמימות הזאת הוא בכל הכחות עד העשי' בפו\"מ כו', וזהו מה שבהרצון לא יש התחלקות מדרי' דבחי' מיעוט וריבוי שגם בסומ\"ע שהוא בבחי' מיעוט האור לגמרי ואין כאן התפעלות והתגלות הרצון כלל, והוא בבחי' התוקף ביותר כמו בעצם נקודת הרצון ממש בלי שום שינוי כלל וכלל כו'. ומובן מזה דמה שיש באו\"מ עליון ותחתון בבחי' ריבוי ומיעוט\nהאור אין זה בחי' התחלקות כלל לפי שבהמיעוט יש בחי' הריבוי ויש בו כל התוקף שבריבוי כו' (ובכללות הוא בבחי' העלם וכמו שהוא בהעלם הוא שוה בכ\"מ ממש כו', ואם יהי' התגלות נקודת הרצון הוא ג\"כ בשוה בכ\"מ, וכמו במס\"נ בנסיון דקדה\"ש הרי ההתגלות היא בסומ\"ע בתוקף ההתגלות במס\"נ בפו\"מ על קדה\"ש שזהו רק מצד עצם נקודת הרצון שמתגלה בסומ\"ע בפו\"מ כו').\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש בסכות תשבו. דהנה מש\"א אברהם והשענו תחת העץ הנה העץ הוא בחי' אילנא דחיי בחי' עץ החיים שזהו בחי' ז\"א או בחי' ת\"ת בד\"פ, והיינו שאברהם המשיך להם אור מקיף דהרי השגת המלאכים הוא רק בהארה מבחי' המל' וכמ\"ש וצדקתך ירננו ואברהם המשיך להם אור מקיף מבחי' ז\"א כו', ובשכר זה נתן לבניו מצות סוכה כמ\"ש בסכות תשבו וזה מדרי' גבוה מבחי' עץ החיים, דגבי נש\"י הוא בבחי' או\"פ וכמ\"ש כי האדם עץ השדה דבחי' עה\"ח זהו בחי' אדם בחי' או\"פ כו', אבל סוכה הוא בחי' או\"מ ממש כו'. ולכן העושה סוכתו תחת האילן פסולה דטוב לחסות בהוי' בחי' סוכ\"ע כנ\"ל שזהו בחי' סוכה כו'. אמנם ענין בסכות תשבו הוא שהמקיף יאיר בבחי' גילוי והיינו ע\"י הקדמה דר\"ה ויו\"כ שהו\"ע התשו' שעי\"ז ממשיכי' בחי' האו\"מ שיאיר בגילוי ממש כו', ומש\"א כל האזרח בישראל הי' בחי' עליונה של המקיף שזהו הגילוי דלעתיד בחי' פנימיו' המקיף, וזהו כל האזרח בישראל מה שיזריח לעתיד בנש\"י ישבו בסוכות עכשיו שהרי המיעוט יש בו בחי' הריבוי כו'. וזהו בסכות תשבו\nשע\"י העבודה דר\"ה ויו\"כ יהי' גילוי בחי' המקיף וכמ\"ש תקעו כו' ליום חגינו כו'. וגם מה שעתיד להזריח בחי' פנימיו' המקיף שיהי' לעתיד בבחי' או\"פ בנש\"י שז\"ע כל האזרח בישראל כו' ישבו ג\"כ בסכות עכשיו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויובן זה מענין התמימות, דתמימות הוא בהעצמי דוקא, והביטול הוא בעצם נקודת הרצון, וזהו תמים תהי' שלא ילך בתחבולות והתחכמות, וזה או שעושה כלי ובוטח בה', או שאינו עושה כלי כלל, והו\"ע טוב לחסות בה' בחי' סוכ\"ע הנק' סבה\"ס, וזהו תמים דעדיף מצדיק, ויש ענין התמימות בכל הציור קומה,</span>"],[3601330316,"<b>במוחין</b> הוא שהשכלותיו הן רק לטוב, ושלא יתאונן לעולם, ובלב הוא שתוכו כברו, ותמים במעשיו, והוא בלי התפעלות אבל לא ישונה בכל מקום ובכל זמן, ונתב\"ס דתמימות המעשה מאמת תמימות הרצון, וזה אתם א' תם, וזהו אמת דשוה ברת\"ס הרי שהמיעוט וריבוי שבהתגלות אין זה התחלקות כלל בהאו\"מ (והתגלות הרצון הוא בסומ\"ע בתוקף כמו במס\"נ על קדה\"ש). ובזה יובן מ\"ש בסוכות תשבו בזכות והשענו תחת העץ, עה\"ח בחי' ממכ\"ע, ואברהם המשיך או\"מ, ולכן תחת העץ פסולה דטוב לחסות בה', ותשבו הוא שיאיר בפנימיות, וכל האזרח בישראל הוא בחי' פנימיות המקיף שיאיר לעתיד."],[3601330317,"<h3>בס\"ד. שמע\"צ, תער\"ג</h3>\n<b>ביום</b> השמיני עצרת תהי' לכם, וצ\"ל והלא שמע\"צ הוא רגל בפ\"ע למה נק' יום השמיני דהיינו שמיני לחג, דלכאו' הי' צריך לחשוב אותו על ימי החודש, כמו כל המועדים שבחדש זה כמו שנא' באחד לחדש ובעשור בו ובחמשה עשר בו כו', וכמו\"כ הי' צריך לחשוב שמע\"צ ג\"כ בימי החדש ומפני מה נק' יום השמיני כו'. גם צ\"ל מה שהקרבן דשמע\"צ הוא פר אחד איל אחד ולא כמו כל יומי החג שהקריבו הרבה פרים שהי' התחלה מי\"ג פרים עד שבעה פרים כו' ובשמע\"צ רק פר אחד כו'. ובמדרש אי' משל למלך שאמר לאוהבו בא ונגלגל אני ואתה במה שנמצא כו' והו\"ע מ\"ש לכם דוקא כו', וצ\"ל מה\"ע אני ואתם דוקא. ולהבין כ\"ז צריכים להקדים משנת\"ל דהאו\"מ אין בו התחלקות דבשרשו באוא\"ס שלפני הצמצום הוא האור שבבחי' גילוי העצם שהוא בבחי' א\"ס וע\"כ גם כמו שנעשה בבחי' מקיף לעולמות הוא בבחי' א\"ס דהגם שיש בזה מקיפי' כללים ומקיפים פרטים אין בזה התחלקות כו'. ונת\"ל דלכאו' יש סתירה לזה ממ\"ש בע\"ח דבעיגולים יש ע\"ס וגם מבו' בע\"ח שיש בעיגולים מעלה ומטה היינו עיגול עליון ועיגול תחתון\nכו'. ונת' דמה שיש מעלה ומטה בעיגולים אין זה סותר לעיקר הענין דעיגולים אין בהם התחלקות, דבחי' מעומ\"ט שבהם אין זה שמחולקים בעצם מדריגתן כ\"א בבחי' הגילוי לבד דהיינו בבחי' ריבוי ומיעוט כו', וענין ריבוי ומיעוט אין התחלקות גם באו\"פ וכ\"ש בהאו\"מ, מפני שהמיעוט יש בו בהעלם כל האור דבחי' ריבוי ובפרט בהאו\"מ שבהמיעוט יש גם בחי' התוקף כמו בבחי' הריבוי כו'.\nפג) <b>ומעתה</b> צ\"ל מ\"ש בע\"ח דבעיגולים יש ע\"ס עיגול הכתר ועיגול החכ' כו', ולכאו' זהו בחי' התחלקות מאחר ששייך בהם השמות דכח\"ב ה\"ז לכאו' התחלקות בעצם מדריגתן כו', וכאשר בעיגולים באמת לא יש התחלקות איך שייך שם ע\"ס כו'. אך הענין הוא דהנה נת\"ל (ד\"ה נשא) דבאוא\"ס שלפני הצמצום שלמעלה מהע\"ס הגנוזות והיינו באוא\"ס הבלי גבול שייך ג\"כ ספירות, לפי שהוא בחי' אור וגילוי עכ\"פ, וכל גילוי הוא ע\"י ספירות, רק ששם אין מספר לספירות."],[3601330318,"<b>ונת'</b> שם דהיינו שגם הספירות הן בבחי' בלי גבול, דמאחר דהפשיטות הוא סיבת הספי' אין קץ, וכמא' אנת הוא חד ולא בחושבן דלפי שהוא חד בעצם ע\"כ הספי' הן לא בחושבן כו', ממילא הספירות גופא הן ג\"כ בבחי' פשיטות כו'. ולכאו' א\"מ איך הוא ספי' בבחי' פשיטות והלא הספי' הן בחי' הגבלה ואיך הוא ספי' בבחי' פשיטות כו'. ולהבין זה צ\"ל תחלה מהו שם ספירה, והנה בפרד\"ס שע\"ח פ\"ב הביא כמה פי' בשם ספי', הא' ל' מספר וז\"ל ויש שפי' בל' מספר כי המספר מבעלי הגבול ואע\"פ שאינם בעלי גבול, בערך שרשם הפשוט בעלי גבול הם ובערך פעולתם אלינו עכ\"ל. והנה כללות ענין המספר הוא רק התגלות הדבר שהרי ע\"י המספר לא נתחדש שום דבר בגוף ומהות הדבר הנספר ולא במספרו, דכמו שהי' קודם שנספר כן הוא בלי שום תוס' וגרעון לאחר שנספר, רק שבא המספר מהעלם לידי גילוי כו', וז\"ע המספר בע\"ס דאצי' שהו\"ע גילוי מההעלם כו'. והענין דהנה מצד ההגבלה דמספר ר\"ל מה שמספר הוא הגבלת הדבר הנמנה שהוא במספר כך וכך כו', הרי זה שייך רק בבי\"ע ששם הו\"ע ההגבלה ממש כו', וכמו ענין\nהזמן ששייך רק בבי\"ע, אבל באצי' למע' מהזמן הי' הוה ויהי' כא' כו' וכמ\"ש במ\"א, וכמו\"כ הוא בענין המספר דשייך רק בבי\"ע כו'. ומ\"מ נק' הספי' ע\"ש המספר לפי שהמספר הוא גילוי מההעלם, א\"כ גם ההגבלה היא רק בבחי' התגלות לבד לא בחי' התחדשות ההגבלה כו', דבבי\"ע ההגבלה היא בבחי' התחדשות דהיינו בבחי' מציאות יש ממש כו', אבל בענין המספר מאחר שהוא בחי' התגלות, ע\"כ גם ההגבלה שבו אינו הגבלה בבחי' התחדשות כ\"א בבחי' התגלות לבד כו'. וע\"כ שייך ענין המספר באצי' שז\"ע אצי' שאינו התחדשות דבר כ\"א רק מהעלם אל הגילוי לבד כו'. והענין הוא דהנה הגבלת המספר שהוא במספר כך וכך היינו עשר ולא תשע כו', הרי גם בשרשי האורות באוא\"ס שלפני הצמצום הן בחי' ע\"ס, והוא מה שאוא\"ס הבל\"ג שיער בעצמו להאיר בבחי' מדה וגבול כו' וכמשנת\"ל, רק ששם הן בבחי' אחדות לגמרי ובאצי' באו בבחי' התחלקות כו' כמשנ\"ת כ\"ז באורך. אך גם ההתחלקות דאצי' אינו בבחי' התחלקות ממש וכמשית\"ל בענין ל' בחי' שנא' בע\"ס דאצי', וא\"כ אין זה התחדשות רק בחי' התגלות לבד כו' (גם שהרי\nהע\"ס דאצי' הן בריבוי התכללות עד אין שיעור שזהו מכח הא\"ס שבהם כו', וכמ\"ש במ\"א בענין ריבוי ההתהוות מבחי' המל' עד אין קץ ושיעור שזהו מכח הא\"ס שבמל' כו' וכ\"ש שכ\"ה בבחי' ההתכללות שבספי' כו'). וי\"ל דהגבלת המספר הוא ג\"ז מה שבאה כל ספי' בהגדרה מוגבלת וכמו הגדרת החכ' והגדרת הבינה כו', אמנם ג\"ז הוא רק בבחי' התגלות מההעלם לא בבחי' התחדשות, שהרי גם בשרשם הן בחי' ע\"ס הגנוזות, ושם הן בבחי' התאחדות לגמרי ובלתי מציאות ניכרת כלל וכלל, ובאו בהקו בבחי' ספירות פרטיות, ובחי' החכ' שבקו היא אותה החכ' שבא\"ס כמשנת\"ל, וגם בהקו הספי' הן בבחי' בלי מה, וכשבאו בכלים ה\"ה בבחי' מציאות דבר, ומ\"מ ה\"ה בבחי' פשיטות לגבי ע\"ס דכלים כו' כמשנ\"ת כ\"ז לעיל. וא\"כ אין זה בחי' התחדשות רק גילוי ההעלם כו' (ועמשית\"ל פ', ואין זה סותר למש\"כ דודאי נשלול לגמרי גדר החכ' מא\"ס, ומ\"מ יש בחי' חכ' שבא\"ס, וחכ' דאצי' הוא בבחי' גדר חכ' ומ\"מ היא בבחי' חכים ולא בחכ' ידיעא כו'). וזהו ששולל הפרד\"ס ענין ההגבלה בע\"ס דאצי' דכשאו' דשם ספי' הוא לשון מספר\nה\"ה שולל ענין ההגבלה בהם, שזהו רק לגבי שרשם הקדום כו', להיות כי ענין המספר הוא הגבלת הדבר ע\"כ אומר שזהו רק לגבי"],[3601330319,"שרשם כי ההגבלה ממש שייך רק בבי\"ע, והגבלת המספר באצי' אינה הגבלה ממש רק לגבי שרשם הקדום כו' (דהיינו הגבלה שבבחי' התגלות לבד כו'), וכן בערך פעולתם אלינו, וכנודע דהגבול דאצי' הוא רק מה שההמשכה שחוץ לאצי' תהי' בבחי' גבול, אבל באצי' אינו בבחי' גבול עדיין דע\"ס דאצי' אין סוף להתפשטותן גם בבחי' הכלים כו' וכמ\"ש במ\"א, ועיקר ענין המספר באצי' הוא מה שהמספר ענינו הוא רק התגלות מההעלם כו', ומ\"מ בהתגלות המספר בא הדבר לידי התחלקות. וזהו שהמספר צ\"ל בדבור דוקא, וכמו בספה\"ע שלא די במח' כי אם בדבור דוקא, לפי שבמח' הוא בהתכללות עדיין, וגם כשחושב כאו\"א בפ\"ע אין זה בבחי' התחלקות רק כשסופר בדבור ה\"ז בבחי' התחלקות, ע\"כ עיקר המספר הוא בדבור דוקא. וכמו\"כ הוא למעלה דלמעלה מאצי' הכל הוא בבחי' אחדות עדיין, וכמשנת\"ל באורך דהקו הגם שעשוי מנקודות פרטים מ\"מ הכל בבחי' אחדות ונק' ע\"ס בלי מ\"ה כו', ובאצי' באין הע\"ס בבחי' התחלקות כו'. וז\"ע המספר שהוא בבחי' ההתגלות מההעלם רק שבא בבחי' התחלקות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם צ\"ל איך שייך כו\"ח בעיגולים, אך הענין דגם באוא\"ס הבל\"ג שייך ספי' אין קץ, והיינו שהספי' גופא הן בבחי' פשיטות, ויקדים מהו שם ספירה, הפרדס מפרש ספירה ל' מספר, ומספר הוא התגלות ההעלם, וכן הגבלת המספר היינו הגבלת ההתחלקות והגבלת ההגדרה, הוא ג\"כ רק בבחי' התגלות מהעלם כי ישנו גם בשרשם, ובהתגלות ג\"כ אינו בהתחלקות והגדרה ממש כ\"א בבי\"ע, ומ\"מ בהתגלות המספר באין לבחי' התחלקות.</span>\nפד) <b>ובשעה\"כ</b> ע' מספר הימים כ' פי' הרשב\"י ע\"ה בתי' כי המל' נק' מספר כו', והטעם כי היא חשבון ומספר לימים עליונים, ופי' כי הימים עליונים מתגלים ע\"י המדה הזאת המגלה אותם כמו החשבון שהוא הגבלת הדבר הנמנה ומצד הגבול והחשבון מתגלה עכ\"ל. והיינו ג\"כ כנ\"ל שהמספר הוא ההתגלות מההעלם, והוא שהמספר כבר יש בהעלם והמספר הוא רק ההתגלות שלו, ומ\"מ הרי קודם שנספר הרי אינו בבחי' מספר עדיין כו', והוא מפני שהמספר הוא הגבלת הדבר שבא בהגבלה והתחלקות, ועי\"ז הוא בבחי' מספר, וקודם שנספר הגם שהוא בבחי' מספר בהעלם אינו בבחי' הגבלה והתחלקות עדיין כו'. וז\"ע שהמל' נק' מספר הימים דימים עליונים הן המדות העליונות שנק' ימי עולם כנודע, והנה הגם שהן ג\"כ בבחי' מספר והן ששה מדות שהן מקור ההשפעה לשית אלפי שני כו', מ\"מ ה\"ז למעלה מהגבלה והתחלקות עדיין, ובמל' בא בבחי' הגבלה והתחלקות, שעי\"ז הוא בחי' הגילוי, וע\"כ שם עיקר המספר כו' (וכמו שהזמן עיקרו בבחי' מל' מלך מלך ימלוך ובז\"א רק סדר זמנים כו' וכמ\"ש במ\"א). והיינו שאינו\nדומה ההגבלה דמל' לההגבלה דלמעלה מבחי' המל', שע\"כ עיקר ענין המספר הוא בבחי' מל' דוקא. ויובן זה ע\"פ מ\"ש בסי' בפי' זכר רב טובך יביעו דפי' רב טובך הו\"ע ריבוי היסודות, דטוב הוא בחי' יסוד וכמ\"ש אמרו צדיק כי טוב, להיות כי כל השפעה הוא מבחי' היסוד כו', וריבוי היסודות הוא ריבוי הצמצומים שהמשפיע משפיל ומצמצם א\"ע לצורך ההשפעה (שז\"ע שהיסוד נק' טוב שהוא מה שהמשפיע משפיל א\"ע להתקשר אל המקבל ולצמצם א\"ע לפ\"ע המקבל כו'). וכמו עד\"מ בהשפעת"],[3601330320,"השכל מהמשפיע אל המקבל שיש בזה כמה צמצומים, ובד\"כ הם ד' צמצומים, צמצום הא' להמציא האור השכל השייך אל המקבל, דהיינו שמאור שכל העצמי של המשפיע יהי' נמצא האור שכל השייך אל המקבל, וכידוע דהשכל העצמי של המשפיע אינו בערך המקבל כלל, ובכדי להמציא האור שכל השייך אל המקבל צריך לצמצם ולהעלים אור שכלו לגמרי ואז נמצא האור שכל השייך אל המקבל כו', וכאשר נמצא האור שכל הוא בבחי' נקודה לבד שא\"א להשפיע כך אל המקבל, ולא יהי' זה שום גילוי עדיין אל המקבל, כ\"א צריך לפרט הפרטים שבהנקודה ולהמציא ענינים במה להלביש הדברים באופן שיהי' מובן אל המקבל כו', וה\"ז צמצום ב' שהנקודה באה בריבוי פרטים כו', דבאמת מתעלם בזה האור כו' וכנודע, וכ\"ז הוא גבי המשפיע עצמו. ואח\"כ כשצריך לגלות ולהשפיע אל המקבל יש בזה ג\"כ ב' צמצומים, דהנה מה שמפרט הפרטים שבהנקודה ה\"ז במחשבה לעצמו עדיין שאינו שייך לדיבור, ובכדי להשפיע צריך לסדר הדברים איך להשפיע ולכלכל דבריו בכדי שיתקבל אל המקבל, שזהו ג\"כ צמצום לגבי כמו שחושב הענין לעצמו כו', וה\"ז בחי'\nדבור שבמח' השייך לדיבור כו', ואח\"כ כשמשפיע להמקבל זהו בחי' מעשה דהיינו מה שעקימת שפתיו הוי מעשה כו'. גם ב' הצמצומים שבהתגלות השכל הוא מה שמגלה לו תחלה השכל בכללות ואח\"כ מפרט ומבאר לו הפרטים כו'. וכן הוא למעלה בהשפעת האור מעצמות המאציל אל הנאצלים ריבוי צמצומים מאד ממדרי' למדרי' כו'. וכנודע בענין ט\"ו ווי\"ן דאמת ויציב שהן ט\"ו יסודות דבווין תתקטר כו', וגם כמש\"א אלף אלפי' ורבוא רבבות פעמים הטובות כו' שהן ריבוי הצמצומים בהשפלת והמשכת האור כו'. ובד\"כ הן ד' צמצומים דד' אותיות הוי', וכנודע דאותיות הוי' הן הבאת והמשכת האור שע\"י ד' צמצומים כו', וכמ\"ש במ\"א דבהמשכת הקו מאוא\"ס יש בזה שם הוי' דהיו\"ד דש' הוי' הוא ראשית המשכת הקו כמו שהוא למעלה מא\"ק, והה' הוא בבחי' א\"ק שזהו מה שבא בריבוי פרטים וכמא' צופה ומביט כו' והכל בהעלם עדיין כו', והוי\"ו הוא בחי' יצי' דכללות והה' הוא בחינת השטח דאצי' כו'. וגם למעלה מזה היו\"ד הוא בחי' נקודת הרשימו דנקודה זו כוללת כל מה שיתגלה בכללות ההשתל' כו', והה' הו\"ע הרל\"א שערים\nדעולם המלביש כו', והוי\"ו הוא התגלות הקו שאחר הצמצום המלביש והו\"ע ראשית הקו שלמעלה מא\"ק, והה' הוא בבחי' א\"ק כו' וכמ\"ש במ\"א. וכ\"ז הוא הצמצומים באופן המשכת האור כו', ולפי אופן ריבוי וגודל האור בעצם כן המה ריבוי הצמצומים כו', דכל שהאור גדול ונעלה ביותר צ\"ל צמצומים יותר בירידת והשפלת האור עד שיהי' בערך המקבל כו'. וז\"ע רב טובך שבהשפעת והמשכת האור מן המאציל יש בזה ריבוי יסודות עד שיהי' באפשר להתקבל כו'. אך מ\"ש זכר רב טובך כו' היינו רק הארה ואפס קצהו מבחי' רב טובך כו', דמלאכים דבי\"ע א\"א להם לקבל מבחי' ריבוי הטוב וההשפעה דאוא\"ס המאציל גם לאחר שבא בריבוי הצמצומים דיסודות כו', רק הארה לבד הוא שיכולים לקבל מה שנמשך להם מבחי' המל', שזהו מ\"ש אח\"כ וצדקתך ירננו בחי' צדק מלכותא קדישא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובשעה\"כ כ' מספר הימים במל', כי היא מגלה הימים עליונים, שיש שם מספר רק שאינו בבחי' הגבלה והתחלקות ובמל' הוא בבחי' הגבלה ועי\"ז הוא הגילוי, ויובן עפמ\"ש זכר רב טובך הן ריבוי היסודות שבמשפיע שהן ריבוי</span>"],[3601330321,"<b>הצמצומים</b>, ובכללות הן ד' צמצומים, כמו עד\"מ בהשפעת השכל, ולמעלה הן ד' אותיות הוי', יו\"ד ראשית הקו, הו\"ה בי\"ע הכללים, גם יו\"ד רשימה, ה' עולם המלביש, וא\"ו גילוי הקו, ה\"א א\"ק, והמלאכים מקבלים רק הארה לבד מהאור הבא ע\"י ריבוי הצמצומים דרב טובך בחי' צדק מלכותא קדישא.\nפה) <b>ומ\"ש</b> זכר רב טובך ל' זכרון לבד הוא עד\"מ אדם שסופר מספר עצום כמו יו\"ד רבבות עד\"מ שמתחיל לספור א' עד שמגיע למאה וממאה לאלף עד יו\"ד רבבות, ולפי שסופר א' א' עד שנמצאו ריבוי אחדים בסך יו\"ד רבבות יגדל מאד בעיני הסופר מספר זה כו', אך זהו דוקא כשסופר לעצמו, אבל כאשר כבר נודע לו המספר הכולל, וא\"צ רק להודיע המספר לזולתו, אז יאמר דרך קצרה יש כאן מספר יו\"ד רבבות. ועם היות שדבור זה כולל כל פרטי המספר וכשיספור לאחדים לא יהי' שום התחדשות בזה, מ\"מ אין זה הדבור שאומר יו\"ד רבבות בחי' מספר עצמי ואמיתי, כהמספר שסופר לאחדים שסופר מהות הדבר, ובהדבור שאומר מספר הכולל אין בזה מהות הדבר כו' והוא בבחי' קטנות לגבי הגדלת המספר, ורק כמו קריאת שם בלבד לזכרון דבר, וכמו שעושין סימן לזכרון איזה דבר גדול כו'. והנה יש התכללות המספר גם לעצמו, וכמו קודם שספר לאחדים יודע שיש כאן מספר יו\"ד רבבות עד\"מ, ואז הוא אדרבה בבחי' גדלות יותר ומה שסופר לאחדים הוא בבחי' קטנות לגבי הכלל כו', וכמו במח' שכל דבר הוא בבחי'\nהתכללות וכשבא לדבור נפרט הדבר בריבוי פרטים, הרי במח' ריבוי האור ביותר כו'. וכמו\"כ הוא בהכלל שקודם הפרט שיש בזה גדלות יותר, דמה שמפרט הדבר ה\"ז רק הגדלת המספר לבד, אבל הגדלת עצם הדבר (כמו הרצון והתענוג כו') הוא בהכלל ביותר כו', וזהו כמו שהוא לעצמו, אבל אל הזולת אדרבה המספר הכולל הוא בבחי' קטנות כו'. וכללות הכוונה בהמשל הוא שבין במספר הכולל ובין במספר המרובה יש בחי' קטנות וגדלות, דבמספר הכולל הנה הכלל שקודם להפרט הוא בבחי' גדלות שהוא עצמי יותר מהפרט גם כמו שהוא לעצמו ויש בו תענוג יותר, והכלל שאחר הפרט הוא בחי' קטנות בב' ענינים אלו, ומספר המרובה יש בו גדלות מה שסופר מהות הדבר, וקטנות שהוא רק הגדלת המספר לבד, דלגבי עצמו הכל הוא בבחי' גדלות, דמספר הכולל ה\"ה הכלל שקודם להפרט (היינו שלמעלה במעלתו מהפרט כנ\"ל), ומספר המרובה כשסופר לעצמו הוא בעצם מהות הדבר, ולגבי הזולת הכל בבחי' קטנות, דמספר הכולל הוא רק בדבור ואינו עצמי, וזהו שהוא למטה מהפרט כנ\"ל, ובא לאחר הפרט כו', ומספר המרובה אל הזולת הוא רק\nהגדלת המספר לא עצם מהות הדבר כו'. והענין למעלה הוא דהנה בחי' המספר דע\"ס העיקר הוא בבחי' הכלים, להיות דמספר הוא בחי' הגבלה כנ\"ל ע\"כ המספר הוא בבחי' ההתחלקות שע\"י הכלים כו' (ונודע דעיקר ההתגלות הוא ג\"כ ע\"י הכלים דוקא, והיינו ג\"כ מצד ההגבלה שהכלים מגבילים את האור ועי\"ז הוא ההתגלות כו', דכל דבר שאינו מוגבל ומצויר אינו בהתגלות, וכמו תהו דבר שמתהה בנ\"א מפני שאין בזה ציור עדיין כו', וכשבא בבחי' ציור והגבלה ה\"ה בבחי' התגלות כו', וכמו אשר יאמר עליו כי הוא זה דהיינו בציור דבר כך וכך והוא בחי' הגילוי כו', ובכלל ההגבלה הוא ג\"כ מה שבא האור בבחי' מציאות דבר כו', דכ\"ז הוא ע\"י הכלי וכמשנת\"ל דע\"ס דאורות הן בבחי' פשיטות וע\"י ההתלבשות בכלים נעשים בבחי' מציאות דבר"],[3601330322,"כמהות הכלים כו', וז\"ש הפרד\"ס שהמספר הוא הגבלת הדבר הנמנה וע\"י ההגבלה הוא מתגלה כו'), והכלים הן ג\"כ בבחי' גילוי ההעלם, דהגם שהן בבחי' מהות ומציאות דבר מ\"מ ה\"ה בבחי' אצי' כו' וכמ\"ש במ\"א. וזהו שהמספר הוא באצי', ומ\"מ מצד ההגבלה שבמספר עיקרו הוא הכלים כו', וזהו שהמספר הוא בבחי' מל' שהרי עיקר הכלים הן במל'. ואינו דומה הכלים דמל' לגבי הכלים שלמעלה מהמל', דעיקר ענין ההגבלה הוא בכלים דמל', אבל למעלה מהמל' הכלים אינם בבחי' הגבלה עדיין כו'. והענין דהכלים שלמעלה מהמל' הן בחי' גווני האור לבד דהיינו רק שמתארים את האור לא לפעול איזה דבר, וכמו מראה וגוון התפוח שמורה על הטעם לבד, אבל לא יש בזה איזה פעולה כו', וכמו\"כ הוא בהכלים דע\"ס שהן רק לתאר ואינן עדיין דבר בפ\"ע מהאור כו'. אבל הכלים דמל' הן לפעול דוקא וכמו פעולת ההתהוות כו', דכל פעולה היא חוץ לעצם כו'. והו\"ע צלם אלקי' ודמות אלקי', דאלקי' הוא בחי' הכלים, והכלים שלמעלה מהמל' הן בחי' צלם בחינת צורה עצמית עדיין, והכלים דמל' הן בחי' דמות כו' וכמ\"ש במ\"א.\n<b>ונמצא</b> דעיקר ההגבלה הוא בבחי' מל', וע\"כ עיקר ענין המספר הוא ג\"כ בבחי' מל' כו'. וגם במדרי' שלמעלה מבחי' המל' שייך בחי' המספר להיות שאצי' בכלל הוא בבחי' התלבשות אורות בכלים ובבחינת התחלקות כו', מ\"מ למעל' מבחי' מל' הוא התגלות האור יותר מהתגלות הכלים והמספר שבהם הוא בחי' מספר האורות (דבכללות ענין המספר הוא מצד נגיעת הכלים, אבל מ\"מ הרי העיקר הוא התגלות האור וע\"כ המספר הוא מספר האורות כו'), ובבחי' מל' העיקר הוא התגלות הכלים והמספר הוא מספר הכלים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וענין זכר רב טובך ל' זכרון הוא עד\"מ כשסופר מא' עד יו\"ד רבבות עד\"מ, הרי המספר הוא במהות הדבר, וכשאומר אח\"כ בדבור ל' מספר הכולל ה\"ז קטנות, אמנם מספר הכולל שקודם להפרט ה\"ה גדלות, והפרט הוא קטנות לגבי' כי הוא רק הגדלת הדבר, ולעצמו שניהם בבחי' גדלות, ולזולתו שניהם בבחי' קטנות, והדוגמא למעלה דהנה עיקר ענין המספר הוא בכלים, כי הכלים הן בחי' הגבלה, וע\"י הוא התגלות האור, ועיקר הכלים במל', והיינו כי בהט\"ס הכלים אינם דבר בפ\"ע מהאור, ובמל' הן דבר בפ\"ע, צלם ודמות, וע\"כ עיקר המספר במל', ובהט\"ס ג\"כ יש מספר אבל שם הוא מספר האורות (ע\"י נגיעת הכלים) ובמל' מספר הכלים.</span>\nפו) <b>והנה</b> ידוע מה שלפעמים המספר המועט הוא במדרי' העליונה דוקא כמו שהאחדים הן בכתר ואלפים ורבבות במל', ולפעמים בהיפך שהרבבות בכתר והאחדים במל', ההפרש הוא בין האורות והכלים שמצד הכלים כל שלמעלה יותר הן בבחי' מיעוט יותר וכל מה שיורד ונמשך מתרבים הכלים כו', ומצד האור כל מה שלמעלה יותר הוא בבחי' ריבוי יותר וכל מה שיורד ונמשך מתמעט האור כו' וכמשנ\"ת ג\"כ לעיל. אך אינו דומה בחי' הריבוי שבכלים להריבוי שבאורות דהריבוי שבכלים הוא בבחי' התחלקות ממש, אבל הריבוי שבאורות הרי אין זה בבחי' התחלקות כו', וכמו כשרבבות הן בכתר הרי הכל בבחי' אחדות והתכללות כו'. וזהו מה שבמל' הוא רק המספר הכולל שהוא בבחי' קטנות היינו בחי' מיעוט האור"],[3601330323,"כו', והוא בחי' הכלל שאחר הפרט ולמטה ממנו, והיינו שהפרט הוא ריבוי האורות דאצי', והן בחי' אורות עצמיים בחי' גילוי מן העצם כו', ובמל' הוא בחי' מיעוט האור, ואינו בחי' עצם האור כ\"א לפעול שהוא חוץ לעצם כו' וכנ\"ל פ' פ\"ה. ויש ג\"כ במספר המרובה שהוא בבחי' קטנות דהיינו הגדלת המספר לבד כנ\"ל, היינו בחי' ריבוי הכלים דבחי' מל' כו', וענין ריבוי הכלים דמל' ידוע שזהו עד\"מ הדבור שבא בריבוי אותיות לגבי מח' והאור הוא במיעוט כו'. אמנם הענין בעבודה י\"ל כמ\"ש במ\"א בענין העלאת מ\"ן דאורות והעלאת מ\"ן דכלים שהן ב' בחי' מס\"נ, הא' דנה\"א למס\"נ באחד שזהו העלאת מ\"ן דאורות כו', והב' מס\"נ דנה\"ב הו\"ע ובכל נפשך שזהו העלאת מ\"ן דכלים כו', והו\"ע ביטול היש כו', ובנשמות דבי\"ע עיקר העבודה הוא בהביטול דנה\"ב בבחי' ביטול היש כו' וכמ\"ש מזה בד\"ה יו\"ט של ר\"ה, תער\"ב, במא' המתחיל ויאמר כו' לך לך. וזהו דבבחי' מל' הוא בחי' ריבוי הכלים כו'. ובמדרי' שלמעלה מבחי' המל' בחי' מספר המרובה הוא מצד האור שהוא בבחי' ריבוי אור כו', והוא המספר בעצם\nהמהות היינו בהאור שהוא עצמי כו', ומצד הכלים הוא בבחי' מספר מועט בחי' מיעוט הכלים כו', והוא בחי' הכלל שקדם במעלה להפרט היינו בחי' פרטי הכלים דמל' כו', וכמו הדבור שהוא בחי' פרט לגבי מח' בחי' כלל, וידוע דכלים דאצי' הן בחי' מח', וכלים דמל' בחי' דבור כו' (והנה בחי' מספר האורות הוא ג\"כ מצד נגיעת הכלים כנ\"ל דלמע' מכלים אין שם מספר כו', וצ\"ל הענין בזה. דהנה יש בחי' פנימיות הכלים וחיצוניות הכלים, דפנימיות הכלים הגם שהן ג\"כ בחי' כלים ופועלים בהאור כו', מ\"מ אינם בבחי' הגבלה כ\"כ וההתגלות הוא מצד האור כו', וי\"ל שהו\"ע שם העצם שהוא התגלות העצם כמו שהוא כו', דודאי יש בזה ג\"כ מפעולת הכלים אך זהו בחי' פנימיות הכלים שההתגלות היא מ\"מ האור כמו שהוא כו', ולקמן פ' ית' דשם העצם הוא למעלה גם מבחי' פנימיות הכלים כו', ומ\"מ יש בזה נגיעת הכלי כו'. ומה שהכלים הן גווני האור זהו בחי' פנימיות הכלים כו', ועמ\"ש במ\"א בענין הג' מדרי' שבשמות שם העצם והתואר והפעולה כו'. ובחי' חיצוניות הכלים הוא שמגבילים האורות ובאים עי\"ז\nבבחי' מציאות דבר כו'. וב' מדרי' אלו הן בכל הע\"ס דאצי' רק שבמדרי' שלמעלה מבחי' המל' העיקר הוא בחי' פנימיות הכלים, וע\"כ מספר המרובה הוא בבחי' מספר האורות (ומובן ג\"כ דבחי' מספר האורות אינן בבחי' התחלקות כ\"כ ולא בבחי' התגלות כ\"כ, היינו שאינו בא בבחי' התלבשות כ\"כ כו', וכמו בשכליים עמוקים שאינו ניכר בהם כ\"כ ההגבלה וההתחלקות כו' וכמשנת\"ל (ד\"ה נשא) בענין שמאי והלל שקיבלו סברא א' ובא בהשגתם בהתחלקות שזהו מצד הפשיטות שבהסברא כו', וכמ\"ש במ\"א בענין שם העצם שזהו כמו וה' נתן חכמה לשלמה שהיא בחי' עצם החכ', דבנפש הוא התגלות המושכלות שמעצם כח חכמתו שבא בבחי' הפשטה לגמרי או בהתעלמות בלבוש שאינו בערך כלל וכמו משלי שלמה כו'), ומספר המועט הוא מצד בחי' חיצוניות הכלים שזהו בבחי' מיעוט במדרי' העליונות דאצי' כו'. ובבחי' מל' העיקר הוא בחי' חיצוניות הכלים, ובחי' פנימיות הכלים שבזה הוא התגלות האור הוא בבחי' מיעוט כו'. ובעבודה הוא ההפרש בין נשמות דאצי' לנשמות דבי\"ע דבנשמות דאצי' העיקר הוא העבודה שמצד הנה\"א למס\"נ\nבאחד בבחי' ביטול במציאות כו', ובנשמות דבי\"ע העיקר הוא העבודה שמצד הנה\"ב דהיינו מזה שהנה\"א עובד עבודתו לברר ולתקן את הנה\"ב בבחי' ביטול היש"],[3601330324,"כו'). וע\"פ הנ\"ל יובן מ\"ש והי' מספר בנ\"י כו' אשר לא יספר, דלכאו' א\"מ מה\"ע מספר אשר לא יספר, וע\"פ הנ\"ל יובן שז\"ע מספר האורות דהגם שיש בהם ג\"כ מספר מ\"מ ה\"ז לא יספר שאין זה בבחי' הגבלה והתחלקות ממש, דזהו בחי' פנימיות הכלים ופנימיות האור שאינם בבחי' התחלקות עדיין כו', וע\"ד מ\"ש ולתבונתו אין מספר, דממ\"ש אין מספר מובן ששייך שם מספר רק המספר הוא בבחי' אין מספר, דלהיות שלתבונתו הוא בחי' פנימיות ועצמות המוחין שלמע' מהמוחין שבמדות כמ\"ש בסי' ע\"פ זה, ושם הרי העיקר הוא האור שהמוחין נק' חיוהי כו', ע\"כ הוא בבחי' אין מספר כו'. גם ענין מספר אשר לא יספר הוא שנש\"י ממשיכים גם במספר שיהי' בבחי' לא יספר כו'. דהנה לפעמים כתיב ועלמות אין מספר דא\"ת עלמות אלא ועולמות שהעולמות יהיו בבחי' בלי מספר כו', והרי העולמות הן בבחי' מספר וגבול דשרשן מבחי' הכלים כו', אך נש\"י ממשיכים שיהיו גם העולמות בבחי' בלי מספר כו', והיינו ע\"י התורה דתורה היא בחי' ח\"ע בחי' חיוהי וע\"כ ע\"י עסק התורה למטה ממשיכים בחי' האור והגילוי בעולמות\nלהיות גילוי אוא\"ס בעולם כו'. וגם נודע שהתורה היא ממוצע בין אוא\"ס לעולמות ויש בה ב' המדרי' שהו\"ע אור ושלמה דתורה כו' וכמ\"ש במ\"א וית' לקמן, ולכן ע\"י התורה ממשיכים גילוי אוא\"ס בעולם ואז העולמות הן בבחי' אין מספר כו'. וז\"ש ששים המה מלכות אלו ששים מסכתות כו' ועלמות אין מספר א\"ת ועלמות אלא ועולמות כו', שע\"י התורה ממשיכים בעולמות גם בחי' בלי מספר כו'. וכן ממשיכים ע\"י התשובה, דהנה ענין המספר הוא בחי' התגלות כנ\"ל, וא\"כ במקום הסיתום אינו שייך מספר (ושם בחי' מספר אשר לא יספר כו'), והתשובה מגעת בבחי' הסתום ונעלם דוקא, וכמ\"ש ממעמקים קראתיך דענין התשובה בנפש הוא בעומק הנפש דוקא, וכן מגיע למעלה בבחי' עומק דוקא הסתום ונעלם כו', ולכן ע\"י התשובה נמשך ג\"כ בחי' בלי מספר במספר כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ביום השמיני עצרת כו', דהנה שמיני הוא בחי' בינה שהיא תמינאה מלמטלמ\"ע והוא בחי' פנימיות בינה וכמ\"ש בלק\"ת סד\"ה ביום השמע\"צ שמאלו תחת לראשי, והיינו בחי' לתבונתו אין מספר וכנ\"ל דתבונה הוא בחי' פנימיות ועצמות המוחין כו', ובמ\"א מבו' דלתבונתו הוא בחי' התבונה שבעצמות אוא\"ס ב\"ה כו'. וזהו ג\"כ ענין עצרת ל' קליטה דהקליטה היא בתבונה וכמ\"ש איש תבונות ידלנה כו' וכמ\"ש במ\"א, והוא ההמשכה שע\"י העבודה דר\"ה ויוהכ\"פ שהגילוי הוא בחה\"ס והעיקר בשמע\"צ, וכמ\"ש תקעו בחדש שופר בכסה ליום חגנו ולא כתי' לימי חגינו אלא ליום חגינו וקאי על שמע\"צ כו', שע\"י הקבעומ\"ש ותשובה דר\"ה ויו\"כ ממשיכים מבחי' עצמות אוא\"ס ב\"ה והגילוי בפנימיות הוא בשמע\"צ, והיינו שההמשכה היא בכחות הגלוים שבנפש ע\"י העבודה דכל השנה כו'. דהנה בר\"ה ויו\"כ העבודה היא בבחי' מקיפים דנפש, אבל בכל השנה העבודה היא בכחות הגלוים שבנפש כו'. ובשמע\"צ נמשך בפנימיות כל מה שמעוררים וממשיכים בר\"ה ויוהכ\"פ, והיינו שתהי' העבודה בכחות הפנימיים\nבמדרי' נעלות ביותר כו', והיינו ההמשכה דבחי' בלי מספר בבחי' מספר כו'. וזהו שהקרבן דשמע\"צ הוא פר א' כו', דהנה קרבן הוא בחי' מל' והו\"ע עליית המל' כו', ובימי החג הי' ריבוי פרים ובד\"כ זהו ההמשכה מבחי' חיצוניות המקיף שנמשך לכל"],[3601330325,"כו' וכנודע, אך בשמע\"צ הוא ההמשכה דבחי' פנימיות המקיף שנמשך רק לנש\"י כו'. והקרבן הוא פר א' איל א' שגם בבחי' מל' יהי' בחי' אחדות והתכללות שז\"ע שהמספר יהי' בבחי' אשר לא יספר כו'. וזהו בואו ונגלגל אני ואתה שההמשכה הוא רק לנש\"י וכמ\"ש יהיו לך לבדך ואין לזרים אתך כו'. וזהו ביום השמיני עצרת שנק' יום השמיני עם היותו רגל בפ\"ע לפי שהוא בחי' פנימיות בינה גילוי בחי' ולתבונתו אין מספר שנמשך בשמע\"צ בבחי' פנימיות כו'. ולכן הקרבן הוא פר א' דהיינו שגם המספר יהי' בבחי' אשר לא יספר כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וידוע דבאורות למעלה הוא בחי' ריבוי ולמטה בחי' מיעוט, ובכלים למעלה מיעוט ולמטה ריבוי, והריבוי שבאורות אינו בבחי' התחלקות (וכמו בשכליים עמוקים שאינו ניכר ההתחלקות), והריבוי שבכלים הוא בבחי' התחלקות, וזהו שלמעלה מהמל' הוא מספר האורות והוא בחי' ריבוי, ומצד הכלים הוא בחי' מיעוט, ובמל' הוא מספר הכלים שזהו הריבוי ומצד האור הוא בחי' מיעוט (ובעבודה הוא דנשמות דאצי' עיקר עבודתם בבחי' נשמתם, ונשמות דבי\"ע העיקר בתיקון דהנה\"ב ביטול היש למס\"נ באחד ובכל נפשך), וזהו מספר אשר לא יספר בהספי' שלמע' מהמל' וכמו ולתבונתו אין מספר, גם שע\"י תורה ותשובה ממשיכים שגם בעולמות יהי' בחי' אין מספר. ובזה יובן ענין שמע\"צ בחי' פנימיות בינה שיהי' הגילוי גם בכחות הגלוים, וזהו שהקרבן בחי' מל' הוא פר א' בחי' מספר אשר לא יספר.</span>"],[3601330326,"<h3>בס\"ד. ש\"פ נח, תער\"ג</h3>\n<b>צהר</b> תעשה לתיבה ואל אמה תכלנה מלמעלה, ופרש\"י צהר י\"א חלון וי\"א אבן טובה המאירה להם. וצ\"ל מה\"ע התיבה ומה ההפרש בין חלון לאבן טובה כו'. ובגמ' סנהדרין אי' אר\"י א\"ל הקב\"ה לנח קבע בה אבנים טובות ומרגליות שיהיו מאירים לכם כצהרים, מפרש צהר ל' צהרים, וצ\"ל מה\"ע שהתיבה תהי' מאירה כצהרים וע\"י מה ע\"י אב\"ט כו'. גם צ\"ל שייכות ענין ואל אמה תכלנה למ\"ש צהר תעשה כו', דלכאו' הול\"ל זה קודם גבי מדידת התיבה שאו' ושלשים אמה קומתה הול\"ל שם ואל אמה כו', וכשהפסיק במ\"ש צהר תעשה ואח\"כ אומר ואל אמה כו' משמע שהענינים שייכים זל\"ז וצ\"ל מהו השייכות. ולהבין כ\"ז ילה\"ק משנת\"ל דשם ספירה הוא לשון מספר ונת' דענין המספר הוא בכלים דע\"ס ועיקר המספר שהוא הגבלת דבר הוא במל' ששם עיקר הכלים כו', ושייך מספר גם במדרי' למעלה מהמל' והוא בחי' מספר האורות דהמספר בזה הוא בבחי' לא יספר ומספר הכלים הוא בבחי' מספר וגבול כו'."],[3601330327,"פז) <b>והנה</b> ב' בחי' מספר הנ\"ל שהן מספר האורות ומספר הכלים, זהו משארז\"ל בפ\"ק דביצה את שדרכו למנות שנינו או כל שדרכו למנות שנינו, דהנה בשל\"ה דשמ\"ז סע\"א הביא בשם מדרש רז\"ל בענין מה שנצטוו לספור את ישראל שהמנין והמספר גורם השראת השכינה כו', ולהבין זה איך שע\"י המספר דוקא יהי' השראת השכינה. הענין הוא דהנה ענין המספר הוא דבר חשוב דכל דבר שסופרים אותו ה\"ז מורה על חשיבות הדבר שזהו שאמרו את שדרכו למנות כו', הרי יש דברים שאין דרכן למנות והיינו דברים שאינם חשובים אין דרכן למנות ומה שמונים הוא מצד החשיבות כו', וכדאי' במדרש שה\"ש ע\"פ שררך אגן הסהר בענין בטנך ערימת חטים, מה החטים הללו כשיוצאין לזרע אין יוצאין אלא במנין וכשנכנסים לגורן אין נכנסין אלא במנין כך ישראל כשירדו למצרים ירדו במנין כו' וכשעלו עלו במנין כו', שזהו מצד החשיבות לכן מונין אותן כו', וכמו מונה מספר לכוכבים כו' וכתי' המוציא במספר צבאם כו' שכ\"ז הוא מצד החשיבות כו'. והחשיבות שבהם הוא מ\"ש אח\"ז מרוב אונים ואמיץ כח איש לא נעדר, ופי'\nהראב\"ע והרד\"ק איש מהכוכבים לא נעדר שכולם קיימים ועומדים ברום עולם משי\"ב ולא כמו הנבראים שבארץ שהם נפסדים כו', וכדאי' בירושלמי ע\"פ אלה תולדות כו' ביום הבראם שהן חזקים כיום הבראם כו', ונודע דמה שאינם נפסדים אינו מצד עצמן שהרי הם הווים וממילא צריכים להיות נפסדים כו', רק מפני שכך הוא רצון הבורא להיות נצחים שבזה נראה בחוש כח הא\"ס כו', שעז\"נ שם קודם לזה שאו מרום עיניכם וראו מי ברא אלה דבנבראים אלו נראה בחוש כח הא\"ס בבחי' ראיה חושיית ממש, שהרי א\"א שיהיו קיימים ונצחים מצ\"ע שה\"ה נבראים, וכל מציאותם הוא מהרכבתם, וא\"א להיות מציאותם מעצמן כ\"א מהבורא ומרכיב אותם כו', וכל המורכב סופו להפרד כו'. וא\"כ מה שהם קיימים זהו רק מכח הא\"ס המקיים אותם כו' וכמו שית' זה לקמן פ'. ובת\"ז אי' מרוב אונים דא כ\"ע ואמיץ כח דא חכ' כו', ולפי\"ז ענין מרוב אונים הוא ע\"ד כל אשר חפץ ה' עשה, דהיינו להיות המשכת בחי' חפץ ורצון ה' שזהו בחי' עצמיות אוא\"ס דבחי' הכתר גם בעשי' בנבראים שלמטה כו', וכנודע במ\"ש ואלקינו בשמים כל אשר חפץ\nכו', דפי' אלקינו בשמים זהו בחי' הגילוי אלקות שבעולמות עליונים שבזה הכל מודים, ורק בהגילוי למטה יש שמכחישים ר\"ל ואומרים אי' אלקיהם כו' (ובפרטיות הוא בהמשכת אוא\"ס שממשיכים ע\"י מצות מעשיות שז\"ע אי' אלקיהם שממשיכים ע\"י תומ\"צ כו', דמ\"ש ואלקינו בשמים קאי על עבודה רוחניות וכמו עבודת האבות שהיו בבחי' מרכבה שע\"ז הכל מודים שממשיכים עי\"ז גילוי אלקות כו', אבל על המשכת אלקות שע\"י מצות מעשיות ע\"ז שואלים אי' אלקיהם כו' וכמ\"ש במ\"א, ובד\"כ הוא על המשכת כח האוא\"ס בעולמות התחתונים). ועז\"א דכשם שאלקינו בשמים כמו\"כ כל אשר חפץ עשה בהמשכת כח הא\"ס גם בנבראים התחתונים, שזהו בחי' חפץ ה' בחי' הרצון שזהו בחי' כ\"ע שנמשך גם למטה כו'. וכ\"ז נראה ביותר בצבא מעלה דגם בנבראים שלמטה מה שקיימים במין זהו מכח הא\"ס שלא נכחד איזה מין לגמרי, אך ביותר הוא נראה בצבא מעלה בזה שקיימים באיש כו'. וז\"ע המוציא במספר צבאם שמצד החשיבות שלהם דאיש מהם לא נעדר לכן ה\"ה מוציא אותם במספר שזהו מורה על החשיבות כו', וענין מה שמוציא אותם במספר היינו ההשגחה העליונה בהם וכמו דבר חשוב שסופרים אותה הו\"ע שימת לב שמשים לבו"],[3601330328,"אל הדבר ההוא, כמו\"כ מה שמוציא אותם במספר הו\"ע ההשגחה כו'. ואף שבאמת השגחתו ית' היא על כל האישים ממש בכל פרטי מיני דצח\"ם גם בדומם היותר אחרון כו', עכ\"ז ודאי יש חילוקי מדרי' בענין ההשגחה, וכמ\"ש במד\"ר ע\"פ הנה אנכי שולח מלאך אלו זכיתם אני בעצמי כו' עכשיו אני מוסר אתכם לשליח כו', וכתי' בו כי שמי בקרבו שההשגחה היא מאתו ית' והמלאך הוא רק שליח בלבד ומ\"מ אינו כמו אני בעצמי כו', ולכן מרע\"ה לא רצה במלאך כו' וכמ\"ש במ\"א. וכמ\"ש ג\"כ גבי גאולת מצרים וישמע אלקים כו' וידע אלקים, ופי' רש\"י נתן עליהם לב ולא העלים עיניו הרי שלפעמים כבי' מעלים עיניו ר\"ל, וגם אז הוא ית' משגיח בהשגחה פרטיות שהרי ההשגחה האלקית הוא החיות של הנבראים וכמ\"ש בסש\"ב פמ\"ח, ואם ח\"ו לא תהי' ההשגחה יופסק החיות ח\"ו, אלא שבאמת השגחתו ית' תמיד על כל נברא ונברא בפרט כו', רק שזהו בהעלם שמתעלם ומסתתר ואין בההשגחה בחי' גילוי אור כו', ועתה נתן עליהם לב ולא העלים עיניו היינו להיות גילוי אלקות שז\"ע הגאולה כו'. ובד\"כ זהו ההשגחה דש' אלקים וההשגחה דש'\nהוי', דמצד ש' אלקים באה ההשגחה בריבוי העלמות והסתרים ע\"י ריבוי הממוצעים בהעלם אחר העלם עד שמלובש בלבוש שק דדרך הטבע ע\"י ע' שרים כו', ואע\"פ שהמה כגרזן ביד החוצב ממש שאין להם שום בחירה בההשפעה דכמצבי' עביד בחיל שמיא ומסדר אותם במשמרותיהם כרצונו דוקא, מ\"מ בא בהם בהתלבשות בהעלם גדול כו' (שזהו כל הכוונה בהתלבשות זאת בכדי שיתעלם האור והגילוי ולהיות השפעות גשמיים כו', וכמ\"ש במ\"א בענין וברכך ה' אלקיך בכל אשר תעשה שצ\"ל עשי' בכדי שתתגשם ההשפעה ותהי' בערך המקבל, דההשפעה היא מאת ה' רק שצ\"ל ע\"י התלבשות הממוצעים העליונים וע\"י הדברים הגשמיים למטה בכדי שתתגשם כו', וכנודע דבכ\"מ שהאור בגילוי הוא מיעוט הישות ובכדי שיהי' בבחי' יש צ\"ל התעלמות האור כו', וה\"ז רק בבחי' לבוש המעלים אבל העיקר היא ההשפעה אלקית כו', וע\"כ צ\"ל נתון ומסור בנפשו לאלקות והעסק הגשמי לא יהי' לו מניעה ועיכוב ולא יטריד ויבלבל אותו מתורה ותפילה, מאחר שזהו רק בדרך כלי ולבוש לבד והברכה היא מאת ה' כו'. ובהשגחה זאת דש' אלקים מתעלם האור בבחי'\nהעלם גדול מאד עד שאינו נראה ונגלה כלל, רק נש\"י יודעים ומשיגים אמיתית הדבר שהכל הוא השפעה אלקית כו', ובמ\"א מבו' דכאשר משים לבו ודעתו לזה יכול לראות בראי' חושיות ממש ההשגחה אלקית בהנהגת העולם כו'). אבל ההשגחה מש' הוי' הוא שבא בבחי' גילוי אור, וכמו בהשפעת לחם מן השמים שלא הי' בו פסולת, וכן בכל ההשפעות בבחי' דקות ורוחניות כו'. ובזה יש ג\"כ חילוקי מדרי' אם שבא עכ\"פ בבחי' לבוש להיות מזה השפעות גשמיים רק שהלבוש הוא ג\"כ לבוש דק שאינו מעלים על האור כו', או שבא האור בבחי' גילוי ממש להיות מזה ענין הגאולה כו'. ומ\"ש ביצי\"מ וידע אלקים היינו שההשגחה דש' הוי' בא בבחי' גילוי בשם אלקים בכדי להיות שכר ועונש שז\"ע נגוף ורפוא נגוף למצרים ורפוא לישראל כו', ועמ\"ש בתו\"א ד\"ה ארדה נא דרוה\"ב. וז\"ע המוציא במספר צבאם שהו\"ע ההשגחה עליהם מצד החשיבות כו'. וי\"ל שהרי ארז\"ל ע\"פ אף ידי יסדה כו' נטה ימינו וברא שמים נטה שמאלו וברא ארץ הרי בשמים הגילוי יותר כו', דכמו\"כ בצבא מעלה שבהם ההשגחה בבחי' גילוי יותר וזהו המוציא במספר כו', ומשו\"ז גופא המה קיימים באיש מצד יתרון הגילוי בהם כו'."],[3601330329,"<span data-k=\"ks\"><b>קיצור.</b> וב' בחי' מספר הנ\"ל הו\"ע את שדרכו למנות וכל שדרכו למנות, דאי' בשל\"ה דע\"י המספר הוא השראת השכינה, והענין כי מספר מורה על החשיבות, המוציא במספר צבאם והחשיבות דאיש לא נעדר והוא שכן רצון הבורא, ובזה נגלה כח הא\"ס, ובת\"ז מרוב אונים כ\"ע והו\"ע כל אשר חפץ ה' עשה גילוי א\"ס הבל\"ג בעשי' (וכן ע\"י מעהמ\"צ), והמספר הו\"ע ההשגחה, והיינו השגחת ש' הוי', דהשגחה דש' אלקים הוא הוא שמסתתר בלבושי' וברכך ה\"א בכל אשר תעשה, והשגחת ש' הוי' הוא בלא העלם, או בגילוי ממש כמו ביצי\"מ, ומ\"ש וידע אלקים בכדי שיהי' נגוף ורפוא.</span>\nפח) <b>וכמו\"כ</b> הוא ענין המנין והמספר בנש\"י שזהו ג\"כ מצד החשיבות וכדאי' במד\"ר פ' שמות פ\"א שקולים ישראל כצבא השמים כו', וכידוע דההשגחה על נש\"י היא מש' הוי' דוקא, שהרי הנשמה היא ג\"כ נצחיות כמו צבא מעלה כו', וסיבת נצחיות דנשמה היא למע' הרבה מסיבת הנצחיות דצבא מעלה שהן בעצם נבראים וקיומם הוא רק מכח הא\"ס שבהם, וג\"ז אינו בבחי' התלבשות בהם, וכידוע שא\"א שבעל גבול יהי' בו אור וחיות בלתי מוגבל כו', והכח הא\"ס שבהם הוא מחוץ להם שאינו מתייחד עמהם רק מקיים מציאותם כו' וכמ\"ש במ\"א. אבל הנשמות ה\"ה אלקות ממש בעצם מהותם, וכמא' נשמה שנתת בי טהורה היא דהיינו בשרשם באצי' וגם למעלה מאצי' וכידוע הפי' דטהורה היא בחי' טה\"ע כו' (ועם היות שבכ\"מ שרשם הוא מבחי' כח הגבול היינו בחי' גרמוהי בכ\"מ שמדברים בזה גם במדרי' שלפני הצמצום, שז\"ע מחשבתן של ישראל קדמה לכל דבר כו' וכמ\"ש במ\"א, דדבר הוא בחי' הצמצום ומחשבתן של ישראל קדמה כו' היינו בבחי' אותיות הרשימו שלפני הצמצום שזהו בחי' כח הגבול שבא\"ס כו'. מ\"מ ה\"ז בבחי' א\"ס\nממש כו', ובאגה\"ת פ\"ד כ' דנשמות שרשן מש' הוי' וכמ\"ש כי חלק הוי' עמו כו'), וגם כמו שבאה בבי\"ע שהיא בבחי' נברא ה\"ה ג\"כ אלקות ממש כנודע ומבואר במ\"א (והיינו מפני ששרשה הוא מפנימיות החיות כמש\"ש באגה\"ת, ע\"כ גם בירידתה לבי\"ע היא אלקות ממש כו'). ובד\"כ בריאת כל צבא מעלה הוא מבחי' הדבור וכמ\"ש בדבר ה' כו' וברוח פיו כו' ובריאת הנשמה הוא מבחי' מח' כו'. ונמצא דסיבת נצחיות הנשמה הוא מפני שהיא ממש אלקות דש' הוי' כו' (והיינו לפמ\"ש באגה\"ת הנ\"ל. וגם לפי המבו' בכ\"ד שהן מבחי' פנימיות הכלים היינו שהן חלק מבחי' הכלים וכמ\"ש בבה\"ז פנחס על מאה\"ז דרמ\"ט ע\"פ ובחודש הראשון, ועם שהנשמה היא רק חלק קטן מהכלים מ\"מ ה\"ה בחי' אלקות דכלים כמ\"ש בבה\"ז שם ובלקו\"ת בהבי' הב' דיונתי ובאגה\"ק סי' כ' אלא מעין בחי' אלקות בצמצום עצום וכעין הכלים די\"ס דאצי' כו' (ובהגהות לבה\"ז הנ\"ל שגם בהתהוותם בבי\"ע הן בחי' אלקות ממש), ובבה\"ז שם שהן מתאחדים עם הכלים כו' (ולכאו' צ\"ע והלא מבו' באגה\"ק הנ\"ל שכבר יצאו ונפרדו מהכלים כו', ובאמת בהכרח לומר שהן\nבבחי' דביקות דאל\"כ איך הן אלקות, ואין לומר שדביקותם הוא בבחי' התחדשות ממקורם בדרך רו\"ש כו' כמ\"ש במ\"א בענין החיות האלקי המחי' את הנבראים כו', דזה שייך רק בהארה לא בעצמי כו', וכאשר הנשמות הן בחי' דבר עצמי בהכרח לומר שהתאחדות שלהם היא בבחי' דביקות כו'. אלא צ\"ל דכמו שהכלים הוא שנתהוו בבחי' מהות דבר בפ\"ע ומ\"מ הן בבחי' דביקות רק שהוא"],[3601330330,"בבחי' דביקות שאינה ניכרת כו', כמו\"כ הנשמות מהכלים הן ג\"כ בבחי' דביקות הבלתי ניכרת כו' וזהו שיצאו ונפרדו כו' ומ\"מ הם בבחי' התאחדות ודביקות כו'. ולפ\"ז י\"ל דהנשמות גם שנעשו נשמות דבי\"ע הן בבחי' דביקות והתאחדות, דאל\"כ איך הן אלקות רק שהוא בבחי' דביקות הבלתי ניכרת כו', ומובן שהוא בבחי' העלם יותר מהנשמות דאצי' כו', ומ\"מ גם הם בבחי' דביקות כו'). וע\"כ הקיום שלהם הוא בבחי' קיום עצמי ולא כמו צבא מעלה דעם היות שהן חזקים כיום הבראם שזהו כמו קיום דבר הבלתי נפסד, מ\"מ הקיום שלהם אינו קיום עצמי רק מפני כח הא\"ס שבהם דהיינו רצון הבורא כו', אבל נשמות שהקיום שלהם הוא מצד ההתאחדות במקורם (אם בהאורות או בהכלים), ושמשום זה הן אלקות, הרי הקיום שלהם הוא קיום עצמי כו'. וכמ\"ש במ\"א בענין האור דהגם דמציאותו הוא מן המאור ומזה הוא קיומו כו', שהרי האור הוא גילוי רצוני דברצותו ית' מאיר וברצותו כו', ומ\"מ כ\"ז שהאור נמצא הוא בבחי' קיום עצמי דלהיות שהאור דבוק בהעצם ה\"ה מעין העצם וזהו שהוא בבחי' אור ובחי' אלקות, וע\"כ חיותו\nוקיומו הוא בבחי' חיות עצמי וקיום עצמי כו'. וכן הכלים הגם שאינם בבחי' דביקות היינו שאינם בבחי' דביקות ניכרת אבל באמת הן ג\"כ בבחי' דביקות מאחר שהן אצי' והן אלקות, וגם שהכלים הן בבחי' דביקות והתאחדות בהאור וכמא' איהו וגרמוהי חד כו' (וגם יתפרש איהו על שרש ומקור הכלים בחי' כח הגבול שבא\"ס והוא בד\"כ בחי' כח הא\"ס להוות דבר שחוץ לעצמותו כבי' וכמשית\"ל פ', וא\"כ איהו וגרמוהי חד הוא בהתאחדות במקורם כו'), וע\"כ גם הכלים הן בבחי' קיום עצמי כו'. וכמו\"כ הוא ג\"כ בנשמות שהן ג\"כ אלקות ממש ומתאחדים במקורם, ע\"כ הקיום שלהם הוא בבחי' קיום עצמי כו', וז\"ש הוא קיים ושמו קיים כו' ומבו' במ\"א שזהו בבחי' אורות וכלים כו', וי\"ל ג\"כ הוא קיים בחי' העצמות שהוא חי וקיים לעד שהרי מציאותו מעצמותו כו', ע\"כ ושמו קיים בבחי' קיום עצמי כאשר רצונו ית' הוא בבחי' גילוי אור כו', וכסאו נכון הוא בחי' הכלים ונשמות שהן ג\"כ בבחי' קיום עצמי כו'). וגם בירידת הנשמות למטה ה\"ה בבחי' קירוב ודביקות בשם הוי' ע\"י תורה ומצות, וכמ\"ש וירם קרן לעמו\nבחי' המשכה עצמיות דתורה ומצות ועי\"ז הם עם קרובו דקאי על שם הוי' כו' וכמ\"ש במ\"א, וכמ\"ש ואתם הדבקים בהוי' אלקיכם דאתם היינו גם כמו שמלובשים בגופים הרי הם דבקים בהוי' אלקיכם ע\"י תורה ומצות כו', וגם שאוא\"ס מאיר בהם בבחי' פנימית ממש בבחי' התאחדות ע\"י תורה ומצות כו'. וע\"י הנשמות נראה ונגלה ג\"כ אלקות בעולם, וכמ\"ש עדות לישראל שהן בחי' עדות על הנסתר בחי' אוא\"ס הסוכ\"ע כו' וכמ\"ש בלקו\"ת ד\"ה אלה פקודי שזהו בחי' ש' הוי' שיש בכאו\"א מישראל כו' ובפניהם הם ניכרים כו', ובפרט דנש\"י כל ענינם הוא להאיר את העולם כמשנת\"ל וית' לקמן בפרטיות. וע\"כ בנש\"י למטה ההשגחה עליהם היא משם הוי' דוקא כו', דבד\"כ ההנהגה עמהם אינו ע\"פ הטבע כ\"א משם הוי' שלמעלה מהטבע, ובזה יש ב' אופנים אם שההנהגה היא למעלה מהטבע לגמרי שזהו משם הוי' ממש, או בדרך נסים נסתרים שהוא ענין רוממות הטבע שזהו מבחי' רוממות הא\"ס שבמל' כמשנת\"ל (ד\"ה אני לדודי), והו\"ע שם הוי' המאיר בשם אלקים כו'. וזהו מ\"ש השל\"ה שע\"י המספר הוא השראת השכינה דהמספר הוא מצד החשיבות, דענין המספר בזה הוא ההשגחה בבחי' גילוי אור שז\"ע השראת השכינה כו'."],[3601330331,"<span data-k=\"ks\"><b>קיצור.</b> והנה הנשמות הן ג\"כ נצחיים, ומעלתם למעלה הרבה מצבא מעלה, כי הם בבחי' דביקות והן אלקות, וע\"כ הן נצחיים בבחי' קיום עצמי, וגם למטה ואתם הדבקים בה' ע\"י תומ\"צ, ואוא\"ס מאיר בהם בפנימיות, ועדות לישראל, וע\"כ עליהם ההשגחה מש' הוי' אם למעלה מהטבע או בחי' רוממות הטבע, וז\"ע המספר שעי\"ז הוא השראת השכינה.</span>\nפט) <b>והקשה</b> השל\"ה והלא לכאורה הוא להיפך שהרי אין הברכה מצוי' בדבר המדוד והמנוי כמשארז\"ל בפ\"ק דב\"מ, ותי' דע כי יש שני עניני מספר המספר של עניני עוה\"ז שהוא חומרי, וזה המספר אינו טוב כי מאחר שנספר כל פרטי לבדו אז הוא פירוד כו', וגם מורה שיש לו קץ ותכלית כו', אמנם המספר של השגת עוה\"ב זה המספר בלתי מספר ואין לו קץ וסוף ותכלית כו'. ובדשמ\"ח כ' שזהו מארז\"ל את שדרכו למנות שנינו או כל שדרכו למנות שנינו, דבחי' את שדרכו למנות ז\"ע המספר של עוה\"ב הנמשך מבחי' את היינו אותיות התורה מא' עד תי\"ו כו', וכל שדרכו למנות הו\"ע המספר דעוה\"ז כו'. ושרש ההפרש בין מספר דעוה\"ז ובין מספר דעוה\"ב הוא ע\"פ מארז\"ל שתי' קושי' דוהי' מספר על ולא יספר כאן בזמן שערש\"מ וכאן בזמן שאין ערש\"מ. והענין הוא דמספר עוה\"ז הוא דבר המדוד ומנוי ויש לו קצבה כו', אבל המספר דעוה\"ב הגם שהוא בבחי' מספר אבל אין לו קצבה. ע\"ד שארז\"ל ת\"ח אין להם מנוחה לא בעוה\"ז ולא בעוה\"ב שנא' ילכו מחיל אל חיל שהוא בחי' עליות המדרי' עד אין שעור כו', וכמ\"ש\nהשל\"ה שם שתמיד מתרבה והולך השגתם בו ית', והוא ית' אין תכלית להשגתו, נמצא תמיד המספר סופר והולך כו', ומ\"מ ההשגות הן בבחי' התחלקות שכל ענין ההשגה הוא שבא בפרטים דוקא כו', רק דבהשגה אלקית דעוה\"ב אין קץ ושיעור לריבוי ההשגות כו', דעכשיו גם בהשגה אלקית יש עכ\"פ קץ וגבול דעד פה תבוא כו', אך זהו לא מצד שהענין מוגבל בעצם כ\"א מצד עומק המושג וקוצר המשיג כו', אבל בההשגה האלקית שתהי' לעתיד לא יהי' קץ ושיעור כלל בההשגה כו', וכמו ולתבונתו אין מספר דמ\"מ ה\"ז בבחי' מספר, והיינו להיות שזהו בחי' תבונה והשגה רק שהפרטים הן בלי מספר כו' (וכנודע דכל שכל כשמגיע על עומקו יותר ה\"ה בא בריבוי פרטים ביותר כו', וגם הפרטים הם בלתי מוגבלים ומחולקים כ\"כ כו', וע\"כ בעומק ההשגה שתהי' לעתיד לא יהי' בזה מספר וגבול כלל כו', ובפרט שלעתיד תהי' ההשגה בבחי' מהות אלקות וכמו שית' בפ' וא\"כ תהי' כל השגה בבחי' א\"ס ממש כו'). וזהו ג\"כ ענין אין מספר מה שאינם בבחי' הגבלה כ\"כ כו', וזהו שארז\"ל שכאו\"א נכווה מחופתו של חבירו שהן מדרי' רבות עד\nאין שיעור כלל, וכאו\"א הוא דבר שבמנין שאין לו ביטול כלל להיותו דבר חשוב ונעלה כו'. וזהו שבזמן שאין ערש\"מ אז המספר ע\"ד המספר דעוה\"ז שיש קץ וגבול כו', ובזמן שערש\"מ אז הוא ע\"ד המספר דעוה\"ב, דעם היות שהוא בבחי' מספר מ\"מ אין קץ למספרו כו'. ויש לבאר זה בב' אופנים. דהנה נת\"ל (ד\"ה ביום השמע\"צ) דעיקר המספר הוא בבחי' הכלים ובפרט בבחי' המל', והיינו שהכלים הם בבחי' מספר וגבול כו', והנה הכלים ה\"ה ג\"כ בבחי' גילוי ההעלם (והיינו לגבי בחינת הכלים דא\"ק שע\"ז שייך לומר גם בהכלים דאצי' בחי' אדם אדמה לעליון כו' וכמ\"ש במ\"א, ולגבי שרשן באוא\"ס שלפני הצמצום דהיינו בחי' אותיות הרשימו כו', הגם שנת\"ל (ד\"ה ויחן) די\"ל שהן באין"],[3601330332,"ערוך לגמרי כו', מ\"מ הרי כ' בע\"ח שע\"א ע\"ב בהג\"ה וסוף ענ\"ג דע\"י הצמצום נתגלה ונתהווה מציאות הכלים כו', והיינו דעם היות שהן באין ערוך לפי שנעשו בבחי' מציאות דבר, מ\"מ אין זה כמו אין ערוך דבי\"ע שהרי הן אלקות ממש והן בחי' אצי' כו', וע\"כ או' בהם ל' נתגלה ונתהווה כו' וכמ\"ש במ\"א), וע\"כ מצד מה שיש בהמספר בחי' כח המספר שסופר את המספר אין בהמספר בחי' גבול כלל כו'. דז\"ע מה שהע\"ס דאצי' אין סוף להתפשטותן שזהו מצד הכלים ג\"כ, דעם היות כ\"א בבחי' הגבלה בחי' חכ' וחסד כו', ומ\"מ החסד גופא הוא בבחי' בלי גבול כו', דלהיות שהוא בחי' הגבול שבא\"ס יש בו כח הא\"ס כו', והוא מה שיש בהכלים משרשם ומקורם בחי' כח הגבול שבא\"ס שהוא א\"ס ממש כמו כח הבלי גבול כו'. וז\"ע המספר דעוה\"ב שהוא בלי מספר שזהו מצד כח המספר שבהמספר כו'. והאופן הב' הוא דהמספר דעוה\"ב הוא מבחי' האורות שנת\"ל דמספר האורות הוא בבחי' בלי מספר ובפרט מצד דביקות האור בשרשו ומקורו ה\"ה בבחי' בלי גבול, וע\"כ המספר הוא בבחי' בלי מספר כו'. ובזמן שערש\"מ ממשיכים גם במספר\nמבחי' בלי מספר וכמשנת\"ל שזהו ע\"י התורה וע\"י תשובה כו', ואז גם המספר דעוה\"ז הוא בבחי' לא יספר כמו המספר דעוה\"ב כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והקשה השל\"ה והלא הברכה היא בדבר הסמוי מהעין, נת' דמספר עוה\"ז הוא לא טוב, ומספר עוה\"ב הו\"ע את שדרכו למנות אותיות התורה, והוא מספר אשר לא יספר, כי אין המספר לההשגות גם עכשיו ולעתיד יהי' בבחי' בל\"ג, וכמו לתבונתו אין מספר וגם שהוא בבחי' השגות מחולקות, והענין דהנה נת' דעיקר המספר הוא בכלים, וכלים דאצי' הן בלי מספר מצד כח המספר שבהם, וגם י\"ל שזהו בחי' מספר האורות שהוא בלי מספר, וכשעושין רש\"מ ממשיכים במספר מבחי' בלי מספר.</span>\nצ) <b>אמנם</b> להבין מ\"ש השל\"ה דאת שדרכו למנות הוא המספר דעוה\"ב וכל שדרכו למנות זהו המספר דעוה\"ז, וגם אינו מובן והלא כתי' כי כל בשמים ובארץ דאחיד בשמיא ובארעא כו', דכל הוא בחי' יסוד המקשר ומחבר כו' ואיך הוא המספר דעוה\"ז כו'. הענין הוא עפמ\"ש יוצר אור כו' ובורא רע וארז\"ל ברכות די\"א ע\"ב כתיב רע וקרינן הכל (היינו מה שאנו אומרים בברכת יוצר ובורא את הכל) לישנא מעליא, הרי כינו את רע בשם הכל שהוא כל, וכ\"מ ברבות אחרי ר\"פ כ\"ב ע\"פ ויתרון ארץ בכל אפי' דברים שאתה רואה מיותרין בעולם כגון זבובים פרעושים ויתושין אף הם בכלל ברייתו ש\"ע דכתיב ויכולו השמים, הרי גם יתושים (שמכניסים ואינם מוציאים שהו\"ע הסט\"א כו' כמ\"ש במ\"א) נק' בכל, והרמ\"ק כ' בכוונת ומלכותו בכל משלה דהיינו גם על הקלי' וסט\"א כו', הרי דבכל כולל הכל כו'. וי\"ל עפמ\"ש במ\"א דמהיסוד יש ב' מיני שפע, הא' מבחי' הימין שנמשך רק למקום הראוי והוא בחי' השפעה פנימית ועצמית כו', והב' מצד השמאל שנמשך שפע המותרות לחיצונים כו', וזהו מה שכל כולל הכל, דכל הוא\nבחי' יסוד דמבחי' השמאל נמשך לכל כו', גם י\"ל ע\"פ מ\"ש בלק\"ת סד\"ה כי ההרים ימושו ההפרש בין כי כל בשמים ובארץ למ\"ש וברית שלומי לא תמוט, דכי כל הוא ההמשכה שע\"פ סדר ההשתל' שמתמעט ממדרי' למדרי', אבל וברית שלומי לא"],[3601330333,"תמוט הוא שנמשך בחי' גילוי אור ממש למטה כו'. וזהו דבחי' כל הוא המספר דעוה\"ז שמתמעט האור ובא בבחי' הגבלה ובבחי' כמה העלמות והסתירים עד שנמשך קצת שפע גם לחיצונים כו', משא\"כ בחינת וברית שלומי שנמשך גילוי אור אין שם שום אחיזה ונמשך רק למקום הראוי כו'. וזהו ג\"כ מ\"ש יראו מה' כל הארץ, כל הארץ דוקא אף מבחי' כל שדרכו למנות שאפי' המזיקים יריאים מהשי\"ת וכמארז\"ל אלמלא ניתנה רשות לעין לראות כו', ואעפ\"כ אין עושים כלום מפני מורא שמים עד שלא יוכל לעבור את פי ה' כו', דעם היות שיש להם אחיזה מ\"מ נמשך משם גם בחי' היראה עליהם כו'. אך יראה זו היא יראת העונש לבד כו', ובד\"כ מ\"ש יראו מה' היא בחי' יר\"ת שהיא מרחוק וזהו מה' כו', וצ\"ל יראו את ה' קדושיו בבחי' ביטול ממש שזהו פי' את הוי' להיות בבחי' את הטפל ממש לש' הוי' שלא להיות שום רצון בפ\"ע כלל כו', וז\"ע את שדרכו למנות בבחי' את הטפל ובטל כו'. ובד\"כ זהו בחי' מספר האורות ומספר הכלים דמספר האורות זהו בחי' את שדרכו למנות דהאורות הן בבחי' דביקות, והביטול הוא בבחי' ביטול\nבמציאות כו', וכן בעבודה הו\"ע למס\"נ באחד להיות בבחי' ביטול במציאות ממש כו' כמשנת\"ל. וזהו ג\"כ ענין המספר דעוה\"ב דאין זולתך מלכנו לחיי עוה\"ב שזהו בבחי' האור שדבוק במקורו כו' וכמ\"ש במ\"א, ומספר הכלים זהו בחי' כל שדרכו למנות דהכלים הן בבחי' מספר וגבול ומזה נמשך ההגבלה למטה עד שיכול להיות אחיזה כו'. ונת\"ל דבעבודה ענין ריבוי הכלים הוא הבירור ותיקון דנה\"ב בבחי' כפי' וביטול היש כו', וע\"י הכפי' וביטול דחומריות הנה\"ב שעי\"ז נעשה תיקון הכלים, ממשיכים עי\"ז מבחי' שרש ומקור הכלים בחי' כח הגבול היינו בחי' המספר את המספר שעי\"ז יהי' גם המספר בבחי' בל\"ג ולא יש אחיזה לחיצונים כו'. ובמ\"א מבואר דע\"י תיקון הכלים נמשך מבחי' האור שלמעלה מהכלים שמאיר בגילוי תוך הכלים כו', ועי\"ז הוא בבחי' מספר אשר לא יספר כו' וכנ\"ל.\n<b>ועפ\"ז</b> יובן מ\"ש צהר תעשה לתיבה, דהנה ידוע בשם הבעש\"ט דתיבה הו\"ע תיבות התפלה, וארז\"ל מט\"ט קושר כתרים לקונו מתפלותיהן של ישראל, דכתר הוא בחי' רצון והיינו המשכת רצון חדש להיות גאולה ורפואה כו'. והנה הכתר עשוי מאבנים טובים, וידוע דאבנים הן אותיות וכמא' שתי אבנים כו', וצ\"ל אבנים טובים ומאירים והוא ע\"י בירור ותיקון הנה\"ב שזהו כל ענין התפלה לברר את הנה\"ב, וע\"ז נסדר סדר התפלה בפסוד\"ז וברכות ק\"ש, דפסוד\"ז היא לזמר עריצים שע\"י ההילולים ותשבחות נעשה חקיקה מבחוץ שיוצא הנה\"ב מחומריות הרע כו', ואח\"כ בברכות ק\"ש בהתבוננות ביטול המלאכים נעשה החקיקה בפנים להיות בבחי' כלי לאלקות והוא ענין ואהבת כו' בכל לבבך בשני יצריך כו' וכמ\"ש במ\"א, וע\"י תיקון ובירור הנה\"ב שבתפלה האותיות דתפלה הן אבנים טובים ומאירים שנעשה עי\"ז כתר לקונו בחי' המשכת רצון חדש כו'. וזהו צהר תעשה לתיבה אבן טוב דתיבות התפלה יהיו בבחי' אבן טוב המאיר כו', והאור הוא כצהרים היינו כנ\"ל שע\"י בירור נה\"ב שנעשה עי\"ז תיקון הכלים למעלה נמשך\nמבחי' האור שלמעלה מהכלים כו', וז\"ע צהרים הנקרא טיהרא והוא גילוי בחי' עצמות אוא\"ס וכמ\"ש במ\"ע בענין אוכם הוא קדם עה\"ע ע\"ד שרגא בטיהרא כו'. ובספר נועם אלימלך אי' בפי' צהר תעשה לתיבה שע\"י תיבות התפלה נהפך צירוף צרה לצירוף צהר,"],[3601330334,"והענין הוא דמהמספר דעוה\"ז להיות שבא בבחי' מספר וגבול ובהעלמות והסתירים יכול להיות ח\"ו צירוף צרה ר\"ל, אך ע\"י שפועל בעצמו ומקבל עליו כפי' בחומריות הנה\"ב שלו ממשיכים עי\"ז מבחי' בלי מספר במספר, והיינו שהמספר דעוה\"ז הוא ג\"כ כמו המספר דעוה\"ב כו', ועי\"ז נהפך צירוף צרה לצירוף צהר שהוא בחי' גילוי אור כו'. ומ\"ש בפרש\"י י\"א חלון זהו מ\"ש בע\"ח דאוא\"ס מאיר בכו\"ח כו' ובז\"א דרך חלון כו', והיינו שהאוא\"ס שלמעלה מהשתל' מאיר בכו\"ח בבחי' קירוב כו', ובז\"א בדרך חלון כו' וכמ\"ש במ\"א. והענין בתפלה הוא כמ\"ש קרוב ה' כו' לכל אשר יקראוהו באמת, ומבואר במ\"א שזהו המס\"נ באחד בק\"ש שע\"י הקדמת למס\"נ באחד ואה\"ר דבכל מאדך ממשיכים גילוי אוא\"ס בתפלה שזה ענין ברוך אתה הוי' כו', והיינו בעבודת הצדיקים שממשיכים רצון חדש בתפלה על ידי הקדמת המס\"נ באחד שזה ענין מספר דעוה\"ב את שדרכו למנות כו' כנ\"ל, וזהו צהר תעשה בחי' חלון להיות גילוי אוא\"ס ב\"ה ע\"י העבודה דמס\"נ כו'. וי\"א צהר אבן טוב הוא שהגילוי דאוא\"ס ב\"ה הוא ע\"י כפיית החומריות דנה\"ב\nכו'. וזהו ג\"כ מ\"ש ואל אמה תכלינה פי' אמה הוא ענין אחת היא יונתי שהוא ענין למס\"נ באחד כו', גם ענין ואל אמה תכלינה הוא ענין מיעוט הכלים היינו שהכלים יהיו בבחינת מיעוט וביטול שעי\"ז מאיר בהם ריבוי אור כו'. וכמו בעקודים שהי' כלי א' ולא הי' שבירה ח\"ו מפני שהכלי היא בבחי' אחד כו', וזה ענין מיעוט הכלים שיקבלו ריבוי האור כו', והיינו הנעשה ע\"י בירור הנה\"ב שהוא ענין ביטול הכלים שעי\"ז מאיר גילוי אוא\"ס ב\"ה. וזהו צהר תעשה לתיבה שאותיות התפלה יהיו בבחי' אבן טוב המאיר ע\"י כפיית החומריות דנה\"ב, וזהו ואל אמה תכלינה שיהיו הכלים בבחי' מיעוט וביטול ועי\"ז נמשך גילוי אוא\"ס למטה להיות המספר דעוה\"ז ג\"כ בבחי' מספר אשר לא יספר כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ומ\"ש השל\"ה דכל שדרכו הוא מספר עוה\"ז, והלא כל הוא בחי' יסוד, הענין הוא כדכתי' רע וקרינן הכל, דמצד השמאל נמשך לחיצונים, וגם דהשפעת היסוד הולך ומתמעט, וזהו יראו מה' כל הארץ, אבל יראו את ה' את הטפל הו\"ע את שדרכו למנות, והוא מספר האורות בחי' דביקות, ובעבודה למס\"נ באחד, ומספר הכלים משם ההגבלה ואחיזה, ובעבודה תיקון הנה\"ב, ועי\"ז מספר אשר לא יספר גילוי שרש הכלים וגם המשכת עצם האור. ובזה יובן מ\"ש צהר תעשה לתיבה אותיות התפלה ע\"י בירור הנה\"ב הן בחי' אב\"ט המאיר משרשן ומקורן, וי\"א חלון הוא עבודת הצדיקים שממשיכים עצם האור ועי\"ז הוא בלי מספר, ואל אמה תכלינה בחי' אחת היא יונתי, וגם מיעוט הכלים וביטולם.</span>"],[3601330335,"<h3>בס\"ד. ש\"פ וירא, תער\"ג</h3>\n<b>והוא</b> עומד עליהם תחת העץ ויאכלו, ואי' בגמ' קדושין דל\"ב ע\"ב מעשה בר\"א ור\"י ור\"צ שהיו מסובין במשתה בנו של רבן גמליאל והי' ר\"ג עומד ומשקה כו', אר\"א לר\"י מה לך יהושע שאנחנו יושבים ור\"ג עומד, והשיב לו ממ\"ש גבי אאע\"ה והוא עומד עליהם כו', משמע מזה שהעמידה מה שעומד ומשמש הוא ענין בפ\"ע לבד מה שמאכיל ומשקה, וא\"כ בהחסד שעשה אברהם עם המלאכים הי' ב' ענינים דלבד מה שהאכילם הי' עוד מה שעמד עליהם שזהו דבר בפ\"ע, וצ\"ל מהו ב' ענינים אלו. גם צ\"ל דמ\"ש תחת העץ הוא לכאו' מיותר שהרי כבר נא' והשענו תחת העץ, והול\"ל כאן והוא עומד עליהם ויאכלו, ולמה נא' עוד הפעם תחת העץ. ולהבין כ\"ז ילה\"ק משנת\"ל דשם ספירה הוא ל' מספר, ונת' שהוא בבחי' הכלים דמספר הוא הגבלה דשייך בבחי' הכלים, ולהיות דמספר אינו התחדשות כ\"א גילוי ההעלם הוא בכלים דאצי' שהן בבחי' גילוי ההעלם כו', ונת' דעיקר ענין המספר שהוא הגבלת דבר הוא בבחי' מל', ולמעלה מהמל' אינו שייך מספר שהוא הגבלה כ\"א מספר האורות שהוא בחי' מספר אשר לא יספר כו'. ונת' שזה ענין\nאת שדרכו למנות וכל שדרכו למנות שזהו מספר האורות ומספר הכלים כו', ושע\"י תורה ותשובה ממשיכים בחי' לא מספר במספר דהיינו שגם המספר דעוה\"ז יהי' בבחי' אשר לא יספר כו'.\nצא) <b>והפי'</b> הב' בספירות הוא ל' סיפור והגדה וכמ\"ש הפרד\"ס שם בשם הרש\"ט וזה לשונו בבהיר מצאתי אמאי אקרי ספירות משום השמים מספרים כבוד אל, והכוונה כמו שהדבור והמכתב יבאר בהגבלתו להיות מורגש הדברים הנעלמים בתוך מחשבת החכם כן השמים מורים על השי\"ת, שכן הספירות הם מגלות המחשבות הנעלמות כו', וכ' הפרד\"ס ע\"ז שהספירות מספרות ומגבילות את הבלתי מוגבל כו'. והענין הוא דכמו שהדבור הוא גילוי המח' שהמח' היא בהעלם דכשאדם חושב אינו יודעים מה הוא חושב והדבור מגלה העלם המח' כו', וכידוע בענין ולכבודי בראתיו יצרתיו דבריאה הוא בחי' חשך והעלם, ויצי' הוא בחי' גילוי ההעלם דבריאה כו', שהמח' שהיא בחי' בריאה היא בבחי' העלם עדיין ונק' בורא חשך, וסיבת ההעלם דמח' הוא מפני שהאותיות דשם אינם בבחי' מציאות עדיין, עם היות שיש שם אותיות אינן בבחי' מציאות עדיין להיות בבחי' גילוי אל הזולת, ובדבור האותיות הן בבחי' מציאות עד שמורגשים אל הזולת כו', והרי העלם המחשבה מתגלה ממש ע\"י הדבור כו', כן הע\"ס דאצי' שהן בחי' הכלים הם\nמגלים העלם האורות עליונים שבלתי הכלים הרי האורות מצ\"ע לא יהיו בבחי' המשכה ולא בבחי' התגלות כו', וע\"י הכלים נמשכים ומתגלים למטה כו'. והענין דהנה ידוע דטבע האורות הוא להיות בבחי' הסתלקות למעלה כו', וכמו עד\"מ בכחות הנפש אנו רואים שכל כח ואור שהוא עליון במדרי' ה\"ה בבחינת התעלמות ועלי', וכל כח שלמטה במדרי' ה\"ה בבחי' התגלות והמשכה. וכמו בשכל ומדות הרי המדות הן בבחי' יציאה והתגלות, שא\"א להיות מדות בהתעלמות שהרי הם התעוררות והתפעלות באיזה דבר, וא\"כ ה\"ה בבחי' יציאה והתגלות כו', ולכן נמשלים המדות באברים חיצונים כמו חסד דרועא ימינא כו', שהן איברים הבולטים ויוצאים מהגוף"],[3601330336,"שכן ענין המדות שהן בבחי' בליטה והתגלות כו', וענין המדות הוא שנמשך לדבר שלמטה ממנו, דבד\"כ המדות הן בחי' שפלות בנפש דהיינו שמשפילים אותו ממהות העצמי כו', ופעולת המדות א\"א בלי זולת, והיינו שפעולתם הוא בהתגלות ובהמשכה לאיזה דבר כו', משא\"כ המוחין אינם בבחי' התגלות היינו שאינם בבחי' יציאה והתגלות כ\"א בבחי' העלם בעצמו כו', ואדרבה המוחין פועלים התעלמות גם בשארי הכחות, וכמו כל רוחו יוציא כסיל והחכם בכחו לעצור בעצמו ולהסתיר עניניו כו', וענין המוחין הוא שמקשר א\"ע לדבר שלמעלה ממנו שז\"ע המוחין להבין מה שלמעלה ולקשר ולדבק עצמו לזה כו', ופעולת המוחין אינו לזולתו כ\"א לעצמו כנודע, ומוחין דגדלות טבעם בבחי' הבדלה דוקא כידוע ומבו' במ\"א, הרי כל כח שהוא אור עליון יותר טבעו הוא בבחי' התעלמות ועלי' כו'. וכמו\"כ טבע האור למעלה הוא בבחי' עלי' והסתלקות כו' (ויצדק המשל דמוחין ומדות על האורות וכלים לפי מה שפי' בע\"ח דחיוהי הוא בחי' המוחין וגרמוהי בחי' הכלים, ומבו' במ\"א דגם מה שפי' רבינו ז\"ל דחיוהי הן האורות וגרמוהי\nכלים ה\"ז מתאים עם מ\"ש בע\"ח, כי המוחין עיקרן בחי' אור, ומדות עיקרם בחי' כלים כו'). וז\"ש כי ה' אלקיך אש אוכלה כמו טבע האש לעלות למעלה להכלל באש היסודי שזהו מצד הדקות שבו לכן יש בו טבע העלי' כו', דכל היסודות הם חומריים ומשו\"ז יש בהם טבע הירידה למטה כו', משא\"כ האש הוא מציאות דק ורוחני והוא בבחי' קירוב הערך אל מקורו וכאלו נא' שנרגש בו מקורו כו', ע\"כ יש בו טבע העלי' לעלות וליכלל בשרשו ומקורו, רק כשיש דבר הנאחז כמו שמן ופתילה ה\"ה נאחז בהם למטה כו', דהיינו כשיש דבר המקבל את האש ומתפעל ממנו להיות נשרף ונכלה בהאש ה\"ה יורד ונמשך למטה כו', וגם אז אינו נח בהפתילה כ\"א מתנענע תמיד למעלה, שאור האש חפץ בטבע ליפרד מהפתילה ולידבק בשרשו למעלה ביסוד האש הכללי כו' וכמ\"ש בסש\"ב פי\"ט. וכמו\"כ הוא הדוגמא בבחי' האור למעלה להיות שהוא בחי' הארה לבד שהרי אין העצמי נמשך ומתפשט כ\"א הארתו לבד כו', ולהיות שהוא בבחי' דביקות במקורו (שזהו כל ענין האור שהוא דבוק במקורו כנודע) ונרגש בו מקורו, לכן הוא בבחי' עלי' והסתלקות\nבמקורו, ולא להיות בבחי' ירידה והמשכה למטה שבזה הוא מתרחק ממקורו, כ\"א כל תשוקתו הוא להיות כלול במקורו כו' (וכמשית\"ל באורך), ורק ע\"י הכלים שהן דבר שנאחז בהם האור עי\"ז דוקא בא האור בבחי' ירידה והמשכה להיות למטה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> פי' הב' בספי' מהרש\"ט ל' סיפור שהן מגלות המחשבות הנעלמות, וכ' הפרדס שהן מספרות ומגבילות הבלתי מוגבל, וכמו הדבור שמגלה המח', כן הכלים מגלים האור, כי לולא הכלי הרי טבע האור לעלות דכל כח ואור עליון הוא בבחי' עלי', וכמו שכל ומדות, המדות הן התגלות והמשכה לדבר שלמטה ממנו, והשכל הוא בבחי' עלי' ודביקות בדבר שלמעלה ממנו, וכמו טבע האש לעלות מפני הקירוב למקורו, כמו\"כ האור להיותו הארה הדבוקה במקורה, ה\"ה בבחי' עלי' והסתלקות, וע\"י הכלים הוא בבחי' ירידה והמשכה.</span>\nצב) <b>וראי'</b> לזה שהרי בעולם התהו שהי' מיעוט הכלים, והיינו שלא היו כלים ראוים שיאחז ויתיישב בהם האור כו', הרי הי' השבירה מצד זה"],[3601330337,"שהאור נסתלק למעלה והכלים נשברו ונפלו למטה כו'. והגם דהאור דתהו הי' בבחי' ריבוי שלא הי' באפשרי להתיישב בכלי כו' כנודע, הנה זהו ג\"כ מצד הכלי דלהיות דהמשכת האור הוא ע\"י הכלי, שאין האור יורד ונמשך מצ\"ע כ\"א ע\"י הכלי דוקא, ממילא נמשך האור כפי אופן הכלי, והכלים דתהו להיותם בבחי' כלים עכ\"פ המשיכו ג\"כ את האור, רק להיותם כלים קטנים שאינם ראוים לקבל אור שיהי' בבחי' התיישבות המשיכו את האור באופן כזה שא\"א להתיישב כו', ולהיות הכוונה היא להיות המשכת האור וכמ\"ש לא לתהו בראה אלא לשבת יצרה כו', לזאת נתחדש בתיקון להיות ריבוי הכלים היינו שיהיו הכלים באופן כזה שיהיו ראוים שיאחז ויתיישב בהם האור כו' (וכידוע דריבוי הכלים דתיקון הוא מצד הביטול דוקא, שז\"ע מה שכל מדה נחלקת לכמה פרטים, וכמו שהחסד יהי' בו גם בחי' הגבו', וכן הגבו' יהי' בה בחי' החסד, שיש בזה ריבוי התחלקות פרטים, ועי\"ז יהי' התאחדות דחו\"ג כו', שכ\"ז הוא מצד הביטול שלא להיות בבחי' מדה וקו א' כ\"א יהי' כלול גם מהמדה ההפכית כו', והביטול הזה במדות הוא\nמהמוחין שהם בבחי' ביטול שזהו כל ענין המוחין להיות בבחי' הביטול דוקא, דענין הישות הוא היפך המוחין האמיתים וכמא' כל גיא שוטה, ואמיתית המוחין הוא להיות בבחי' ביטול דוקא, וזהו לפי שענין המוחין הוא שמבין ומשיג מה שלמעלה ממנו ה\"ז פועל בחי' ביטול בנפש כו' (והמוחין דסט\"א הן בבחי' ישות וכמ\"ש ראיתי איש חכם בעיניו כו', וכידוע בענין כהן און כו', אבל בקדושה ענין המוחין הן בחי' ביטול דוקא כו', וי\"ל לפי שהמוחין דקדושה הן כלים להענין המובן המושג שנרגש הענין המושג וע\"כ הם בבחי' ביטול, דהרי הביטול הוא מהענין המושג במוחו (שזהו למעלה ממנו ופועל הביטול) לא ההשגה עצמה, והמוחין דסט\"א אינם כלים ראוים לקבל אור וע\"כ אין הדבר המושג נרגש בהם לכן הן בבחי' יש כו', וזהו שהגם שמבינים ענינים באלקות כמו בריאה יש מאין וכה\"ג, ומ\"מ אינם מתבטלים בזה, מפני שאצלם הוא רק ההשגה לבד ועצם הענין אין להם שום שייכות כלל כו', אבל מוחין דקדושה ה\"ה כלים הראוים להאור דבהשגת ענין אלקי נרגש הענין המושג שזה פועל הביטול כו'). וזהו הסיבה מה\nשכל ענין שכלי בא בריבוי פרטים שבזה יש פרטים שונים והפכים זה מזה כו', שזהו ג\"כ מצד הביטול, וכמו מי שהוא בישות ביותר הוא מחזיק בדעתו ואינו נותן מקום לסברת חבירו לחשוב בה אולי ימצאה לנכון, ומי שהוא בטל ה\"ה חושב בסברת חבירו גם שהיא היפך סברתו ומקבלה אם מוצאה לנכון כו', וכמו\"כ כללות הענין מה שכל אור שכל מתחלק לכמה פרטים וגם פרטים הפכים, שזה ענין ההשגה להיות בהתחלקות פרטים דוקא, דבידיעה שטחיות אינו רואה פרטים כלל בהענין, וכשמשיג את הענין ה\"ה בא על הפרטים שבזה, והשגה טובה היא כשבא הענין בפרטים הפכים ואיך ששניהם אמת כו', ונודע ג\"כ דכל שבא לעומק השכל יותר ה\"ה בא בריבוי פרטים ביותר כו' דכ\"ז הוא מצד הביטול דוקא כו', ומהביטול דמוחין נמשך הביטול במדות להיות בהם ריבוי הפרטים כנ\"ל, ונמצא דריבוי הכלים הוא מצד הביטול שעי\"ז הם כלים ראוים אל האור כו'), וברבות הכלים יתרבה האור וההמשכה ביותר כו' וכמ\"ש אין עוד כלי ויעמוד השמן, ואלו היו עוד כלים הי' עוד ריבוי המשכת האורות כו'. וזהו ג\"כ ענין הגדלת הז\"א שנעשה\nע\"י המצות דרמ\"ח פקודין רמ\"ח אברין דמלכא, דבחי' אברין דמלכא היינו בחי' הכלים דז\"א, וע\"י מצות מעשיות שהוא עשיית ריבוי הכלים, דהיינו טפ\"ט ובכל א' יש ראש תוך וסוף"],[3601330338,"וה\"ח המגדילים כו', שע\"י ריבוי הכלים נמשך ריבוי האור כו'. שזהו מארז\"ל ועשיתם אותם מעלה אני עליכם כאלו עשוני, דלכאורה מהו כאלו עשוני והלא רמ\"ח פקודין הן רמ\"ח אברין כו'. אך הענין הוא לפי שע\"י המצות נעשה ריבוי הכלים, ומעלה אני עליכם כאלו עשוני שהכלים ממשיכים את האור, וכמו האברים שממשיכים את החיות שצריכים רק לתקן את האבר וממילא נמשך החיות כו', ופי' עשוני היינו מפני שבלעדי הכלים לא הי' האור נמשך ואדרבה הי' בבחי' הסתלקות למעלה, וע\"י הכלים נמשך האור היפך טבעו, וזהו שע\"י המצות דוקא עשוני בבחי' המשכת האור כו' (והמא' כאלו עשוני הוא מא' הז\"א כו'. וי\"ל ג\"כ עשוני ל' הכרח והיינו כבי' הכריחוני להיות בבחי' ירידה בבחי' ציור אדם היפך טבע האור כו', וה\"ז ע\"ד ישראל מפרנסין כו' להיות בבחי' ציור אדם כו' וכמ\"ש במ\"א, ומ\"מ אין זה הכרח ממש ח\"ו וכמשי\"ת בסמוך). וכן בעבודה להיות התגלות אור האהבה בנפש הוא ע\"י הכלים דתורה ומצות דוקא, דואהבת בגימ' ב\"פ אור וכל אור צריך לכלי שיתפעל מהאור והיינו שיהי' בבחי' ביטול ובבחי'\nקירוב ודביקות באלקות וזה דוקא ע\"י תורה ומצות כו', ולכן כשלא יש כלים דתורה ומצות א\"א להיות נמשך בו אור האהבה כו'. דהנה האהבה העליונה ודאי המשכתה הוא ע\"י המצות דוקא, וכמ\"ש ויצוינו את כל החוקים האלה ליראה כו', וידוע דקאי על בחי' יר\"ע וכן האהבה העליונה כו', וגם האהוי\"ר שע\"פ טו\"ד הוא דוקא כשיש כלים דתורה ומצות, וכמארז\"ל ולא ע\"ה חסיד דחסיד הוא בחי' חסד ואהבה ולא ע\"ה כו', דתורה ומצות הן כלים שע\"י יומשך בחי' אור האהבה כו', דגבי מצות כתי' אשר אנכי מצוך היום על לבבך שע\"י המצוה יתעורר רצון הנפש אליו ית' כו', וז\"ע כי נר מצוה שעי\"ז נמשך בחי' נר והארה בנפש היא הארת הרצון והאהבה שבלב כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והראי' מתהו שהכלים לא היו ראוים להתיישבות האור, ומשו\"ז ג\"כ הי' בתהו אורות הבלתי מתיישבים מפני שהכלי ממשכת האור וכפי אופן מהותה, משו\"ז הי' הסתלקות האורות, ובתיקון נעשו כלים הראוים לקבל האור, והו\"ע ריבוי הכלים שזהו מצד הביטול, וכמו התחלקות המדות שהוא ע\"י שהמוחין עושים ביטול בהמדות, וכן המוחין דהשגה אמיתית הוא בריבוי פרטים דוקא וגם באופנים שונים והפכים, הוא מפני שהמוחין להיותם השגה במה שלמעלה ה\"ה בבחי' ביטול (ומוחין דסט\"א הן יש מפני שאינו נרגש הענין המושג ובקדושה העיקר הוא להיות נרגש הענין המושג), וכמו\"כ הוא בכלים, ובהם נאחז האור, וברבות הכלים יתרבה האור, והו\"ע כאלו עשוני שעושין הכלים ונמשך האור, וכן בעבודה לא ע\"ה חסיד דאהוי\"ר שע\"פ טו\"ד ושלמעלה מטו\"ד הוא ע\"י הכלים דתומ\"צ.</span>\nצג) <b>וטעם</b> הדבר מה שהכלים ממשיכים את האור היפך טבעו הוא לפי ששרש הכלים הוא למעלה מהאור ושרשם מהאור מקיף, לכך כמו שהאור חושק לעלות אל המקיף כך חושק לירד ולהתאחז בהכלי כו', ולגבי האור ה\"ז מאיר בגילוי, דהנה בהכלים גופא כח שרשם ומקורם הוא בהם בהעלם מפני שהכלים בעצם הם בחי' העלם, אבל האור הוא בחי' גילוי ע\"כ בחי' שרש ומקור הכלי מאיר בהאור בגילוי, ומשו\"ז יש חשק בהאור לירד ולהאיר את הכלי, כי כל השפעה צ\"ל"],[3601330339,"בתשוקה דוקא לא בהכרח, ומשום מה שנתוסף בהאור ע\"י הכלי ההמשכה היא ברצון וחשק כו', וזהו שהכלי ממשיך את האור בכח שרשה ומקורה והוא בבחי' רצון בהאור כו'. וזהו הטעם מה שהוסד בסדר השתל' להיות נעוץ תחלתן בסופן דוקא, בכדי שיהי' משפיע ומקבל, דהרי המשפיע לא הי' רוצה להשפיע מפני שזהו ירידה לגבי', רק משום שע\"י ההשפעה נתוסף אור במשפיע עי\"ז יש רצון בהמשפיע להשפיע אל המקבל כו', וכמ\"ש בסדור בהדרוש שאחר עלינו. וכן הוא באורות וכלים דנעוץ תחלתן בסופן דוקא, והיינו שבהכלים שהן למטה במדרי' מהאורות יש בהם דוקא כח התחלה, דהיינו דהכח דאוא\"ס שלמעלה מן האורות הוא בהכלים דוקא, בכדי שיהי' ירידת והמשכת האור להאיר את הכלי, וההמשכה היא ברצון וחשק, מפני שעי\"ז נתוסף בו אור כו' וכמ\"ש במ\"א. ונמצא דלולא הכלים הי' האור בבחי' הסתלקות למעלה והכלים ממשיכים את האור להיות למטה כו'. וכמו\"כ ע\"י הכלים הוא התגלות האור והיינו שנעשה בבחי' אור המאיר, דלולא הכלים לא הי' בבחי' אור המאיר כלל כו'. וכמו עד\"מ באור האש מה שהוא מאיר זהו ע\"י דבר\nהנאחז דוקא, שהרי כשהאש מסתלק מהפתילה אינו מאיר כלל כו', דהדבר הנאחז ממשיך את הארת האש מהאש היסודי וע\"י נעשה בבחי' אור להאיר כו'. והענין הוא דהנה האש היסודי ידוע שהוא עצם חשוך ר\"ל שאינו אור, שאם הי' כאש שלנו המאיר לא הי' חשך כלל בלילה כו', אלא שאין יסוד האש כאש שלנו כי הוא רוחני מאד ולא ממהות אש שלנו ולמע' מבחי' אור עדיין, ולכך גם הארת האש הנמשך ממנו ג\"כ אינו מאיר אא\"כ יש לו כלי כו', לפי שהמשכתו ממקורו הוא בבחי' קירוב ע\"כ הוא כמו מקורו העצמי שאינו בבחי' אור עדיין, כ\"א ע\"י הכלי שנאחז בו והוא הפתילה להיותה מציאות אחר מהאש ה\"ז מסתיר קצת על האור ועי\"ז נעשה בבחי' אור המאיר כו'. וכמו\"כ יובן למע' דבחי' עצמות המאציל הרי אינו בגדר אור כלל וכמ\"ש ישת חשך סתרו שהוא בבחי' חשך והעלם שאינו בגדר אור כלל כו', וכמו\"כ בחי' הגילוי מן העצמות להיות שהגילוי הוא בבחי' קירוב ודביקות במקורו ה\"ה ג\"כ אינו בבחי' אור להאיר עדיין כו', דלבד בחי' הדביקות וההסתלקות שלו לגבי מקורו, דמשו\"ז אינו בבחי' גילוי עדיין וע\"ד איידי\nדטריד למיבלע כו' וכנ\"ל שבהאור הוא טבע העלי' כו', הנה מצד עצם מהותו להיותו בבחי' גילוי הדבוק במקורו אינו בבחי' אור עדיין כו', כ\"א ע\"י הכלים דוקא יהי' בבחי' אור המאיר לפי שהכלים הן בבחי' לבוש שמעלים קצת על האור, ועי\"ז הוא בבחי' אור להאיר כו'. וכמו עד\"מ אותיות המח' והדיבור שע\"י הוא גילוי אור השכל שהרי א\"א להיות שום גילוי אור שכל לעצמו בלי אותיות המח', והגילוי אל הזולת ע\"י אותיות הדבור, והיינו ע\"י שהאותיות מלבישים את האור שמתעלם בהאותיות, שהרי האותיות בעצם הם בחי' העלם, שהרי מי שאינו בר שכל בעצם אינו מבין מהאותיות מאומה, הרי שהן העלם בעצם, ובהתלבשות השכל בהם ה\"ה מתעלם בהאותיות ועי\"ז הוא הגילוי כו' (ומ\"מ ההעלם אינו כמו ע\"י המסך וכמו אותיות בלתי מסודרים שמעלימים לגמרי כו', משא\"כ אותיות מסודרים הרי האור מתלבש בהם, היינו שמתגלה בהם, ובהתלבשות זאת ה\"ה מלבישים ומכסים שמעלימים על האור ועי\"ז הוא הגילוי כו', דבכ\"מ שאינו בבחי' התלבשות אין זה גילוי לגבי האותיות אבל אין האותיות מעלימים כו', וההתלבשות\nהוא התגלות האור בהאותיות, אך בההתלבשות ה\"ה מעלימים כו'. וכמו\"כ הוא בהנמשל ענין התלבשות אור בכלי הוא שהאור"],[3601330340,"מתגלה בהכלי, ולהיות שהוא בבחי' התלבשות ה\"ה מעלים על האור שיהי' בבחי' אור וגילוי כו', וה\"ז כענין שע\"י הכלי נעשה האור כמהות הכלי להיות בבחי' מציאות אור שזהו ע\"י ההתלבשות שהאור מתלבש ונתפס בהכלי כו' וכמשנת\"ל. ובד\"פ י\"ל דהתגלות האור בהכלים הוא בבחי' פנימיות הכלים, דפנימית הכלי אינה מסתיר על האור להיות שאין זה מהות אחר עדיין כו', ומה שמעלים ומגלה זהו בחי' חיצוניות הכלים כו', ולהיות דגם פנימיות הכלים הוא בבחי' התלבשות ע\"כ ביכולת חיצוניות הכלים להעלים שיהי' בבחי' גילוי כו' (ובענין ים וארץ מבו' שבחי' הפנימית מעלים ומכסה כו', ומבו' במ\"א שזהו ע\"י הרוממות דמל' שהו\"ע הבדלה כו', א\"כ ההעלם הוא באופן אחר ממה שנת' כאן שההעלם הוא בבחי' כיסוי והסתר כו'). ומ\"מ צ\"ל דבד\"כ המשכת האור הוא באופן כזה שיתלבש בהכלי ויתגלה על ידה כו', והיינו מה שהמשכת האור הוא במדה ומשקל כו', וזהו ע\"י הקדמת הצמצום שהוא ג\"כ כדוגמת הכלי כו' וכמשי\"ת). והדוגמא מזה למעלה דלולא הכלים לא הי' בבחי' אור וגילוי וע\"י הכלים דוקא הוא בבחי' אור\nלהאיר כו', והגם שהכוונה בהמשכת והתגלות האור מן העצמות הוא להאיר כו' (ונת\"ל דהאו\"פ אינו בבחי' גילוי העצם כ\"א להאיר כו'), ומפני מה האור מצ\"ע אינו בבחי' אור המאיר כו'. הענין הוא דעם היות שהכוונה היא להאיר, מ\"מ הרי הכוונה היא שיהי' בבחי' אור דוקא שזהו ע\"י שיהי' בבחי' דביקות בהעצם כו', לכן גם בבחי' ההמשכה והתגלות לא הי' בבחי' אור להאיר כ\"א ע\"י הכלים דוקא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והטעם הוא משום דשרש הכלים למעלה משרש האור, ובהאור להיותו גילוי נרגש שרש הכלים, וע\"כ הוא נמשך ברצון וחשק להאיר הכלים. ומשו\"ז הוסד להיות נתב\"ס דוקא, וזהו שהכלים ממשיכים את האור, ועוד שע\"י הוא בבחי' אור המאיר, כי העצמות אינו בבחי' אור, וכמו\"כ האור הנמשך מן העצמות, מצד מעלתו ומצד דביקותו בהעצם, אינו בבחי' אור, וע\"י הכלים שמעלימים על האור ה\"ה בבחי' אור המאיר, וכמו אותיות מחו\"ד שמלבישים השכל ומעלימים עליו, ועי\"ז הוא ההתגלות (והתלבשות הוא התגלות בהמלביש וכמו\"כ האור מתגלה בהכלים ומתעלם ע\"י וי\"ל שההתגלות בפנימיות הכלים וההתעלמות בחיצוניות הכלים), וכמו\"כ האור ע\"י שמתעלם בהכלים ה\"ה בבחי' אור המאיר.</span>\nצד) <b>וזהו</b> דאי' במד\"ר פ' ויקהל פ\"נ מהיכן האורה נבראת א\"ל נתעטף הקב\"ה בשלמה והבהיק זיו הדרו כו', דלכאו' מה יפלא בריאת האור יותר מכל מה שנתהווה בשימ\"ב. אך הענין הוא דלהיות שהאור הוא בבחי' דביקות במקורו דמשו\"ז הוא כמו המקור שאינו בבחי' מציאות אור עדיין כו', וע\"ז שאל מהיכן האורה נבראת להיות בבחי' אור וגילוי כו'. ואינו מתמי' על כל הנבראים שנתהוו בבחי' מציאות, להיות שהתהוותם הוא בבחי' ריחוק כו', רק על התהוות האור הוא מתמיה איך הוא בבחי' אור המאיר מאחר שהוא בבחי' קירוב ודביקות כו'. והשיב שנתעטף הקב\"ה בשלמה כו', דבאמת בכדי להיות בבחי' מציאות אור זהו ע\"י שלמה ולבוש שבזה נאחז האור כו', ובשרש שרשו בחי' השלמה כמו שהיא באוא\"ס שלפה\"צ היא בחי' המח' דאנא אמלוך, שזהו עד\"מ כמו המח' באדם שבה נאחז אור"],[3601330341,"הנפש ומתגלה עי\"ז כו'. כמו\"כ כבי' למעלה המח' דאנא אמלוך הוא בחי' הלבוש שבזה נאחז האור להיות בעצמותו כבי' בבחי' אור השייך אל העולמות כו' וכמ\"ש במ\"א, ואח\"כ כשהי' הצמצום ונשאר רשימו ה\"ז בחי' כלי המקבל אור הקו כו' (עמ\"ש בזהר\"ק על מאה\"ז בראשית דט\"ו), שבזה נאחז האור להיות אור הקו בבחי' מציאות אור כו' (ולהיות בא במדה ומשקל כו') (ועמ\"ש בד\"ה להבין ענין אוא\"ס, א\"ס ולא אין לו תחלה, דע\"י הרשימו בא האור בבחי' כח גבולי, והיינו להשיטה שהאורות הן פשוטים לגמרי מצ\"ע להיותם מבחי' אוא\"ס הבל\"ג, ה\"ה באים בבחי' מדה וגבול ע\"י הרשימו שהיא בחי' כח הגבול שבא\"ס כו', ולפי המבו' בדרוש זה ע\"פ השטה שהאורות יש בהם ג\"כ ע\"ס, מ\"מ הרי האורות הן מבחי' אוא\"ס הבל\"ג, רק שזהו מה שהאוא\"ס שיער בעצמו להאיר בבחי' מדה וגבול כמשנת\"ל פכ\"ז, ולכן הן בבחי' פשיטות לגבי הכלים כמשנת\"ל פי\"ד, ובכדי שיהיו בערך להתלבש בבחי' כלים זהו ע\"י נקודת הרשימו כו'). והעיקר הוא בבחי' כלים דאצי' שבהם נאחז הארת אור המאציל להיות בבחי' אור וגילוי כו', ולכן\nבמדרי' שהכלים הן בבחי' מיעוט אין האור בבחי' גילוי ממש כו', וכמו החכ' שהיא בבחי' נקודה שאינו בבחי' גילוי ממש עדיין משום מיעוט הכלים כו', ובבינה ששם ריבוי הכלים יותר ה\"ז בחי' גילוי כו' (ובאמת הרי האור הוא בבחי' ריבוי בחכ' דוקא דגם בבחי' נקודת השכלה דחכ' האור בבחי' גילוי רב ובבינה מתעלם האור כו', והיינו כנ\"ל שהגילוי שע\"י הכלים הוא ע\"י שהכלים מלבישים ומעלימים על האור כו', ומ\"מ גם החכ' היא בחי' גילוי לפי שמ\"מ יש בחי' הכלים גם בחכ' כו', והגילוי הוא בבחי' ריבוי אור כו'). וכן החו\"ב בכלל נק' נסתרות מפני מיעוט הכלים שהרי נק' חיוהי כו', ועיקר הגילוי במדות שנק' אלה כו'. ובכללות הרי הע\"ס דאצי' הן בחי' ע\"ס הגלויות שזהו ע\"י הכלים שעי\"ז דוקא הן בבחי' אור וגילוי כו', וכמו\"כ מה שהן בבחי' חו\"ב וחו\"ג כו' כ\"ז הוא ע\"י הכלים דוקא, דהאור מצ\"ע אינו בגדר חו\"ב עדיין כו', והגם שבאורות יש ג\"כ ע\"ס וכמשנת\"ל, מ\"מ ה\"ה בבחי' פשיטות עדיין, ודוקא ע\"י הכלים ה\"ה בבחי' מציאות חו\"ב וחו\"ג כו'. וכמ\"ש הפרד\"ס שע\"ד פ\"ד וז\"ל ולפי\nהאמת לא יקרא החכ' הכלי כו' כי התכונה (היינו בחי' העצמות המתלבש בהכלי) הוא אשר יקרא חכ' באמיתית וזו (היינו הכלי) לבוש אלי' להראות העמים והשרים את יופי נשמתה הפועלת בה כו' עכ\"ל, והיינו שהכלי מראה ומגלה את האור כו', דעם היות שהאור הוא בחי' החכ', מ\"מ ה\"ה בבחי' פשיטות ואינו נראה ונגלה בבחי' מציאות חכ' כ\"א ע\"י הכלי כו' (ומ\"ש להראות כו' את יופי נשמתה י\"ל שזהו כענין המאמר אנת הוא דאפיקת עשר תיקונין שנק' הע\"ס תיקונין שהם תיקון המאציל כבי' וכמ\"ש הפרד\"ס שם פ\"ה מטעם שבהם מגלה הקב\"ה כחו וגבורתו כו', וגם שבזה נשלם תכלית הכוונה כו' וכמ\"ש במ\"א). וזהו שהספירות הן ל' ספור והגדה דכמו שהדיבור מגלה את הדבר הנעלם כמו\"כ הספי' מגלים את ההעלם דהיינו מה שהכלים ממשיכים ומגלים את האור כו', דלולא הכלים לא הי' המשכת האור כלל אלא הי' כלול בעצמות המאציל, וגם לא הי' בבחי' אור המאיר כו', והכלים ממשיכים את האור ומגלים אותו להיות בבחי' אור להאיר ובבחי' חכ' וחסד כו'. וז\"ע מה שהכלים הן גווני האור דהיינו שע\"י הכלי הוא בחי'\nמציאות אור ובגדר מיוחד כו', דהאור בעצם אינו בבחי' גוון וציור עדיין שאינו עדיין בבחי' מציאות אור ומכ\"ש שאינו בגדר וגוון מיוחד כו', וכמו המים שהם בגוון פשוט כו'"],[3601330342,"וכמ\"ש במ\"א, והכלים שמגלים את האור ובגדר מיוחד ה\"ז גווני האור כו', והו\"ע שם התואר שמתארים ומגלים את האור כו', ועש\"ז נק' ספירות ל' סיפור והגדה שמגלים את האור כו' (ועמשית\"ל בענין שהאורות והכלים הן בחי' אין ויש כו'). ולפ\"ז יובן דענין הספור שייך בספי' גם בהמדרי' שאינו שייך שם ענין המספר, דהרי נת\"ל פרק פ\"ה, דענין המספר עיקרו בבחי' מל' ולמעלה מבחי' המל' הוא בחי' מספר אשר לא יספר כו', אבל ענין הספור והגדה שייך גם בהמדרי' שלמעלה מהמל' להיותם בחי' הגילוי שמגלים את האור שזה שייך בכללות הע\"ס, דגם חו\"ב שנק' נסתרות מ\"מ בכללות הן בחי' ע\"ס הגלויות כנ\"ל ושייך בהם ענין הסיפור והגדה כו', וכמ\"ש אז ראה ויספרה הכינה וגם חקרה שהן ד' מדרי' חו\"ב וזו\"נ, אז ראה בחי' חכ' ויספרה בינה או בחי' חב\"ד בכלל כו' וכמ\"ש במ\"א, הרי שגם במדרי' דולתבונתו אין מספר שייך ענין סיפור שהוא בחי' התגלו' האור כו'. וז\"ע השמים מספרים כבוד אל שמים הן בחי' ע\"ס דז\"א גם שמים שם מים בחי' חכ' כו' מספרים כבוד אל שהן מגלים את האור וכמ\"ש אל ה' ויאר לנו כו'.\n<b>ועפ\"ז</b> יובן מ\"ש והוא עומד עליהם, דהנה נת\"ל פרק פ\"ד בענין זכר רב טובך יביעו שזהו בחי' מספר דמל', דהמלאכים אינם יכולים לקבל מבחי' האורות דאצי', רק בנש\"י כתיב ורב טוב לבית ישראל, אבל המלאכים מקבלים רק הארת בחי' המל' לבד כו', ואברהם עשה חסד עם המלאכים שהמשיך להם מבחי' אורות דאצי' וז\"ע והשענו תחת העץ בחי' אילנא דחי' כו', והיינו להיות שאצי' הוא בחי' גילוי עכ\"פ ע\"כ הי' ביכולתו להמשיך גילוי זה גם במלאכים כו', והוא ע\"ד מהלכים בין העומדים כו'. אך בהע\"ס דאצי' גופא הרי חו\"ב הן בחי' נסתרות כו', ועיקר הגילוי בחי' ז\"א כנ\"ל, ע\"כ בהמשכת האור שהמשיך אל המלאכים הי' בזה ב' ענינים, דהאור מבחי' ז\"א המשיך להם בבחי' או\"פ וז\"ע ויאכלו דאכילה הוא בחי' או\"פ, וידוע דמזון המלאכים הוא ההשגה שלהם, וז\"ע האכילה שהמשיך להם האור שיהי' בהם בבחי' השגה כו', ומבחי' חו\"ב המשיך להם בחי' או\"מ לבד ועז\"א והוא עומד עליהם דהעמידה הו\"ע בחי' מקיף כו'. וזהו והוא עומד כו' כמו כי הוא עשנו וכמו ועבד הלוי הוא בחי' בינה שנסתר\nונעלם עדיין דעש\"ז נק' הוא כו', וכמ\"ש בהגהות לד\"ה לך לך בתו\"א והוספות, דבחי' זו המשיך עליהם בבחי' מקיף לבד כו'. וזהו שאו' תחת העץ הגם שכבר נא' והשענו תחת העץ, אך לפי שאומר והוא עומד עליהם חוזר ואומר דמה שהמשיך להם בבחי' או\"פ הוא מבחי' העץ בחי' אילנא דחיי כו', וזהו והוא עומד עליהם בחי' או\"מ שהמשיך להם מבחי' חו\"ב כו', ותחת העץ בחי' ז\"א ויאכלו בבחי' אור פנימי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו דאי' במד\"ר מהיכן האורה נבראת מתמי' על האור להיותו בבחי' דביקות במקורו איך הוא בבחי' אור המאיר, ואו' שנתעטף בשלמה ולבוש המעלים, ולפני הצמצום הוא בחי' המח' דאנא אמלוך, ואח\"כ בחי' הרשימו היא כדוגמת כלי, והעיקר בחי' כלים דאצי', ולכן חכ' ששם מיעוט הכלים ה\"ז למעלה מהגילוי, גם הע\"ס שבהאור להיות בבחי' גדר מיוחד הוא ע\"י הכלים, וז\"ע ספירות ל' ספור שמגלים ומתארים את האור, וענין ספור שייך גם במדרי' שאינו שייך ענין המספר. ובזה יובן מ\"ש והוא עומד עליהם, דמלאכים יכולים לקבל רק מבחי' מספר</span>"],[3601330343,"<b>שזהו</b> בחי' הכלים דמל', ואברהם המשיך להם מבחי' האורות, ומבחי' ז\"א המשיך בבחי' פנימיות שז\"ע האכילה, ומחו\"ב בחי' מקיף שז\"ע והוא עומד עליהם."],[3601330344,"<h3>בס\"ד. ש\"פ חיי, תער\"ג</h3>\n<b>ואברהם</b> זקן בא בימים וה' ברך את אברהם בכל, וצ\"ל מה\"ע בא בימים אחרי שאו' ואברהם זקן מהו עוד בא בימים. ובכי\"ק הקשה דהול\"ל יצא מן הימים, מהו בא כו'. גם צ\"ל וה' ברך את אברהם בכל ואיזה שייכות יש לזה עם מ\"ש בא בימים דלפה\"נ יש להם שיכות זל\"ז, גם המשמעות הוא דמה שבא בימים הוא מכח עצמו והברכה היא מלמעלה דוקא. ובמדרש אי' וה' ברך כו' שהשליטו ביצרו, וצ\"ל מהו השבח כ\"כ לאברהם אחר שנתנסה בהעשרה נסיונות מה שהשליטו ביצרו. ולהבין כ\"ז ילה\"ק משנת\"ל דשם ספירה הוא ל' ספור והגדה והיינו מה שהכלים ממשיכים ומגלים את האור, דהאורות מצ\"ע ה\"ה בבחי' עלי' והתכללו' במקורם וכמ\"ש כי ה' אלקיך אש אוכלה כמשל האש כו', וגם אינו בהתגלות להיות אור המאיר והכלים ה\"ה ממשיכים ומגלים את האור להיות בבחי' אור המאיר כו'.\nצה) <b>אמנם</b> מ\"ש הרש\"ט שהספי' מגלות המחשבות הנעלמות אין הכוונה רק מה שהכלים מגלים את האורות כנ\"ל, כ\"א מה שכללות הע\"ס דאצי' בחי' אורות וכלים מגלות את האוא\"ס שלמעלה מאצי' כו'. דהנה ידוע דכללות ענין האצי' הוא בכדי שיהי' גילוי אלקות בעולמות וכמ\"ש בזח\"ב דמ\"ב ע\"ב דכללות ענין הע\"ס דאצי' הוא בגין דישתמודעון בי' כו', דהרי מההתהוות לבד לא היינו יודעין אלקות (דבכח ויכולת הא\"ס הוא שתהי' ההתהוות גם שלא ע\"י אמצעית האצי' אך מזה לא היינו יודעין אלקות כו'), לפי שההתהוות היא בבחי' העלם והסתר הבורא מהנברא, דלולא זאת הרי לא הי' התהוות היש, כ\"א דוקא ע\"י שהאלקות מסתיר את עצמו כו'. ובפרט אם הי' ההתהוות מאוא\"ס שלא ע\"י אצי' הרי לא הי' בבחי' התלבשות כלל, דהנה בהאור שהוא בבחי' התלבשות כח הפועל בנפעל שייך לומר שמתעלם ומסתתר, אבל מה שאינו מתלבש כלל אינו שייך שמתעלם כו'. דכן הוא גם בבחי' האין האלקי שאינו בבחי' התלבשות בנבראים דהיינו שההתהוו' שהאין האלקי מהווה את הנבראים אינו בבחי' התלבשות בהם, רק שאינו בדרך\nממילא מפני שיש לו שייכות עכ\"פ אל הנבראים, וזהו ע\"י אמצעית האצי' כמו שנמשך ממדרי' למדרי' במדריגות דאצי' גופא נעשה בבחי' שייכות כו' וכמ\"ש במ\"א, אבל לא בבחי' התלבשות כו' רק מפני שכל פעולה צ\"ל ע\"י התגלות הפועל ה\"ז בחי' הארת האין שבא בבחי' כח הפועל ובנפעל כו', ובחי' זו הוא שמתעלם ומסתתר כו'. ואם הי' ההתהוות מעצמות אוא\"ס לא הי' בבחי' התלבשות ובדרך ממילא כו', וא\"כ לא הי' מזה בחי' גילוי אלקות כו'. והגם שמההתהוות"],[3601330345,"מוכרח שיש מהווה שהרי א\"א לומר שהדבר נתהווה מעצמו שהרי כל מציאותו הוא מההרכבה כו', וכמו\"כ מזה שיש בהם הפסדות הרי נראה שהן נבראים כו', וגם מובן שההתהוות הוא בדרך אין ערוך כו' וכמ\"ש במ\"א, וא\"כ הרי מההתהוות מובן גם ההפלאה דאוא\"ס כו'. הנה לבד זאת דכל ענין ההשגה הזאת היא ע\"י אמצעית הע\"ס דאצי' שעי\"ז הו\"ע ההשגה באדם ושישיג השגה אלקית (שהרי ענין ההשגה לא בכולם בשוה שזה משיג באופן כזה וזה באופן אחר (בל\"א בא דעם לייגט זעך אזוי ובא דעם לייגט זעך באו\"א), שזהו מצד החילוקים באופן שרשן ומקורן כו', וכמו\"כ זה שיהי' השגה אלקית הוא מפני שכבר יש בחי' ספי' החכ' בסדר השתל' כו'), הרי גם הידיעה שהיו יודעים מההתהוות ה\"ה ידיעה כללית שיש אלקה הבורא ומהווה, אבל לא הי' שום ידיעה פרטית באופן האור והחיות האלקי כו', וגם לא הי' כלל בחי' אור וחיות המתלבש מאחר שההתהוו' היא מעצמות אוא\"ס שלא ע\"י התלבשות כנ\"ל, א\"כ הרי אינו שייך כלל אור וחיות המתלבש כו'. וכמו\"כ ידיעת ההפלאה הוא רק מה שהאלקות מרומם מהעולמות, ובאמת אין זה ענין\nההפלאה דאוא\"ס מה שמופלא מעצם מהות חומריות העולם כו', דהפלאה שייך בבחי' אורות ובמדריגות גבוהות שייך ההפלאה שמופלא מזה אבל לא ההפלאה מעצם מהות העולמות כו', וכללות הידיעה בזה הוא רק מה שהאוא\"ס מופלא ומרומם, אבל אינו שייך בזה הידיעה באופן ההפלאה כו', כי העולמות אינם בערך כלל וכלל לגבי אלקות וא\"כ אינו שייך שמפרטי הנבראים יהי' איזה ידיעה פרטית באופן ההפלאה דאלקות כו', ועצמות אוא\"ס ה\"ה סתום ונעלם לגמרי שאינו בגדר גילוי כלל וכמא' אנת הוא עילאה על כל עילאין סתימא דכל סתימין כו', שסתום ונעלם בעצם כו', וגם הארה מן העצמות אין העולמות יכולים לקבל כו'. וענין הארה מן העצמות לפי המבו' כאן י\"ל שזהו האור שבבחי' א\"ס ובלי גבול כו', וכמא' לית מח' תפיסא בך כלל שאינו שייך שום השגה באוא\"ס כו', וכמש\"א אתה קדוש ושמך קדוש דגם בחי' שמו קדוש ומובדל, וכמ\"ש כי נשגב שמו לבדו שאין ערוך לעולמות עם שמו ית' עד שהוא קדוש ומובדל מהם כו', מ\"מ הודו וזיו מאיר על ארץ ושמים דהארה משמו ית' ה\"ז בא בבחי' ירידה וצמצום להיות בגילוי\nבעולמות כו' (דשמו בכלל הוא בחי' המל' ועם היות דהמלך המרומם לבדו וכמ\"ש והים עומד עליהם מלמעלה רק בבחי' מקיף, מ\"מ הארה מזה בא בבחי' גילוי בנבראים שז\"ע בחי' דבר ה' שהדיבור הוא בחי' השפעה בקירוב דבחי' מל' והוא בחי' גילוי ההשגות וגילוי התענוג שבג\"ע כו', והיינו לפי שכללות בחי' המל' יש לזה שייכות אל העולמות דאין מלך בלא עם כו', שגם הרוממות הוא מה שמרומם מעם כו' ע\"כ הארה מזה בא בבחי' קירוב בגילוי כו', וכמו שהוא במל' דאצי' לגבי בי\"ע כן בבחי' מל' שלמעלה מאצי' לגבי אצי', וכן במל' דא\"ס לגבי כללות העולמות כו', ועמ\"ש בלק\"ת ד\"ה ראשי המטות ספ\"א, וכבר נת\"ל דמל' דא\"ס זהו בחי' ההשערה להאיר במדה וגבול כו'), אך פי' אתה קדוש הוא בחי' הקב\"ה בכבודו ובעצמו שלמעלה מבחי' שמו היינו שאפי' בחי' זיוו והודו לא היו העולמות יכולים לקבל ממנו כלל כו'. ולזאת מבחי' עצמות אוא\"ס לא הי' שום גילוי בעולמות כו' כ\"א ע\"י התהוות האצי' שהוא בבחי' גילוי ההעלם מאוא\"ס המאציל ה\"ז בבחי' גילוי אור כו', דהתהוות שבבחי' התחדשות הרי ההתהוות\nהיא בחי' העלם אבל מה שנתהווה בבחי' גילוי ההעלם ה\"ז גילוי כו', והאור הוא באופן כזה שהעולמות יכולים לקבל כו'"],[3601330346,"(דכללות הגילוי הוא מבחי' שמו ית' ובא באופן כזה שהוא בבחי' גילוי לגבי העולמות והעולמות יוכלו לקבלו כו'), ולפי שהגילוי הוא בבחי' מדות פרטיות בחי' חו\"ב וחו\"ג כו' עי\"ז נמצא השגה אלקית והרגישות אלקות בעולם כו', ועי\"ז יודעים אופן האור והגילוי דמאחר שהן בבחי' מדות וכחות פרטיים יכול להיות בהם ההשגה באיזה אופן ואיך ומה כו', דהיינו שמשיגים את האור האלקי כו'. וז\"ש בזהר שם בגין דישתמודען לי' במדות דילי' דכאשר מצמצם בבחי' מדות פרטיות עי\"ז יודעים ומכירים אלקות כו', ועמ\"ש הפרד\"ס שע\"ד פ\"ח על מא' זה שזהו ג\"כ ע\"י הכלים שעושים ציור ותמונה בהאור כו', אך עי\"ז יודעים אלקות כו'. וזהו כללות ענין האצי' שנתהווה בבחי' גילוי ההעלם דוקא בכדי שיהי' גילוי אלקות בעולמות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה המחשבות הנעלמות הכוונה על אוא\"ס שלמעלה מאצי', דהנה התהוות האצי' הוא בגין דישתמודעון בי', דמהתהוות לבד לא היינו יודעים אלקות מפני שהוא בבחי' העלם, ובפרט אם הי' ההתהוות מעצמות אוא\"ס ה\"ז לא בבחי' שייכות ולא בבחי' התלבשות כלל, משא\"כ האין האלקי ה\"ה בבחי' שייכות אל היש, והארה ממנו היא בבחי' התלבשות, והגם דמהתהוות יודעים שיש מהווה, ושהוא באין ערוך היינו שמופלא, הרי ענין הידיעה הוא ע\"י אמצעית חו\"ב דאצי', וגם היא רק ידיעה כללית שיש בורא, וגם לא זו היא ההפלאה שמופלא מהיש, ועוד שלא הי' גילוי אור וחיות בעולמות, שהרי עצמות סתום וגם גילוי העצמות לית מחת\"ב, אתה קדוש ושמך קדוש, והארה משמו הוא בחי' גילוי ע\"י צמצום, ואתה קדוש ומובדל לגמרי, רק ע\"י האצי' שהוא גילוי ההעלם, דהיינו ע\"י הצמצום ובא במדרי' פרטיות, עי\"ז הוא גילוי אור וחיות, וההשגות והרגישות אלקית.</span>\nצו) <b>ועוד</b> זאת שע\"י הע\"ס יודעים את האוא\"ס שלמעלה מאצי', שז\"ע שהם מגלים את המחשבות הנעלמות דהיינו כח אצי' הכמוס וחתום באוא\"ס המאציל והן הע\"ס הגנוזות במאצילן כו'. אך מה שהספי' דאצי' מגלות המחשבות הנעלמות, היינו הע\"ס הגנוזות כמו שהן בהמשכה להיות בבחי' מקורים עכ\"פ לע\"ס הגלויות כו', וגם בהם וע\"י יש גילוים מהאורות עצמיים דע\"ס הגנוזות כו'. ויובן זה עד\"מ בנפש האדם שיש בו כחות עצמיים הכלולים בנפש, דהנה הנפש עצמה ה\"ה פשוטה לגמרי ואינה בגדר כחות כלל וכמ\"ש בסש\"ב פנ\"א שהיא כולה עצם א' רוחני פשוט כו', והיא למעלה גם מבחי' יחידה וכדאי' במדרש חמשה שמות נקראו לה כו' הרי הנפש עצמה למעלה גם מבחי' יחידה, והיא בבחי' פשיטות לגמרי כו', רק שכוללת בתוכה כל הכחות וכמו כח השכל ההיולי העצמי וכח החסד ההיולי העצמי כו' שמהם נמצאים כל הכחות הגלוים כו' (והכחות העצמיים זהו בחי' יחידה שבנפש ונק' יחידה לפי שהכחות עצמיים אינם בבחי' מציאות כחות כלל, והן בבחי' פשיטות לגמרי בעצם מהותם ואינם בבחי' התחלקות כלל היינו\nשאינם כלל בבחי' עשר כחות כו'. והגם שזה כח החכ' וזה כח הבינה כו', ה\"ה בבחי' פשיטות לגמרי ונק' העלם שאינו במציאות כו' וכמ\"ש במ\"א, וכמו כח האש שבצור החלמיש כו'. וכללות בחי' יחידה זהו ע\"ד כמו חומר היולי שכולל בעצמו שרשי הד' יסודות ואין"],[3601330347,"בו שום צורה רק עתיד להלביש צורה ונק' תהו כו', וכמ\"ש בע\"ח שמ\"א פ\"ג ושם שזהו בחי' אריך כו'). ומובן דהכחות עצמיים הגם שמהם נמצאים כל הכחות אינם בגדר מקור לכחות, דכל מקור בהכרח שהוא בבחי' מציאות דבר מה שנעשה מקור וגם הוא בבחי' המשכה להיות מקור לדבר כו', והכחות עצמיים הרי אינם בבחי' מציאות כחות כלל, דכל דבר הכלול בעצם ה\"ה כמו העצם, וכמו שעצם הנפש אינו בבחי' מציאות דבר, כמו\"כ הכחות הכלולים בו אינם בבחי' מציאות דבר כו', וגם אינם בבחי' המשכה כלל והיינו להיותם עצמיים וכל עצם אינו נמשך (ר\"ל בבחי' המשכה והתפשטות כ\"א בבחי' המשכה עצמיות, הרי בהמשכתו הוא בבחי' מהות עצמו שאינו בגדר בחי' מקור כו', ובמ\"א מבואר דבהמשכתו הגם שזהו שהעצם נמשך ואינו בגדר מקור עדיין, מ\"מ הוא בגדר שנעשה בבחי' ממוצע כו', והוא בחי' העליונה שבהממוצע שמובדל בערך כו' וכמ\"ש במ\"א). (והגם שהן כחות הנפש לא עצמות הנפש, י\"ל דזה שהן כחות הנפש אין זה שהן התפשטות וגילוי מהנפש שנעשים כחות, כ\"א מה שנמצאים עם הנפש דכשנמצא הנפש נמצאים עמו הכחות\nכו', וע\"כ עם היותם כחות ה\"ה עצמיים כו'), הרי שאינם בגדר מקור לכחות רק שמהם נמצאים הכחות בדרך ממילא (שאין הכחות עצמיים מתפעלים במציאות הכחות מהם שזהו דוקא בדבר שהוא בבחי' מקור ה\"ה מתפעל בעצמו כו', וע\"ד כל מניע מתנענע בעצמו כו', אבל הכחות עצמיים אינם מתפעלים בזה וזהו שהוא בדרך ממילא כו'), ומה שנמצא מהם הוא להיות בבחי' מקור לכחות הגלוים, דהכחות הגלוים ממש אינם בערך להיות נמצאים מהכחות העצמיים כו' (וכאשר לפעמים נמצאים מהכחות עצמיים ה\"ה בעילוי באין ערוך, וכמו בגילוי ההשכלות הבאים בכח או\"ח ע\"י קושיות כו', וכמו תלמיד המחכים את רבו כו' וכמ\"ש במ\"א, ולפ\"ז צ\"ל דההמשכה מהכחות עצמיים הגם שזהו רק מה שנמצא מהם וה\"ז רק בדרך סיבה לבד, מ\"מ יש בזה איזה ערך ואין זה בדרך אין ערוך לגמרי כו'), כ\"א מה שנמצא מהכחות הוא בחי' מקורי הכחות שהן בבחי' מציאות דבר ובבחי' המשכה להיות בבחי' מקור והוא הנק' המשכה נעלמת כו'. וכמו שמכח השכל ההיולי העצמי נמשך להיות מקור לשכל גלוי והוא בחי' כח המשכיל שבנפש כו', דכח המשכיל הוא\nבבחי' מציאות דבר לגבי הכח השכל ההיולי העצמי הנטוע ומושרש בנפש, ולגבי שכל הגלוי אינו במציאות שכלי עדיין שה\"ה כח היולי על כל השכליים, וידוע דכל כח היולי הוא מושלל מהגילוים שממנו כו'. וכמו\"כ כח המשכיל מאחר שהוא היולי על כל מיני שכליים בהכרח שהוא מושלל ממציאות שכל גם במדרי' היותר נעלית כו' וכמ\"ש במ\"א, ומ\"מ אינו מושלל מגדר שכל לגמרי מאחר שהוא בבחי' המשכה עכ\"פ מכח ההיולי עצמי, ממילא ה\"ה באיזה ציור ובאיזה מציאות, רק שהוא בבחי' המשכה נעלמת כו', דענין המשכה נעלמת הוא שמושלל ממציאות הדבר שהוא מקור אליו אבל אינו מושלל מעצם הדבר כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וגם שהע\"ס מגלות בחי' הע\"ס הגנוזות בהמשכתן (היינו מה שנמצא מהן להיות מקור) וגם גילוי מעצמותן, ועד\"מ עצם הנפש שמושללת מכחות לגמרי וכוללת בתוכה כחות, שהן נמצאים עמה מתחלת ההתהוות (ולמעלה ה\"ז רק באור א\"ס), וע\"כ הן ג\"כ עצמיים, והן בבחי' פשיטות לא בבחי' מציאות כלל וכלל, ואינם בבחי' המשכה והתפשטות כלל, ואינם בבחי' מקור כלל, רק שמהם נמצאים</span>"],[3601330348,"<b>מקורי</b> הכחות (לא הכחות, וא\"כ אין זה אין ערוך לגמרי), וכמו כח המשכיל מקור השכל שהוא המשכה נעלמת היינו שמושלל ממציאת השכל, ואינו מושלל מעצם ענין השכל.\nצז) <b>ויובן</b> זה מענין השגה נעלמת, דהנה כל השכלת והשגת דבר ה\"ז התפשטות כח החכ' לא עצם כח החכ', עם היות שהחכ' היא השכלה היינו לא רק כח להשכיל כ\"א הוא ענין ההשכלה עצמה, מ\"מ אין ההשכלה עצם הכח כ\"א התפשטות הארה לבד כו' (והענין הוא דהנה כל השכלת והשגת דבר הוא בא באיזה פרט דבר, היינו הדבר המושג, ויש בזה ב' ענינים השכלת והשגת הדבר המושג, ועצם ההשכלה, היינו ידיעת הדבר המושג, ועצם ההשכלה וההשגה הגם שהוא בהדבר המושג, ה\"ה בעצם למעלה מהמושג, שהרי המושג הוא ענין פרטי מה שהוא המושג (וואס דער מושג איז) וההשכלה אינו פרטי, וכמו שכל א' שמסתעפים ממנו שני ענינים, הרי הענינים המה פרטים, וההשכלה אינה פרטיות, וכמו המבין דבר מתוך דבר, הרי המה דברים פרטיים מובדלים, וההשכלה בהם אחת היא, וכמו\"כ הוא בכל שכלי בפרט הנה המושג הוא שהשכל הוא בהתלבשות בדבר פרטי, וההשכלה הגם שהיא באותו הפרט, היא בעצם מופשטת מהפרט, והוא עצם ענין ההשכלה שלמע' מהתלבשות ותפיסא בדבר מה, הגם שמשכיל ומתחכם באיזה דבר, הנה עצם ההשכלה\n(והכוונה היא על ההשכלה בפועל) היא למעלה מהדבר, דרק הארתו הוא המתלבש ונתפס בהדבר המושג כו', והרי הארה זו ודאי היא רק התפשטות לבד. אמנם גם עצם ההשכלה היא רק התפשטות הארה מעצם כח החכ' כו'), וההארה היא בסדר והדרגה דלפעמים מתפשטת יותר ולפעמים במיעוט, כמו בשכל גדול יש בו יותר מאור החכ' מבשכל קטן, וכן בחכם גדול מאיר ומתפשט אור החכ' יותר וגבי חכם קטן מאיר אור החכ' במיעוט כו', ומן המיעוט יכולים לבוא אל הריבוי, וכמו בהדרגת ההשכלות הרי יודע ומשכיל שכל קטן ואח\"כ בא לידי השכלת שכל גדול כו', וכמו בחכמים החכם הקטן נעשה במשך זמן חכם גדול, והחכם הגדול מלמד את הקטן כו', כי כ\"ז הוא התפשטות הארה בסדר והדרגה ששייך בזה לימוד והגדלה ממדרי' למדרי' כו'. אמנם מי שמאיר אצלו עצם כח החכ' והוא הנק' חכם מצד עצם כח חכמתו, הנה ההשגות שלו המה נפלאים בערך שלא יש כלל השגות כאלו בחכם זולתו (היינו מי שהוא חכם רק בבחי' התפשטות החכ') ואינו משערים כלל השגות כאלו, וגם הוא א\"א לו להשפיע ולגלות השגה זו מפני שבו בעצמו אין זה בכלי\nהשגה שלו, כי כלי ההשגה המה קטן מהכיל השגה זו, וע\"כ לא יוכל לגלות ולבאר זה בדבור, וכמה שידבר בזה לא יהי' זה מה שהוא עצם כוונתו בהענין, כי הדבור מגלה רק מה שנתפס בכלי ההשגה, אבל השגה זו היא למע' מתפיסא בכלי השגה. וה\"ז קרוב להידיעה דראי' דחכ', עם היות שזה השגה מ\"מ הידיעה היא כמו הראוי כו', ויותר מכוון שזה כמו השגה דשכלים נבדלים כו'. וכן יכול להיות בכל ענין שכלי לבד ההשכלה נגלית שבו שזה ידוע לכל חכם, ה\"ה תופס את הענין באופן אחר לגמרי שאינו ידוע כלל לשום חכם זולתו, וגם הוא אין ביכולתו כלל לגלות מה שהוא יודע בהענין הזה, רק ביגיעה יוכל להביא את הדבר ענין באותיות קצרים שנושאים את הענין, לא שהוא בהם בהתגלות כי א\"א להיות בהתגלות כ\"א בהשגה נעלמת לבד בעצם החכ' שלמע' מהשגה נגלית גם בעצמו, וכ\"ש שא\"א להתגלות אל"],[3601330349,"הזולת כ\"א בדברים הנושאים את הענין כו' (וכמו באיש הטוב בעצם כח הטוב שבנפשו יוכל לבוא על עניני הטבה ולהתעורר בהם מה שהאיש הטוב זולתו לא יבוא כלל ע\"ז כו', וכמו\"כ הוא בחכ' ושכל כו'). וגם יובן זה כמו המבין מדעתו דהיינו שצריכים לפתוח לו רק כחודה של מחט בהענין ומעצמו יבוא ע\"ז, וזהו מצד עצם כח חכמתו שיש לו בעצם חוש טוב ביותר בהשכלה, א\"צ להגיד לו הרבה ומכ\"ש שלא לפרט לו הפרטים, רק שצריכים לפתוח לו הענין ומעצמו בכח חכמתו יבוא על הענין ועל פרטיו ולא יטעה ח\"ו בשום דבר כו'. גם מי שהוא מבין בדעתו יבין הכוונה האמיתית בכל דבר שהגם שלפי הנגלה הכוונה באופן אחר, ה\"ה מבין שאמיתית הכוונה היא באופן כך וכך, הגם שאינו נגלה כלל בהדברים זהו מצד עומק המושג שהדברים לא יכילנו ע\"כ נראית הכוונה באופן אחר, או משום כבוד אלקים הסתר דבר כו', ומי שהוא מבין מדעתו ה\"ה בא על אמיתית הכוונה שזהו רק מפני שמאיר בו עצם כח חכמתו שלמעלה מהשכל גלוי כו'. ועד\"ז יובן ענין המשכה נעלמת דכח המשכיל שאין זה שכל ומ\"מ אינו מושלל לגמרי מענין\nהשכלי, וכמו ההשגה נעלמת שאינה בבחי' שכל גלוי כלל עד שא\"א לו להביאו לגילוי כו' כנ\"ל, ומ\"מ ה\"ז שכלי כו', וכן בהמבין מדעתו כו' (דבאמת זהו גילוי מכח המשכיל שז\"ע כח חכמתו העצמי כו', וההשגה נעלמת זהו שהשכלי גופא הוא כמו מהות עצם החכ' כו', והמבין מדעתו זהו הגילוי מעצם כח החכ' להבין מדעתו כו', ובאמת גם ההשכלה בזה היא באופן הזה כמו מצד העצם כו', ובאמ\"ב מבו' שזהו מכח המשכיל מהמדרי' העליונה שבו היינו מה שסתום ונעלם בעצם כו').\n<span data-k=\"ks\"><b>קיצור.</b> ויובן זה מהשגה נעלמת, שזהו השגה נפלאה בערך הבאה מעצם כח חכמתו, וכמו השגה דשכלים נבדלים, והיא למעלה מתפיסת כלי השגה, ולכן א\"א לגלות ולבאר זאת, כ\"א להביא באותיות קצרים הנושאים את הענין, ובחכם כזה בכל ענין ידיעתו באופן כזה, וכן המבין מדעתו שזהו מצד טוב עצם חוש ההשכלה, וההשכלה היא כמו מצד העצם.</span>\nצח) <b>והנה</b> ידוע דכח המשכיל נודע מציאותו ולא מהותו דהגם דמהותו אינו ידוע כמו החכ' הגלוי' שאנו יודעים ומרגישים איך ומה הוא כו' (דהגם שידיעתנו בהשכל גלוי הוא ג\"כ רק מציאותו לבד כי אין אנו יודעים מהות הרוחני מ\"מ הרי אנו יודעים את מציאות הכח ממש כמו שהוא כו'), משא\"כ מקור השכל אין אנו יודעים איך ומה הוא כו', מ\"מ הרי מציאותו אנו מרגישים שיש מקור שמשם בא השכל גלוי, שהרי כשבאים על איזה השכלה חדשה הרי מרגישים שבא מאיזה מקום, לא שכאן נתחדש ההשכלה כ\"א שבא מאיזה מקור, הרי שאנו מרגישים מקור השכל ע\"י השכל גלוי כו', וממילא אנו יודעים ג\"כ עילוי המקור על הגלוי כמו כל היולי שיש בו עילוי הנ\"ל על הגילוי שממנו ושמ\"מ אינו מושלל לגמרי כו' כנ\"ל. וגם יש גילוים ממקור השכל כמו ענין השגה נעלמת ומבין מדעתו הנ\"ל, שכ\"ז הוא ע\"י השכל גלוי שהרי יהיב חכמתא לחכימין דדוקא לחכימין בכח השכל הגלוי יהיב חכמתא מעצם כח החכ' כו', וגם יכולים להיות גילוים גם מהכח השכל ההיולי העצמי בכח או\"ח כמו ומתלמידי יותר מכולם כתלמיד המחכים את רבו שכ\"ז הוא ע\"י השכל גלוי כו'. וכ\"ז הוא לפי שהתהוות"],[3601330350,"השכל גלוי ממקורו אינו בבחי' התחדשות ממש כ\"א בבחי' גילוי ההעלם כו', שאם הי' בבחי' התחדשות לא היינו יודעים ומרגישים את המקור (היינו שלא הי' ההמשכה באופן כזה שיורגש שנמשך מאיזה מקור כו'), מאחר שהוא בדרך אין ערוך כו', וכ\"ש שלא הי' גילוים מעצם כח החכ' כו', כ\"א ע\"י שהוא בבחי' גילוי ההעלם עי\"ז הוא הרגש מציאות המקור והגילוים ממנו כו'. וגם הגילוים מכח העצמי הגם שזהו ע\"י ההעלמו' והסתירים מ\"מ ה\"ז ע\"י השכל גלוי, שהרי זהו ע\"י בירור וליבון דהשכל גלוי, וגם שע\"י שמעיין בשכלו ומייגע א\"ע לתרץ הקושיות ה\"ה בא לידי גילוים מהכח העצמי שכ\"ז הוא ע\"י השכל גלוי (ולפי שאופן ההמשכה אינו בדרך אין ערוך לגמרי כ\"א בבחי' איזה שייכות כו', וכמשנת\"ל פצ\"ו שמה שנמצא מכח השכל העצמי הוא דוקא מקור השכל לא שכל הגלוי, ואם יהיו גילוים מכח השכל העצמי ה\"ה שכליים נעלים ביותר, מכ\"ז מובן שאין זה בדרך ערוך לגמרי דאל\"כ לא הי' הבדל בין מקור השכל לשכל גלוי וגם לא הי' הפרש בין אופני הגילוים כו'). והדוגמא מזה יובן בע\"ס דאצי' דלבד זאת שהן\nבבחי' גילוי מהמחשבות הנעלמות, הנה עי\"ז שהן בבחי' גילוי ההעלם לבד ה\"ה מגלים גם את המחשבות הנעלמות היינו מקורי הספירות כו'. דהנה ידוע דחכ' סתימאה נק' שכל הנעלם מכל רעיון שאינו בבחי' מציאות חכ' כמו בחי' חכ' הגלוי' וכמשנת\"ל פי\"ד בענין שתוק כך עלה במח' כו', ומ\"מ אינו מושלל לגמרי מבחי' החכ'. וכידוע ההפרש בין שכל נעלם לשכל מופלא, דשכל מופלא הוא בחי' חכ' דעתיק (כמשל כח ההיולי העצמי) שמופלא לגמרי מגדר החכ', משא\"כ שכל נעלם אינו מופלא לגמרי מבחי' החכ' והיא בחי' העלם השייך אל הגילוי כו' (ומה שהוא למעלה מן החכ' לגבי חכ' הגלוי' כמשנת\"ל בענין שתוק כו', זהו כמו שהשגה נעלמת הנ\"ל היא נעלם לגמרי משארי חכמים וגם הוא אין ביכולתו להביא לידי גילוי, ומ\"מ ה\"ז בחי' חכ' ושכל כו'). וידוע שח\"ס נק' הוא שנודע מציאותה עכ\"פ כמ\"ש בסי' בפי' ברוך שאמר, והיינו להיותו בחי' מקור לחכ' ע\"כ ע\"י החכ' נודע ג\"כ מציאות בחי' ח\"ס כו' (והעיקר מה שנודע מציאותו הוא באצי' דגילוי החכ' שם הוא בבחי' גילוי המהות ממש וח\"ס בבחי' גילוי המציאות\nכו', ועמ\"ש בלק\"ת ד\"ה וידעת הא' דבבחי' ממכ\"ע דהיינו בחי' חכ' שייך ידיעת המציאות ובבחי' סובב דהיינו בחי' הכתר הו\"ע האמונה כו', ומבו' במ\"א שזהו אצלינו כך אבל באצי' החכ' היא בבחי' השגת המהות וח\"ס בהשגת המציאות כו'. וגם מבו' שם בהבי' הב' בענין הדעת באמונה שגם בבחי' סובב שייך השגת והרגשת המציאות כו', וזהו גם אצלינו וכמש\"ש שכל הנבראים יכולים להשיג מציאות בחי' הסובב כו', וגם בחי' ח\"ס אין זה בחי' הסובב ממש שזהו מקור או\"פ כו', אך גם הסובב מושג מציאותו וכמשי\"ת). וגם יש המשכות וגילוים מבחי' ח\"ס וכמו סודות ורזין דאורייתא וכמו בחי' השגה נעלמת והחכ' דמבין מדעתו כו' שכ\"ז הוא מבחי' ההמשכה נעלמת דבחי' ח\"ס כו'. וכמו עד\"מ בנפש ע\"י קושיות ותירוצים יהיו גילוים גם מהשכל ההיולי העצמי, כמו\"כ הוא למעלה שע\"י הבירורים יהיו גילוים אורות עצמיים מבחי' חכ' דעתיק, וכמו טעמי תורה שיתגלה לעתיד ע\"י משיח מבחי' פנימיות עתיק שזהו ע\"י הבירורים דעכשיו, וכמ\"ש יעשה למחכה לו למאן דדייק כו' שעי\"ז יהי' גילוי בחי' עדן סתימאה בחי'\nההעלם העצמי כו' וכמ\"ש במ\"א. וכ\"ז הוא ע\"י בחי' החכ' דאצי' כו', כי לולא ח\"ו בחי' חכ' דאצי' לא היו כל הגילוים הנ\"ל כ\"א הכל"],[3601330351,"הי' סתום ונעלם לגמרי ולא הי' שום גילוי כלל, וכל הגילוים הנ\"ל הכל ע\"י החכ' הגלוי' כו', וגם דהרי כל הבירורים הן ע\"י החכ' דבחכ' אתברירו כו', ועי\"ז הן כל הגילוים גם גילוי האורות עצמיים כו'. וזהו דחכ' דאצי' וכן כל הע\"ס דאצי' מגלים לנו את המחשבות הנעלמות כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ואברהם זקן בא בימים, דבזהר אי' בא בימים באינון יומין עילאין והן הלבושין דתומ\"צ שבאים בימים בחי' הזמן וכמ\"ש במ\"א, והיינו שע\"י הלבושים הוא אחיזת האור שיהי' בבחי' המשכה והתגלות כו' וכמשנת\"ל פצ\"ב, וזהו ואברהם זקן ואי' במדרש זקן ויושב בישיבה הי' כו', ועז\"א בא בימים שבא ביומין עילאין שעי\"ז הוא המשכת והתגלות האור כו'. דהנה אברהם התחיל להאיר דעד אברהם הי' העולם מתנהג באפילה ואברהם התחיל להאיר שפרסם אלקותו בעולם ע\"י העובדות בגמ\"ח כו', והן בחי' היומין שע\"י הוא המשכת והתגלות האור כו'. ובמדרש הנעלם שבא לעולם שהוא בבחי' ימים ולא לעוה\"ז שנק' לילה, והיינו כמו שנת\"ל פצ\"ה דמהתהוות העולם אינו יודעים אלקות וזהו שעוה\"ז נק' לילה, ועולם שבבחי' ימים היינו עולם האצי' שע\"י הספי' הוא גילוי אלקות זהו שבא לעולם שהוא בבחי' ימים היינו בחי' הע\"ס דאצי' כו'. ומ\"ש וה' ברך את אברהם היינו מה שע\"י האורות הוא התגלות בחי' המחשבות הנעלמות שלמעלה מאצי' כו', ואומר ע\"ז וה' ברך שזהו בבחי' המשכה\nמלמעלה כו'. דהנה המשכת והתגלות האור ע\"י הלבושין דתומ\"צ הוא בכח עצמו ועבודתו כו', אמנם ההמשכה דבחי' מח' הנעלמות זהו מה שנותנים מלמעלה כו', ולהיות דיהיב חכמתא לחכימין דוקא כנ\"ל זהו לאחר שבא בימים בכח עצמו ועבודתו אז וה' ברך את אברהם בההמשכה העליונה בבחי' הגילוי שלמעלה מאצי' כו'. ומש\"א במדרש שהשליטו ביצרו זהו מה שבא ע\"י בירורים שמאיר מבחי' העצמיות דע\"ס הגנוזות כו', וענין שהשליטו ביצרו היינו שא\"צ ללחום עוד והו\"ע הגמר הבירור דאז הגילוי דבחי' העצמיות דהע\"ס כו'. וזהו ואברהם זקן בא בימים היינו שע\"י היומין הוא המשכת והתגלות האור וגם שע\"י הע\"ס דאצי' הוא בחי' גילוי אלקות בעולם כו'. ועי\"ז וה' ברך את אברהם בהגילוי דע\"ס הגנוזות כו', וענין שהשליטו ביצרו היינו גמר הבירורים שמאיר מבחי' העצמיות דע\"ס הגנוזות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וידוע דכח המשכיל נודע ע\"י השכל גלוי, והיינו לפי שהוא גילוי ההעלם, ויש גילוים מעצם כח החכ' ע\"י החכ' הגלוי' דיהיב חכמתא לחכימין דוקא, וגם הגילוים מכח ההיולי העצמי הגם שזהו בדרך או\"ח, מ\"מ הוא ע\"י השכל גלוי, והדוגמא למעלה דלהיות ע\"ס דאצי' בבחי' גילוי ההעלם עי\"ז יש גילוים מבחי' ח\"ס, והן הרזין דאורייתא (ובאצי' ח\"ס נודע מציאותו) וע\"י הבירורים שהן בכח החכ' יהי' גילוים אורות עצמים, יעשה למחכה לו. ובזה יובן מ\"ש ואברהם זקן בא בימים ובמה\"נ בעולם שבבחי' ימים היינו אצי', ועי\"ז וה' ברך גילוי הנעלם והשליטו ביצרו הוא גילוי העצמיות שע\"י הבירורים.</span>"],[3601330352,"<h3>בס\"ד. ש\"פ תולדות, תער\"ג</h3>\n<b>ואלה</b> תולדות יצחק בן אברהם אברהם הוליד את יצחק, והקשה מהרמ\"א מ\"ש ואלה בוי\"ו שארז\"ל כל אלה פוסל את הראשונים ואלה מוסיף על הראשונים ומה מוסיף כאן על בני ישמעאל שנא' בפ' הקודמת, והנה רש\"י פי' תולדות יצחק יעקב ועשו האמורים בפרשה, ולפ\"ז י\"ל דמ\"ש ואלה היינו עשו שמוסיף על בני ישמעאל, אך א\"מ למה נא' ואלה שמוסיף על הראשוני' בשביל עשו יותר הי' ראוי לו' אלה שפוסל את הראשונים בשביל יעקב שזהו שבח יותר. גם צ\"ל מ\"ש אברהם הוליד את יצחק אחרי שכבר נא' יצחק בן אברהם למה כפל עוד אברהם הוליד כו'. גם א\"מ מ\"ש בן אברהם ולא נא' תולדות יצחק סתם כמו שנא' אלה תולדות יעקב כו', ולמה נא' כאן יצחק בן אברהם וכפל עוד אברהם הוליד כו'. ולהבין כ\"ז ילה\"ק משנת\"ל בפי' ספירה מל' ספור והגדה כמו השמים מספרים כבוד אל, דכמו שהדבור והמכתב מגלים דברים הנעלמים במח', כן השמים מורים על השי\"ת שכן הספי' מגלות את המחשבות הנעלמו', ונת' דהיינו שע\"י הע\"ס להיותם בבחי' גילוי ההעלם נמשך ע\"י גילוי אלקו' בעולם, וגם שהם מגלים המחשבות\nהנעלמו' שהן הע\"ס הגנוזו', ונת' שיש בזה ב' מדרי' בחי' העצמי' דע\"ס ובחי' ההמשכה שנק' המשכה נעלמת שהוא מקור הספי', ונת' דהאורות דע\"ס מגלות מקור הספי' דע\"י חכ' הגלוי' נודע מציאותה דבחי' ח\"ס ויש גילוים מח\"ס כמו ידיעת הסודות כו', וגם מגלים בחי' העצמי' דע\"ס הגנוזו' כו'.\nצט) <b>והנה</b> לבד זאת שהע\"ס מגלים שרשם ומקורם שהן המחשבות הנעלמות כו', עוד זאת שאצי' מגלה את בחי' הא\"ס הבל\"ג כו', שז\"ע השמים מספרים כבוד אל שהשמים התחתוני' מספרים ומגלים אלקו' היינו שהם מגלים את בחי' אוא\"ס הבל\"ג כו'. דהנה בת\"י כ' ע\"ז דמסתכלין בשמיא משתעין ביקרא דה', והוא כענין שאו מרום עיניכם וראו מי ברא אלה שנראה ונגלה בהם כח הא\"ס, הן במה שהן קיימים באיש בלי הפסדות כלל שזהו רק מכח הא\"ס כו' וכמשנת\"ל פרק פ\"ז בקצרה ומבו' במ\"א באורך ועמשית\"ל פ', וכן מהתמדת הפעולה שלהם מה שסובבים תמיד בלי הפסק כו' שא\"ז מכח עצמן, כי הבע\"ג א\"א שיתמיד פעולתו בתמידות ובהכרח שיהי' נח מפעולתו, והגלגלים שמסבבים תמיד בלי הפסק ה\"ז מכח הא\"ס ב\"ה. והגם שהסיבוב הוא רק בשית אלפי שנין וא\"כ ה\"ז בהגבלה, הענין הוא דהתמדת הפעולה הוא שפעולת הסיבוב שלהם בכח נצחי היינו שאינו מוכרח כלל שיופסק, ומה שיופסק בשית אלפי שנין זהו ברצון הבורא שיופסק סיבובם, אבל עצם הסיבוב שלהם הוא באופן כזה שאינו מוכרח ההפסק ויכול להיות בבחי'\nבל\"ג. וכמו העדר ההפסדות שלהם הוא שאין בהם הפסדות כלל דדבר הנפסד הוא שבעת קיומו הוא נפסד, וצבא מעלה בעת קיומם אין בהם הפסדות כלל, הגם שאחר שית אלפי שנין יפסדו וכמ\"ש שמים כעשן נמלחו כו', הרי דבהקיום גופא אינו דומה קיומו של הנפסד לקיומו של בלתי נפסד. כמו\"כ בהסיבוב אופן הסיבוב של הגלגלים הוא בבחי' סיבוב נצחי וה\"ז רק מכח הא\"ס כו', ועוד שהן גופים רבים ובסיבובי' מיוחדים ומחולקי' זמ\"ז וכולם מכוונים לכוונה א', שא\"ז בכוונת עצמן כ\"א מכח עליון הבלתי מלובש בהם והוא כח ויכולת הבורא ית'. דהנה הגלגלים הם בעלי דעה"],[3601330353,"והשכל כמ\"ש הרמב\"ם בהל' יסוה\"ת, ובזה יכול לכוון סיבוב עצמו אבל לא סיבוב הזולת, וא\"כ מה שכולם מכוונים לכוונה א' א\"ז מכח עצמן כ\"א מכח שחוץ להם והוא כח הבורא ית' וכמ\"ש במ\"א, ועמ\"ש מזה בד\"ה מצה זו, רנ\"ה. הרי מהשמים נראה בראי' חושי' כח הא\"ס הבל\"ג כו'. ובמד\"ת ובילקוט אי' עפ\"ז משל לגבור שנכנס למדינה ולא היו יודעים מה כחו, א\"ל פקח א' מאבנא דהוא מתגושש בהון אתון יודעים גבורתו כך מהשמים אנו למדין מה כחו של הקב\"ה, ופי' מתגושש הוא כדאי' במשנה פ\"ב דחלה אימתי בזמן שהספינה גוששת, פי' הערוך שקרקעית הספינה נוגעת בקרקעי' הים, וכמו\"כ כאן מש\"א דהוא מתגושש היינו כח הקב\"ה שנראה ונגלה למטה ע\"י השמים כו', והיינו כח הא\"ס שנראה ונגלה בהם. וי\"ל שזהו שמגלים בחי' אחדות ה' יחודו בתחתונים, וז\"ע דהוא מתגושש בהם דפי' שנוגע בקרקע כו' היינו בחי' יחודו ית' בתחתונים, דהנה ידוע מ\"ש ה' אחד ואין אומרים ה' יחיד דהכוונה באו' א' שגם כמו שנתהוו העולמו' ה\"ה אחד לפי שכולם בטלים ביחודו ית' שז\"ע כד אמליכתי' כו' כידוע ומבו' במ\"א, שכ\"ז\nנראה בחוש בשמים איך שכח הא\"ס פועל והן בטלים בתכלית כו', והוא שבהתמדת הפעולה ובהסיבוב לכוונה א' נראה כח הא\"ס שפועל בהם ומנהיגם ואיך שהם בטלים בתכלית לאוא\"ס ב\"ה שמנהיגם כרצונו. ובפרט לפי הידוע דסיבוב עצמן הוא באופן אחר (היינו ממערב למזרח) והסיבוב שלהם להכוונה המיוחדת הוא בכח עליון המסבבם ומנהיגם באופן כזה, הרי נראה בזה איך שהן בטלי' בתכלית לבחי' א\"ס ב\"ה המנהיגם כרצונו ית', וזהו דהוא מתגושש בהון דמהז\"ר וארץ נראה ונגלה כחו דאלופו ש\"ע ואיך שהן בטלי' בתכלית לגבי א\"ס ב\"ה שהוא מנהיגם כרצונו ית'. גם ענין אבנא דהוא מתגושש הוא כדאי' במד\"ר בשלח ר\"פ כ\"ה ע\"פ הנני ממטיר הה\"ד כל אשר חפץ ה' עשה כו' כל מה שהקב\"ה חפץ לעשות עושה שהכל שלו כו', כשהמטיר אש וגפרית הי' מן השמים כו' והטל מן השמים כו', והמן מן השמים כו', ור\"ל שבין השפעת הדין והעונש הגדול ר\"ל ובין השפעת החסד הגדול אשר הם ב' עניני' הפכי' הכל נמשך מכלי א' דהיינו מהשמים, והו\"ע התכללו' חו\"ג שזהו ע\"י הגילוי דא\"ס הבל\"ג שעי\"ז דוקא יהיו התכללו' ההפכי'\nכו', וזהו ג\"כ ענין יקרא דה' שכ' הת\"י שהו\"ע לאסתכלא ביקרא דמלכא בבחי' התכללו' שנראה וניכר בהשמים כו', דענין היופי והיוקר הוא בהתכללו' הגוונים דוקא כו' וכמ\"ש בד\"ה מצה זו הנ\"ל, וגם התהוות השמים הוא מאש ומים דקיימי ברוחא עילאה כדאי' בזהר פ' לך לך דע\"ז ע\"א, דפי' רוחא עילאה הוא בחי' הת\"ת שכולל חו\"ג בכח אוא\"ס הבל\"ג המאיר בו כו' וכמ\"ש במ\"א.\n<span data-k=\"ks\"><b>קיצור.</b> והנה הע\"ס מגלים גם בחי' אוא\"ס הבל\"ג, וכמו השמים מספרים כבוד אל יקרא דה' והוא דבקיומם התמידי ברצון הבורא והתמדת פעולתם וסיבוב כולם לכוונה א', נראה בזה כח הא\"ס, ובמד\"ת מאבנא דהוא מתגושש בהם, מל' ספינה גוששת, והיינו הגילוי למטה והוא גילוי יחודו ית' שהשמים בטלים, וביותר שהסיבוב הוא היפך טבע עצמן, גם שמציאותם הוא באש ומים וקיימא ברוחא עילאה, ופועלים פעולת הפכים דחו\"ג, דההתכללות הוא מאוא\"ס הבל\"ג, וזהו יקרא דה'.</span>"],[3601330354,"ק) <b>ועד\"ז</b> יובן בע\"ס דאצי' שהן מספרים ומגלים את בחי' האוא\"ס הבל\"ג, דהנה אנו אומרים ותן בלבנו בינה להבין דהיינו להבין דבר מתוך דבר כו', דהנה ענין הבינה הוא בחי' תפיסת האור שבא בבחי' התלבשו' דוקא, וכמו עד\"מ כח הבינה בנפש שהיא להשיג כל ענין שכלי שבא בבחי' תפיסא בכלי מוחו, ולא כמו נקודת החכ' שאינה בבחי' תפיסא עדיין, דע\"ה שיודע את הענין בכללו' אין הענין אצלו עדיין בבחי' תפיסא ממש כ\"א בבחי' מקיף לבד שמרחף על מוחו ויודע רק כללו' הענין לבד כו', אבל במוח הבינה בא הענין בבחי' תפיסא ממש שיודע ומשיג אותו היטב איך ומה הוא כו'. וכמו\"כ הו\"ע הבינה למע' שהוא בחי' תפיסת האור בכלי דוקא שידוע ומושג כו', וזהו דש' ה' דבינה הוא בניקוד אלקי' דהיינו בחי' הכלים כו' וכמ\"ש במ\"א, וזהו שהבינה היא בחי' נשמה וכמ\"ש נשמת שדי תבינם דהיינו בחי' גילוי או\"פ, דכשם שהנשמה ממלאה את הגוף בבחי' התלבשו' בגילוי ממש עד שאנו יודעים ומשיגים את הכחות כו' (וכנ\"ל פצ\"ח בענין ידיעת המציאו' והשגת המהות כו'), כמו\"כ בינה שהיא בחי'\nנשמה ה\"ה בחי' השגה ותפיסא ממש בהאור כו' (וה\"ז יותר מהשגת כחות הנפש למטה שאינם השגת המהות ממש כמשנת\"ל, ולמע' בבחי' בינה הוא שמושג מהות האור והזיו כו', וכמו השגת הנשמו' בג\"ע שנהנין מזיו השכינה בבחי' השגת המהות ממש כו' וכמ\"ש במ\"א), וענין להבין דבר מתוך דבר הוא דמהשגה זאת בא לידי השגה אחרת ההפכי' מההשגה הקודמת, והיינו שמזה בא לידי השגה שבהכרח לומר שיש דבר הבלתי מושג כו'. ובמ\"א מבו' ענין להבין דבר מתוך דבר דהיינו שבא מהשגה זו על ענין אחר שאין לו לכאו' שייכות כלל להענין הזה, אמנם ג\"ז הוא בכלל מבין דבר מתוך דבר שמתוך השגה בא לידי השגה שיש דבר הבלתי מושג כו'. וענין מה שהשגה זאת הפכי מהשגה הקודמת הוא כי השגה ובלתי מושג ה\"ה הפכים זמ\"ז, וע\"כ מי שהוא בחוש ההשגה לא יהי' בו ענין העדר השגה והיינו שכל ענינו וכל התעסקו' שלו הוא בהשגת הענין היינו איך שהענין מושג לא בזה שהענין הוא למע' משכל המושג כו', והיינו שבכל ענין ההתעסקו' שלו הוא למצוא המושג שבו ר\"ל איך שהוא מושג ולהביאו לידי השגה לא למצוא בו איך\nשאינו מושג שא\"ז מהחוש שלו, להיות שהחוש שלו הוא בהשגה דוקא. וע\"ד שיש מתון ומסיק וחריף ומקשה שהן ב' חושים נבדלים דמתון ומסיק הו\"ע הירידה וההתגלות של המושכל כו' (בל\"א געפינען דיא רעכטקייט פון דעם ענין ווי דער ענין איז רעכט), וחריף ומקשה הוא להעלים ולהסתיר איך שעדיין אין הענין מובן כו' וכמ\"ש במ\"א, ה\"ה ב' חושים דמי שהוא מתון ומסיק אינו חריף ומקשה כו'. כמו\"כ מי שהוא בחוש ההשגה אין ענינו למצוא הבלתי מושג כ\"א כל ענינו והתעסקו' שלו למצוא את המושג כו', ובד\"כ התעסקו' שלו הוא בעניני' המושגים דוקא לא בעניני' שהן למע' מהשגה כו', ובכל ענין התעסקו' שלו הוא להשיג את הענין בלבושי השגה דוקא ולהיות בבחי' תפיסא דוקא כו', וע\"כ ההשגה וההרגש שיש דבר הבלתי מושג ה\"ז הפכי מעצם החוש שלו כו', ובפרט שהרי השגה הו\"ע בחי' יש וענין דלמע' מהשגה זהו בחי' ביטול כו' (וכמו חו\"ב שהן אין ויש כו'), דההרגש איך שיש דבר הבלתי מושג פועל ביטול בכלי מוחו ובחושים שלו כו' א\"כ ה\"ה הפכים זמ\"ז כו', ומ\"מ ה\"ה בא לידי ההשגה האחרת הנ\"ל, הנה\nבאמת זהו בבחי' פנימי' בינה דוקא, דחיצוני' בינה הוא להשיג ולתפוס כו', והשגה דחיצוני' בינה הוא בהאור האלקי כמו שבא בגילוי"],[3601330355,"ששייך בזה תפיסא והשגה כו', אמנם אחר שתופס ומשיג היטב את הענין האלקי ה\"ה בא מהשגה זו גופא לידי השגה פנימי' (מצד בחי' פנימי' בינה), דמאחר שזה הענין בא בהשגה בהכרח שזהו רק זיו והארה לבד שהרי העצמי' אינו בגדר התלבשו' ובגדר תפיסא, ומאחר שבא בבחי' התלבשו' ותפיסא ה\"ז רק הארה לבד ויש בחי' העצמי' שמופלא ומובדל מזה ובלתי מושג, דכללו' האור שבא בהשגה הוא באין ערוך כלל לגבי העצמות כו'. ומה שבא לידי השגה זו היא מבחי' פנימי' בינה דוקא לפי שזהו כמו יציאה מחוש א' לחוש אחר ההפכי כו', כי חוש ההשגה הוא רק להשיג כנ\"ל, וא\"כ מה שבא (בל\"א וואס ער קומט גאר ארוף) ע\"ז שיש מה שבלתי מושג ה\"ז התחדשו' היפך החוש שלו כנ\"ל, וביותר שהרי ההשגה הו\"ע הישות ומציאו' הדבר, והיינו דלבד מה שהשגה בעצם הוא בחי' יש הרי הענין המושג בהכרח שהוא בבחי' מציאו' דבר באיזה ציור דאז שייך בו השגה כו'. וע\"י ההשגה והתפיסא בכלי מוחו ה\"ז בא בבחי' מציאו' יותר כו', והבלתי מושג הרי אינו בבחי' מציאו' דבר דמשו\"ז אינו מושג, ופועל הביטול גם בהמושג היינו\nאיך שהמושג הוא באין ערוך כו', נמצא דהשגה הו\"ע המציאו' לא ביטול הדבר והבלתי מושג הוא בעצם בבחי' בלתי מציאו' ועוד בבחי' ביטול הדבר המושג כו', א\"כ ה\"ז היפך מציאו' הכח דחיצוני' בינה כו', ולכן באמת בחיצוני' בינה אין כח ההשגה הזאת רק השגת הדבר ומציאותה כו' כ\"א הכח הזה הוא בבחי' פנימי' בינה דוקא כו'. וזהו שנק' מבין דבר מתוך דבר כמו הבנה חדשה דהגם שבאה מההשגה הקודמת ה\"ה הבנה חדשה והפכי' מההבנה הקודמת ובאה דוקא ע\"י ההבנה הקודמת, דאם לא יהי' המושג אין הכרח על הבלתי מושג כ\"א ההשגה היא אשר תכריח את השגת והרגש הבלתי מושג כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכמו\"כ הע\"ס מגלים בחי' אוא\"ס הבל\"ג, דהנה א\"א ותן בלבנו בינה להבין דבר מתוך דבר, בינה היא השגה ותפיסא בכלי, ולכן נק' נשמה או\"פ, ומתוך ההשגה בא לידי השגה שיש דבר הבלתי מושג, והיא השגה הפכיות מהקודמת, דחוש ההשגה היא למצוא בכל ענין את המושג לא הבלתי מושג, מתון ומסיק חריף ומקשה, גם השגה היא יש והמושג הוא מוגבל בציור ובא בבחי' מציאות והבלתי מושג הוא לא במציאות וידיעת והרגש הדבר ופועל ביטול בהמושג, הרי שזה התחדשות, ובא מתוך ההשגה, דמאחר שמושג ה\"ז הארה ויש הבלתי מושג, והוא בחי' פנימיות בינה.</span>\nקא) <b>והנה</b> פנימי' בינה היא ג\"כ השגה (דבינה בכלל הו\"ע השגה כו'), וההשגה בזה באה ג\"כ מבחי' חיצוני' בינה (דכשם שכללות ההשגה הזאת שיש מה שבלתי מושג הוא מה שמוכרח מתוך ההשגה כו' כנ\"ל, כמו\"כ השגת ענין הבלתי מושג הוא מהאור הנגלה המושג כו'), רק שהיא השגה אחרת והוא השגת ענין ההפלאה דעצמו' אוא\"ס ב\"ה כו'. והענין הוא דהנה ידוע שיש ידיעת החיוב וידיעת השלילה, ידיעת החיוב הוא שמשיג מהות הדבר מה הוא והו\"ע תוארי החיוב שמתארי' את הדבר במהותו ומציאותו כו', ותוארי השלילה הוא שאינם מתארים את הדבר כ\"א ששוללים ממנו את ההיפך, וכמו שם חכם הוא לא לתאר במדרי' החכ' כ\"א לשלול את ההיפך מהחכ' כו'. וידוע דתוארי השלילה הן באוא\"ס שלמע' מהשתל' בחי' סוכ\"ע בכלל דאינו שייך שם שום תואר שהרי אוא\"ס מופשט מכל"],[3601330356,"תואר כו', כ\"א שייך שם תוארי השלילה, דאנו אומרי' עד\"מ שם חכם הכוונה לא לתאר במדרי' החכ' כ\"א לשלול כל מה שהוא היפך החכ' כו' וא\"כ ה\"ז חכ' עכ\"פ, ולכאו' מהו השלילה מאחר שסוף סוף הוא בחי' חכ', הענין הוא דהשלילה היא שאינו כלל מערך וסוג בחי' החכ' דהשתל' גם לא בהמקור דהשתל' כו' (דאל\"כ לא היו צריכים לשלול שה\"ה חכ' רק שהיא במדרי' עליונה הרבה יותר, וכמו ח\"ס לגבי חכ' הגלוי' ה\"ז מסוג בחי' החכ' כו', וכמשנת\"ל פצ\"ו דכח המשכיל עם היותו מושלל ממציאו' השכל אינו מושלל מענין השכל כו', ובאמת בחי' החכ' דהשתל' אינו נחשב חכ' לגבי עצמות א\"ס, וכמו עד\"מ גבי חכם גדול הרי חכמת החכם הקטן אינו נחשב חכ' כלל, וכמו\"כ ויותר מכן באין ערוך דלגבי עצמות א\"ס בחי' החכ' דהשתל' אינו נחשב לחכ' (ועמ\"ש לקמן בענין חכ' דתורה וחכ' דמע\"ב) וכמ\"ש כולם בחכ' עשית, וכמו שכל המעשי לגבי חכמת אלקית ומכ\"ש לגבי למעלה מהחכ' כו'). ונמצא במה שאנו אומרים תואר חכם רק בדרך שלילה הרי אנו שוללי' לא רק מההיפך דחכ' כ\"א גם מהחכ' דס' השתל' כו', ומאחר ששוללים\nבחי' החכ' דס' השתל' מאוא\"ס ב\"ה, הרי ע\"י ידיעת החכ' דס' השתל' במהותה ומציאותה ובפרטי המדרי' שבזה גבוה מעל גבוה כו', ואנו שוללי' פרטי אופני המדרי' והגילו' האלו מבחי' עצמו' אוא\"ס ב\"ה, יש עי\"ז ידיעה והכרה באופן ההפלאה דאוא\"ס ב\"ה בענין החכ' כו'. וכמו\"כ הוא בכל העניני' וכמו בענין היכולת ובענין החיות שנק' חי בעצם ולא בחיים כו' וכמ\"ש במ\"א, וכ\"ז אינו בבחי' מציאות מדרי' באוא\"ס, שהרי כ\"ז אינו בבחי' חיוב באוא\"ס כ\"א רק בדרך שלילה, והיינו דזה שאנו אומרים שזהו חכ' עכ\"פ הרי א\"ז בבחי' חיוב (דאז ה\"ז בבחי' איזה מדרי') כ\"א בבחי' שלילה שאנו שוללים את היפך החכ' ואנו שוללים את החכ' דסדר השתל', א\"כ מה שהוא בבחי' חכ' עכ\"פ א\"ז בבחי' איזה מדרי' כ\"א שזהו הפלאת אוא\"ס בענין החכ' וכן הפלאת אוא\"ס בענין היכולת וכו' (ועמ\"ש לקמן בעזה\"י בענין הספי' באוא\"ס הבל\"ג), ומפני שאינו באיזה מדרי' היינו באיזה מציאו' דבר ע\"כ ה\"ז באמת למע' מהשגה דלית מח' תב\"כ כו', רק שע\"י ידיעות ההשגה מה שאפשר להיות מושג וכאשר יודע לשלול העניני'\nמאוא\"ס ב\"ה יהי' קצת ידיעה בענין ההפלאה דאוא\"ס ב\"ה כו'. וי\"ל כמו בענין ההתאמתות מבו' במ\"א שע\"י הקדמת ההכרה בא לידי התאמתות שנותנים זה מלמע' כו', כמו\"כ ע\"י הקדמת ידיעת השלילה באים לידי ידיעת והרגש ההפלאה דאוא\"ס ב\"ה כו' (וכ\"ז שייך רק בבחי' חיצוני' דאוא\"ס השייך אל העולמו' כו'), ואם לא היו הגילוים מאתו ית' לא היינו יודעים כלל מציאו' ההפלאה ומכ\"ש שלא היו יודעים אופן ההפלאה כ\"א ע\"י הגילוים דהיינו הע\"ס יודעים מציאו' אוא\"ס ואופן ההפלאה דאוא\"ס ב\"ה כו', וגם מובן איך שכל הגילוי' הם באין ערוך לגבי אוא\"ס המופלא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה פנימיות בינה ג\"כ השגה, והיא ידיעת השלילה, ובאה מחיצוניות בינה שהוא ידיעת החיוב, דהנה השלילה בחכ' עד\"מ היא מהעדר החכ'. וא\"כ ה\"ה חכם, אך השלילה היא גם מהחכ' דהשתל', וא\"כ מידיעה טובה בבחי' החכ' יודעים ומכירים אופני ההפלאה דאוא\"ס בענין החכ', וכן ביכולת משלילת היכולת דהשתל' יודעים ומכירים ההפלאה בענין היכולת, וכ\"ז אינו מדרי' כ\"א הפלאה, וידוע מן הגילוי דוקא.</span>"],[3601330357,"קב) <b>והנה</b> מה שהאור הוא באין ערוך לגבי עצמו' ה\"ז בחי' ביטול האור, ומ\"מ א\"ז בבחי' ביטול אמיתי עדיין, והביטול האמיתי הוא מבחי' עצמו' אוא\"ס ב\"ה (היינו כמו שבאוא\"ס ידוע האין ערוך דהאור) דכולא קכל\"ח כו'. והענין הוא דהנה ידוע בהב' דעות דד\"ע וד\"ת שהן דעת המשפיע ודעת המקבל והן הפכים זמ\"ז, דד\"ת הוא דעת המקבל (הן בבי\"ע לגבי אצי' והן באצי' לגבי המאציל עליון כו'), והדעה היא שלמטה הוא היש ולמע' אין כו', וד\"ע היא דעת המשפיע שלמע' הוא היש האמיתי ולמטה אין כו'. ויובן זה בעולמו' בי\"ע לגבי אצי', דהנה עולמו' בי\"ע הם נבראים מחודשים מאין ליש בבחי' מהות ומציאו' דבר ממש ובבחי' הגבלה שאינם בערך הא\"ס כלל, ומ\"מ מתלבש בתוכם אור וחיות אלקי להחיותם שבא בהם בבחי' התלבשו' פנימי ממש שמורגש ומושג בנבראי', וכמו המלאכי' עליוני' שמשיגים את האור האלקי המתלבש בתוכם. וכידוע בענין השרפים שאומרים קדוש מפני שמשיגים את החיות שלהם ואיך שעצמו' אוא\"ס קדוש ומובדל כו', וכתי' שרפים עומדים ממעל לו דהיינו ממעל לש' אד'\nהמחי' אותם, שזהו מפני שמשיגים את החיות, וההשגה ה\"ה מקפת את הדבר המושג ע\"כ הם עומדים ממעל להחיות שלהם כו' וכמ\"ש במ\"א, ונודע ג\"כ דהשגת המלאכי' מה שמשיגים ההארה האלקי' זהו המזון פנימי שלהם כו', וזהו ג\"כ ההתחלקו' שלהם מה שמחולקים זמ\"ז שהרי אין להם גופים שיחלקו אותם כ\"א ההתחלקו' הוא בההשגה אלקי' ובאופן עבודתם שזה משיג באופן כך וזה באו\"א כו', ולפי אופן כזה הוא עבודתם (גם במדה א' באה' או ביראה כו'). וכן גם בנבראי' שלמטה מתלבש בהם ההארה אלקי' בבחי' פנימי' עד שמורגש בהם החיות כו', רק שלמטה האור מסתתר ביותר ואינו מורגש שהחיות הוא אלקו' כו' (ויכולים להיות ח\"ו היפך מאלקו', דמלאכי' עליוני' מפני שמרגישי' שהחיות הוא אלקו' אינם יכולי' כלל להיות היפך האלקו' ח\"ו, ובאמת גם למטה מה שאפ\"ל היפך ח\"ו זהו בכח הבחירה שהוא כח עליון מאד, אבל מצד החיות המתלבש בתוכו אא\"ל באו\"א, וכמו בלעם שא' לא אוכל לעבור את פי' ה' כו' ועמ\"ש באגה\"ק סי' כ\"ה בענין ה' אמר לו קלל כו'), אבל מרגישים את החיות (והם באמת לפי אופן החיות\nשבתוכם כו' כנ\"ל), והחיות הוא בהם בבחי' פנימי' בכל הנבראי' כו', וע\"כ צריך הכח האלקי המחי' אותם לצמצם עצמו בצמצום גדול שלא להשפיע רק הארה וזיו לבד שיהי' בערך להתלבש בנבראי' בע\"ג כו'. וג\"ז צ\"ל שההארה היא בבחי' מציאו' דבר מה להיות מושג ומורגש בנבראי' כו', והוא רק בחי' תחתונה שבמל' שנק' דבר הוי' שבא בבחי' התלבשו' בנבראי' דבי\"ע, אבל עצמי' בחי' המל' היא למע' מהתלבשו' בעולמו' ואינו מושג בהם כלל כו'. וז\"ע ד\"ת שלמטה יש היינו ההארה אלקי' שמושג בהם הוא בחי' יש היינו בבחי' מציאו' דבר וע\"י ההשגה בא בבחי' מציאו' יותר כו', ולמע' היינו בחי' העצמי' דמל' וכ\"ש מדרי' העצמי' דאצי' שלמע' מהשגתם הוא אין כו' (ונק' אין שאינו מושג וגם הוא באמת בחי' אין שאינו בבחי' מציאו' דבר דמשו\"ז אינו בהשגת הנבראים כו'). ומלמעלמ\"ט בחי' ד\"ע הוא להיפך דעצמי' המל' ומדרי' עצמי' דאצי' הוא בחי' יש האמיתי, ולגבי האצי' הרי כל דיירי ארעא כל\"ח, והיינו שגם ההארה שמאיר ומתלבש בנבראים ה\"ז רק הארה לבד וכל\"ח לגבי העצמי' ה\"ז בחי' אין כו',\nוכמו\"כ הוא באצי' לגבי אוא\"ס המאציל ב\"ה כו'. דהנה בד\"כ ב' המדרי' דד\"ע וד\"ת הן בהב' מדרי' דממכ\"ע וסוכ\"ע,"],[3601330358,"דממכ\"ע הוא שבא בבחי' התלבשו' פנימי בעולמו', והן האורות דאצי' שהם בבחי' התלבשו' בכלים, שההתלבשות היא בבחי' התאחדות ממש שהאור מורגש ומושג בהכלי כו' וכמ\"ש במ\"א באורך, וכללו' האור הזה הוא שבא ע\"י הצמצום שנמשך רק הארה לבד שהרי עצמו' אוא\"ס אינו בגדר התלבשו' בכלים כו', וגם בזה בחי' ד\"ת הוא דעת הנאצלי' שלמטה היש והיינו בחי' הארת המאציל שמאיר ומושג בהם כו', ולמע' הוא האין היינו בחי' אוא\"ס הסוכ\"ע שלמע' מהשגה כו', וכמו החכ' מאין תמצא שהכתר נק' אין מפני שאינו בבחי' מהות ומציאו' החכ' כלל ואינו מושג כלל בבחי' חכ' כו', וזהו מלמטלמ\"ע מן הנאצלי' אל המאציל הוא בחי' ד\"ת כו'. אמנם מלמעלמ\"ט מן המאציל אל הנאצלי' הוא בחי' ד\"ע שלמע' הוא היש האמיתי והוא בחי' עצמו' אוא\"ס ב\"ה ולמטה הוא האין שכל האורות והמשכות החיות להחיות העולמו' והנבראי' הם רק הארה לבד וכולא קמי' כל\"ח ממש ולכך נק' אין כו'.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר ענין ד\"ת וד\"ע, ד\"ת מלמטלמ\"ע שהנברא יש וגם ההארה המחי' הוא מציאות מושג, ועצמיות אצי' אין שאינו במציאות מושג, ומלמעלמ\"ט אצי' יש וההארה המחי' הנבראים היא אין, וכן באצי' האור שבכלים הוא מושג באצי' ה\"ז בחי' יש נאצל ולמעלה מאצי' אין, ומלמעלמ\"ט המאציל יש אמיתי והאור אין.</span>\nקג) <b>והנה</b> דעה זו יש ג\"כ בנאצלי' שזהו ג\"כ ענין מבין דבר מתוך דבר שמדבר השגה א' ה\"ה בא להשגה הפכי' מהקודמת כו', והוא דעם היות דהשגה דד\"ת הוא שההתהוות היא מאין ליש כו' (הן בנבראי' והן בנאצלי' כו'), דהיינו שהאור והגילוי הוא בבחי' מהות ומציאו' דבר המושג להם, וביטול האור לגבי העצמי' הוא רק מה שאינו תופס מקום לגבי העצמו' שאינו בערך כו', ה\"ה בא לידי השגה אחרת איך שלגבי עצמי' נהפוך הוא דהאור כל\"ח ואינו בבחי' מהות ומציאו' דבר כלל וה\"ה בחי' אין באמת כו' (וזה בא מההשגה הקודמת דמאחר שמתלבש בפנימי' ומושג כו' ה\"ז הארה לבד וא\"כ לגבי העצמו' ה\"ז בבחי' אין כו'). ועם היות דשני הדעות הפכי' הן דלד\"ת ההארה היא בבחי' מהות ומציאו' דבר ולד\"ע הוא בבחי' אין כו', הנה באמת מצד האוא\"ס ב\"ה שניהם אמת, וז\"ע אל דעות ה' דש' אל נושא ב' הדעות כו', דהנה מצד הרצון שבעצמו' להיות עולמו' מצד זה ההארה האלקי' היא בבחי' מציאו' דבר כו', ומצד העצמו' היא כל\"ח כו', והיינו שע\"י צמצום העצמו' הוא בחי' ד\"ת כו', אך ע\"י הרגש\nהעצמו' (שרש ומקור ההארה כו') הוא גילוי בחי' ד\"ע שבא לבחי' ביטול אמיתי כו'. ויש בהאור ב' הענינים שהרי האור בא ע\"י צמצום העצמו' ומ\"מ הוא בבחי' דבקו' בהעצם כו', דמצד הצמצום הוא בבחי' מציאו' אור ומצד הדבקו' שנרגש בו העצמי' הוא בבחי' ביטול דכולא קמי' כלא כו', ובפרטי' ה\"ז ב' מדרי' בהאור דמצד חיצוני' האור הוא בבחי' ד\"ת ובחי' פנימי' האור הוא בבחי' ד\"ע כו'. וכן מצד האוא\"ס הנה בחי' חיצוני' דאוא\"ס שהוא בחי' ראש ומקור לנאצלי' לגבי מדרי' זו האורות הן בבחי' מציאו' דבר מאחר שזהו בבחי' מקור עכ\"פ כו', ובחי' ד\"ע שבבחי' ביטול במציאו' הוא מצד הפנימי' דאוא\"ס שזהו מה שהדעת מחליף מקום הכתר בחי' פנימי' הכתר כו' וכמ\"ש במ\"א."],[3601330359,"<b>וז\"ע</b> ברישא חשוכא והדר נהורא, ברישא חשוכא הוא הצמצום הראשון שעי\"ז נמשך האור שהוא בבחי' מציאו' דבר כו', והדר נהורא הוא כמ\"ש באורך נראה אור באורך העצמי נראה אור שהוא בחי' האין של היש האמיתי דכולא קמי' כל\"ח כו'. וזהו ג\"כ בתחלה עלה במח' לברוא את העולם במדה\"ד וכמ\"ש בראשית ברא אלקי' כו', דבאמת הרי ההתהוות היא מש' הוי' רק שזהו הארת ש' הוי' הבא ע\"י ש' אלקי' כו', ואח\"כ שיתף עמו מדה\"ר היינו גילוי עצם ש' הוי' כו'. ובד\"כ הוא ההפרש בין ההמשכה דברה\"ע וההמשכה דמ\"ת, דההמשכה דברה\"ע הוא בבחי' ד\"ת וע\"י תומ\"צ ממשיכי' גילוי בחי' ד\"ע שז\"ע שיתף עמו מדה\"ר במ\"ת שנא' אנכי ה' כו'. ובכללות הוא בהאור גופא ב' המדרי' דמצד הצמצום הוא בבחי' מציאו' דבר, ומצד הדבקו' בהעצם הוא בבחי' כלא כו'. וזהו השמים מספרים כבוד אל דש' אל הוא הכולל ב' הדעות כו' כנ\"ל, ופי' כבוד אל הוא בחי' כבוד תתאה וכמ\"ש בזח\"א ד\"ח ע\"א דא כבוד כלה, והוא בחי' ד\"ת שלמטה יש ולמע' אין שאינו מושג, וע\"כ נק' כלה מל' כלתה נפשי דמפני שאינו מושג נעשה הצמאון כו',\nוהשמים מספרים ומאירים בחי' הכבוד להיות בהם גילוי ד\"ע ע\"י הרגש העצמו' שנעשה בהם הביטול והו\"ע השוב כו' וכמ\"ש במ\"א, וכ\"ז הוא בבחי' האור להיותו דבוק במקורו כו' דגם בחי' הרצוא הוא מצד הדבקו' וכמשנת\"ל פצ\"א בענין טבע האש כו', וכ\"ש בחי' השוב שזהו מצד גילוי העצמו' ה\"ז מצד הדבקו' דלהיותו דבוק במקורו יש בו הרגש העצמו' כו'. וזה\"ע שהאורות להיותן בבחי' אצי' ה\"ה מספרים ומגלים גילוי בחי' דעה העליונה איך שכולא קכל\"ח כו', והביטול הוא בהאור גופא שהוא בבחי' מציאו' דבר ה\"ה בבחי' ביטול דכלא מצד הרגש העצמי' כו' (שזהו בדוגמא בחי' יחודו ית' בתחתוני' כו'), והגילוי הזה הוא באצי', וע\"י תו\"מ נמשך הגילוי דד\"ע גם למטה שהרי זה ההתחדשות דהיחוד דמ\"ת לגבי ברה\"ע כו' כנ\"ל. וז\"ע מה שספי' הוא ל' ספור והגדה שזהו למע' מבחי' מספר שהוא בחי' מל', וענין הספור הוא בד\"כ במדרי' שלמע' מהמל' והוא שהכלים מגלים את האור כו', וגם שע\"י הכלים והאורות הוא בחי' גילוי אלקו' בעולמו' כו' (דהגבלת המספר הוא להיות בחי' המציאות דעולמו' והספור הוא\nבד\"כ להיות גילוי אלקו' בעולמו' כו'). ובפרטי' הוא בבחי' האורות דאצי' שמגלות המחשבות הנעלמו' שהן מקורי הספי' כו', וגם מגלים בחי' האוא\"ס הבל\"ג לידע בחי' האוא\"ס המופלא ומרומם ואופן ההפלאה כו', והיינו לידע מציאו' האוא\"ס ואיך הוא האוא\"ס ב\"ה, ואיך שלגבי עצמו' כולא קכל\"ח כו', שהגילוי הוא באצי' וע\"י תומ\"צ הגילוי גם למטה כו', דלולא האצי' לא היו כל הגילוים האלו כ\"א ע\"י התהוות האצי' דוקא שהוא בבחי' גילוי ההעלם הם כל הגילוי' האלו כו'. וז\"ש בס\"י ודברו בהם ברצו\"ש הרי גילוי האורות דאצי' הוא בחי' דבור (והן רצו\"ש בחי' ד\"ת וד\"ע כו' כנ\"ל), וגם ודברו הוא בחי' מל' דא\"ק או מל' דא\"ס שז\"ע בחי' ספור להיות בחי' גילוי אור כו'. וי\"ל דז\"ש הרש\"ט כמו שהדבור והמכתב יבאר כו', הדבור הוא בחי' האור והמכתב הו\"ע הכלים, וכמ\"ש בלק\"ת ד\"ה זאת חקת התורה ובהבי' דאם בחקותי דהכלים דאצי' הן ע\"ד אותי' הכתב כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ואלה תולדות יצחק, דהנה הרמ\"א הביא בשם הפסיקתא ע\"פ ויצא הראשון אדמוני ששאב את הדם נדות, ואומר דהנה בכדי"],[3601330360,"שישראל יקבלו את התו' הי' צ\"ל שיפסוק מהם זוהמת הנחה\"ק וכמא' ישראל שעמדו כו' פסקה זוהמתן כו', ובתחלה הי' זה בהאבות שהם עשו הכנה למ\"ת דאאע\"ה ע\"י שנתנסה בהנסיונות נמרק חלק רב מזוהמת הנחש, ובכדי להוליד את יצחק הי' צ\"ל תחלה ישמעאל שבזה נפרדו מאתו הסיגים והפסולת, וכמא' אברהם יצא ממנו ישמעאל יצא בבחי' הפרדת הפסולת כו' וכמ\"ש במ\"א, ובשרה הי' צ\"ל חדל להיות לה אורח כנשים דדם נדות הוא מזוהמת הנחש כו', וע\"כ הי' צ\"ל לידת יצחק דוקא לאחר שחדל כו', והקצת סיגים שנשארו בו הי' צ\"ל המירוק דעקדה כו', וגם יצא ממנו עשו בבחי' יציאת והפרדת הפסולת כו', וגם שאב את דם הנדות מרבקה כו', ואז יצא יעקב נקי ומזוכך כו'. וזהו ואלה מוסיף על הראשונו' דכמו שבאברהם יצא ממנו ישמעאל בשביל יצחק, כמו\"כ ביצחק יצא ממנו עשו בשביל יעקב שיהי' נקי ומזוכך כו'. והענין דלהיות שענין התורה הוא שיהי' עי\"ז גילוי ד\"ע שזהו הגילוי דבחי' עצמו' אוא\"ס ב\"ה כנ\"ל הי' צ\"ל פסקה זוהמתן כו', וע\"ד מ\"ש בלק\"ת ד\"ה למנצח על השמינית דבכדי שיהי' גילוי בחי' יסוד\nדא\"ק צ\"ל העברת הערלה וגם עור הדק בפריעה כו', וכמ\"ש במ\"א בענין שכר מצוה בהאי עלמא ליכא מפני שכ\"ז שיש מציאו' הנוגה אא\"ל הגילוי דעצם אור המצות כ\"א כאשר יהי' וחד חרוב כו'. וזהו ואלה מוסיף כו' שצ\"ל הפרדת הפסולת בכדי שיהי' הגילוי דתו' כו', וזהו שהוא בשביל יעקב שהוא בחי' התו' וכמ\"ש ויקם עדות ביעקב כו', וזהו ואלה תולדות יצחק דתולדותיהן ש\"צ הן תו' ומע\"ט ובכדי שיהי' התגלו' התו' צ\"ל ואלה מוסיף הפרדת הפסולת כו'. והנה במאור עינים פי' ואלה מוסיף שמוסיף ומרחיב מקום הקדושה והיינו ע\"י הבירורי' שזהו בבחי' ד\"ת דהרי ד\"ת הו\"ע ביטול היש שזהו\"ע הבירור כו', וזהו שפרש\"י יעקב ועשו האמורים בפרשה דעשו הוא שמוסיף על ישמעאל בהפרדת הפסולת שזהו ג\"כ בשביל יעקב כו', ויעקב הוא בחי' י' עקב שמברר למטה שבזה מוסיף ומרחיב מקום הקדושה כו'. וזהו ג\"כ מ\"ש יצחק בן אברהם אברהם כו', דהנה יצחק הוא בחי' היראה וכמ\"ש ופחד יצחק כו', וידוע שיש ב' בחי' יראה יר\"ת ויר\"ע יר\"ת בחי' ד\"ת ויר\"ע בחי' ד\"ע, וז\"ש יצחק ב\"פ הא' בחי' יר\"ת והב' בחי' יר\"ע\nכו', ואברהם הוא בחי' אה' ויש באה' ג\"כ ב' מדרי' אה\"ע ואה\"ר, דאה\"ע הוא שבא ע\"י השגת החיוב שהוא האה' שע\"פ טו\"ד כו', ואה\"ר באה ע\"י השגת השלילה וידיעת ההפלאה דאוא\"ס כו', והסדר הוא יר\"ת ואה\"ע ואח\"כ אה\"ר ויר\"ע, וזהו יצחק בן אברהם יר\"ת ואה\"ע והן ד\"ת וידיעת החיוב כו', אברהם הוליד את יצחק אה\"ר ויר\"ע שהן ידיעת השלילה ובחי' ד\"ע כו'. וזהו ואלה תולדות יצחק שבשביל הגילוי דתו' צ\"ל הפרדת הרע והפסולת וגם הבירורים שמוסיפים ומרחיבים מקום הקדושה והו\"ע יעקב ועשו האמורים בפרשה כו', ויצחק בן אברהם ואברהם הוליד את יצחק הן בחי' ד\"ת וד\"ע וידיעת החיוב וידיעת השלילה שכ\"ז מגלים הספי' דאצי', והגילוי הוא למע' וע\"י התו' נמשך הגילוי גם למטה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויש גם ידיעה זו דד\"ע ובא מהמושג דד\"ת שמזה מובן שלגבי עצמות הוא אין, ושניהם אמת דמצד הרצון בהתהוות ה\"ז מציאות, ומצד העצמות ה\"ז כלא, וכן בהאור מצד הצמצום הוא בבחי' מציאות ומצד הדביקות הוא כלא, ובפרטיות הוא בחיצוניות האור ופנימיות האור, וכן מצד אוא\"ס ד\"ת מבחי'</span>"],[3601330361,"<b>חיצוניות</b>, וד\"ע מבחי' הפנימיות, וזהו ברישא חשוכא ד\"ת והדר נהורא ד\"ע, וזהו כבוד אל ד\"ת ומספרים ומגלים בחי' ד\"ע, וזהו שמגלים בחי' אוא\"ס הבל\"ג. ובזה יובן מ\"ש ואלה תולדות יצחק, דבשביל התורה ד\"ע צ\"ל הפרדת הפסולת, ובמ\"ע שמרחיב היינו הבירורים דד\"ת וזהו ג\"כ ב\"פ אברהם וב\"פ יצחק ד\"ת וד\"ע."],[3601330362,"<h3>בס\"ד. ש\"פ ויצא, תער\"ג</h3>\n<b>והאבן</b> הזאת אשר שמתי מצבה יהי' בית אלקי', וצ\"ל מהו\"ע מצבה דמה נתחדש בזה לגבי מה שהי' בתחלה אבן סתם ועשאה מצבה כו'. גם אינו מובן מ\"ש והאבן הזאת כו' יהי' בית אלקי' איך אפ\"ל בית מאבן א', הלא בית עשוי מכמה אבנים, וכאן הרי הי' אבן א' דוקא וכמ\"ש תחלה ויקח מאבני המקום כו' ואח\"כ ויקח את האבן כו' שנעשה אבן א' כו', ואיך מאבן א' יהי' בית כו', וגם דהול\"ל תהי' בית אלקי' כמ\"ש קודם והאבן הזאת ל' נקבה ומהו אומרו יהי' ל' זכר. ולהבין כ\"ז ילהק\"ת משנת\"ל ב' פי' בש' ספי' ל' מספר ול' סיפור, ונת' דכללו' ענין המספר הוא בכלים דאורות הן למע' מבחי' מספר, ונת' דעיקר ענין הגבלת המספר הוא בבחי' המל', וענין הסיפור הוא מה שהכלים מגלים את האור וזה גם בכלים שלמע' מבחי' המל' וגם מה שכללו' הספי' אורות וכלים מגלים אלקו' היינו שעי\"ז יהי' גילוי אלקו' בעולם, ועיקר ענין הסיפור הוא בהאורות שמגלים המחשבות הנעלמו' היינו הע\"ס הגנוזו' שרשי האורות וגם מגלים את האוא\"ס הבל\"ג היינו ההפלאה דאוא\"ס ב\"ה.\nקד) <b>והפי'</b> הג' בספי' הוא מל' אבן ספיר שהוא מורה ענין הבהירו', וזהו לחלק בכלל בין הכלים ללבושי', שהכלים אינם מסתירים על האור כו', דהלבושין הן מעלימי' ומסתירים על האור, והכלים דאצי' הן בבחי' בהירות שהאורות המלובשי' בתוכם אינם מכוסים ומוסתרי' ע\"י כ\"א הם מאירים ומתנוצצים ע\"י שאין הכלי מסתיר על האור. וכמו עד\"מ זכוכית בהירה מאד שהאור השמש שעובר דרך בה לבית מאיר ומתגלה אורו מאד ואין הזכוכית מסתרת ומחשכת האור לגודל בהירותה כו'. כמו\"כ הכלים דע\"ס אינם מסתירים על האור, אדרבה מגלים אותו כו'. והענין הוא דהנה במא' פתח אליהו אי' אנת הוא דאפיקת עשר תיקונין וקרינן להון עשר ספירן כו', שהע\"ס נק' תיקונין ופי' תיקונין הן לבושי' וכמ\"ש לא ילבש גבר ות\"א לא יתתקן גבר כו', ולכאו' מפני מה נק' לבושי' בש' תיקוני'. אך הענין ידוע דמ\"ש לא יתתקן גבר קאי על התכשיטין שלא יתקשט גבר בתכשיטי נשים כו', והתכשיטין עם היותם לבושי' אינם דומים לשארי לבושי' בזה שהאדם מתקשט בהם והיינו שהם מתאחדים עם האדם שמתפעל מהם\nומתייפה על ידן כו'. כי יש שני מיני לבושים הא' לבוש הנפרד שמעלים ומסתיר על האדם, והב' לבוש המיוחד שאינו מעלים עליו אדרבה מגלה אותו כו', וכמו עד\"מ הלבושי' שהאדם מתלבש בהם הרי כל ענינם הוא להתכסות בהם ולהסתיר עצמו מן הזולת"],[3601330363,"כו', וכאשר האדם הוא בפ\"ע א\"צ ללבוש כ\"א לגבי הזולת צריך לכסות א\"ע וכן לעצמו מפני הקור וכה\"ג, והיינו שלגבי דבר שחוץ ממנו צריך לבוש לכסות ולהגן עליו כו', ויש כמה מיני לבושי' וכמו לבושי הראש ולבושי הגוף ולבושי הרגל העשוי' מעור שהן עבים ביותר כו', והיינו שלפ\"ע הדבר שחוץ ממנו כ\"ה הלבוש כו'. ובאמת הלבושי' הן ג\"כ לפ\"ע המתלבש, דע\"ה שהן לבושי' נפרדים מ\"מ הן לפ\"ע המלובש דלפ\"ע דקות ועביות המלובש כ\"ה הלבוש, וידוע דבג' חלקי הגוף ראש גוף ורגל הרי הראש דק יותר והרגל עב ביותר לפיכך הן מחולקי' בהלבושי', אך ע\"פ פשוט הוא לפ\"ע הדבר שמבחוץ דברגל הולך גם במקום רפש וטיט ע\"כ צריך לבוש עב יותר להגן עליו כו'. וכללו' ענין הלבושי' הוא לכסות ולהסתיר על הגוף כו', ואדה\"ר קודם החטא לא הי' צריך ללבושי' המסתירים על הגוף מפני שבעצם לא הי' בבחי' זולת, וגם הי' מרוחק מהדברים שחוץ ממנו והיינו שהי' מרוחק ומובדל מן הרע וע\"כ לא הי' צריך ללבושי' המסתירים, כ\"א אחר החטא הוצרך ללבושים המסתירים כו'. והנה הגוף הוא ג\"כ לבוש וכמ\"ש עור\nובשר תלבישני, אך אין ענינו להסתיר כ\"א שבתוכו יתלבש אור וחיות הנפש ויתגלה ע\"י כו', שהרי כל כחות הנפש ההתגלות שלהם הוא ע\"י אברי הגוף, כמו כח הראי' בעין וכח השמיעה באזן הרי לולא חומר העין או חומר האזן לא הי' ענין הראי' והשמיעה כו', כי הנפש קודם התלבשותו בגוף הכחות הם בבחי' התכללות והתעלמו' בנפש ואינם מתגלים כלל כו'. והענין הוא כמשנת\"ל פצ\"א שהאור הוא בבחי' התכללו' במקורו כשאין לו דבר הנאחז כו', כמו\"כ הכחות כשאין להם כלי שיתאחזו בהם ה\"ה בבחי' התכללו' בנפש ואינו שייך ענין הראי' והשמיעה כלל כו', ומה שמבו' במ\"א דהנשמה רואה ושומעת הכרוזים למע', זהו ג\"כ ע\"י לבוש שעי\"ז הוא התגלו' הכחות, כי גם הנשמה למע' יש לה לבוש רק שאינו בבחי' גוף כמו במלאכים שיש להם גופים (והם מהיסודו' הדקים כו'), והנשמות למע' אין להם גוף כו' וכמ\"ש במ\"א, אבל מ\"מ יש להנשמה למע' לבוש והוא לבוש דק ורוחני שאינו מעלים, ולכן בו וע\"י הנפש רואה ושומעת כו', וכן ע\"י חומר העין והאזן הוא התגלו' הכחות דראי' ושמיעה וגם לראות ולשמוע דברים\nהגשמיים כו'. וזהו מה שאברי הגוף מגלים את הכחות היינו שיתגלו ויפעלו גם בדבר שחוץ מהם, דהכחות דראי' ושמיעה עד\"מ מצ\"ע אינם בערך לפעול בדבר הגשמי' והאברי' מביאים ומגלים אותם גם בדברי' הגשמי' כו', וכמו\"כ כח השכל להשכיל הוא ע\"י חומר המוח דבלעדי זאת ה\"ה בהתכללו' בנפש ואינו שייך להשכיל דבר כו', והשגת הנשמו' בג\"ע הוא ג\"כ ע\"י לבוש שיש להנשמה שעי\"ז היא מצטיירת בכחות ששייך בה השכלה והשגה כו', וע\"י חומר המוח הוא גילוי אור השכל להשכיל השכלו' גם בעניני' החומרי' כו'. הרי כל ענין הגוף הוא להיות התגל' אור הנפש ולפעול ע\"י כו', וזהו הלבוש המיוחד שמתייחד עם הנפש ומגלה אותו כו', וכמו בגשמי' הגוף שא\"א לפושטו ולהחליפו כמו הלבושי' שפושט ולובש כו', והיינו מפני שהוא הלבוש המיוחד, וכ\"ה בפעולתו לגבי הנפש שהגוף הוא לבוש המיוחד שענינו לגלות ולהביא את הכחות לידי פעולה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> הפי' הג' בספי' ל' אבן ספיר, והוא שהכלים מגלים את האור, ולא כמו לבושים. ויבאר הענין דהנה יש לבוש הנפרד כמו לבושי האדם שענינם</span>"],[3601330364,"<b>לכסות</b> הגוף ולהסתירו מדבר שחוץ ממנו, ויש לבוש המיוחד כמו הגוף שהאברים מגלים, כי לולא זאת היו בהתכללות בנפש, וגם התגלות כחות הנשמה קודם התלבשותם בגוף הוא ע\"י לבוש רוחני.\nקה) <b>והנה</b> כמו בגשמיות לבושי הגוף הן לכסות ולהסתיר ולבוש הגוף הוא לגלות, כמו\"כ יובן שיש ב' מיני לבושי' הנ\"ל ברוחני' הנפש שהן כחות הנפש ולבושי' דמחדו\"מ, דהנה ידוע דכחות הנפש שהן שכל ומדות אינן עצמי' הנפש, וראי' לזה הוא מה שיש בהם שינוים דקטנות וגדלות וכמו ימים דברו ורוב שנים יודיעו חכ', שהקטן שכלו ומדותיו קטנים וכשיגדל נתגדל שכלו וגם מדותיו הם בדברים גדולי הערך כו', וה\"ז הוראה שאינם עצמי' דכל עצם אינו משתנה כו', והגם שהשינוי הוא מצד הכלים ואברי הגוף דהקטן כלי מוחו קטנים ואינם כלים לקבל אור השכל ע\"כ השכל הוא בהעלם (דבהעלם יש בו אור השכל הגדול גם בקטנותו וכמ\"ש בוצין בוצין מקטפוהי ידיעא כו' רק כשאין כלים ה\"ה בהעלם כו') וכשמתגדלים כלי מוחו מתגלה האור כו', הנה מזה גופא מובן שאינו עצמי כי העצמי אינו נוגע לו הכלי אם היא בקטנו' או בגדלות כו'. וכמו בקישור וחבור עצם הנפש מה שהוא מוגדר בגוף אינו נוגע בזה כלל קטנות וגדלות הגוף כו' (וזהו מפני שאינו בא בבחי' התלבשות בדרך אור וכלי כו', אך הא\nבהא תליא דמפני שהוא עצמי אינו בא בהתלבשו' ומה שבא בהתלבשו' ה\"ז הארה לבד כו'), וכח השכל שיש שינוי בהמשכתו והתגלותו לפי אופן קטנות וגדלות הכלי, ה\"ז הוראה שאינו עצמי כו', וה\"ה רק כמו לבושי' וכלים אל הנפש שהנפש פועלת בהם וע\"י, וכמו שהנפש משכלת ע\"י כח השכל ומתחסד ע\"י כח החסד כו'. ומ\"מ ה\"ה לבושי' מיוחדים שה\"ה כחות נפשיים והן ממהות הנפש וממילא ה\"ה מיוחדים עמו (שבאם לא היו מיוחדים לא היו ממהותו ולא היו נפשי' כו'), ובפרט כח השכל שמתאחד עם הנפש עד שהנפש נק' ע\"ש נפש המשכלת כו', וכמו\"כ כל הכחות המה מיוחדים כו'. משא\"כ לבושי' דמחדו\"מ הם לבושי' נפרדים שהרי אינן מסוג הנפש וממהותו וה\"ה כמו דבר בפ\"ע מהנפש, וממילא אינם מיוחדים עם הנפש, וע\"כ הם מסתירים על אור הנפש כו'. והגם דמחדו\"מ ג\"כ ענינם לגלות אור הנפש כו', מ\"מ הרי האותי' בעצם מהותם הם מעלימים, וכמו אותי' הכתב הרי מי שאינו בר שכל וכמו התינוק אינו יודע מאומה מן האותי' הרי שהן מעלימים בעצם כו', וכמ\"ש בלק\"ת ד\"ה והניף ידו כו', וכן אותי' הדבור ה\"ה מעלימי'\nבעצם וכמו כשידבר דבר שכל לפני מי שאינו בר שכל הרי הגם שיודע את הדבור לא ידע את השכל כלל כו', וע\"כ הגם שהן מגלים יש בהם התעלמו' ג\"כ כו', אבל הכחות הרי אינם מעלימים בעצם מהותם אדרבה מגלים כו' (וכמו גם הגוף שאינו מעלים על החיות שהרי נראה ונגלה שהגוף חי, והיינו שגם בלי תנועה נראה ונגלה בהגוף שהוא חי וזהו מפני שהוא לבוש המיוחד כו'), והיינו מפני שהם בבחי' לבוש המיוחד ה\"ה מגלים את הנפש כו' (והנה הכחות הן ג\"כ מעלימים על הנפש, והראי' שהרי בהתגלות אין הנפש מאיר בגילוי, וכידוע דכאשר הכחות הן בהעלם אזי העצם הוא מתגלה, וכאשר הכחות הן בגילוי אזי העצם בהעלם כו', וא\"כ מובן מזה דהתגלות הכחות הוא ע\"י העלם עצם הנפש. אך ענין ההעלם דהכחות על הנפש הוא שאין הפנימיות ועצמיות אור הנפש מתגלה בהם רק בחי' חיצוניות אור הנפש, משא\"כ בלבושים דמחדו\"מ הוא שמעלימים על"],[3601330365,"האור המתלבש בתוכם. והנה נעריך המשל דכחות הנפש על בחי' הכלים דענין ההעלם שלהם הוא זאת שאין הפנימיות מתגלה בהם, מבו' במ\"א שזהו בבחי' כלים שבכתר, אבל כלים דאצי' הוא שמעלימים על האור המתלבש בתוכם וכמשית\"ל פקכ\"א, וזהו שהאור נעשה כמהות הכלי, אך צ\"ל בכללות הוא ההפרש בין בחי' פנימיות הכלים וחיצוניות הכלים, דפנימיות הכלי הוא שהכלי הוא כמו האור וענינה הוא לתאר ולגלות את האור (וכמשי\"ת לקמן), וחיצוניות הכלי הוא שמעלים על האור ולפעול כפי מהות הכלי כו', ועמש\"ל דחיצוניות הכלים הן בחי' לבושים כו' ועמשנת\"ל פצ\"ג, ובמ\"א מבו' המשל דכחות הנפש על האורות דאצי' כו'). ולכן האותי' דמחו\"ד יכולים להחליף דשכל המלובש באותי' אלו יוכל להלבישו באותי' אחרים, משא\"כ בשכל ומדות כשהשכל מאיר בהמדות ונמשך ממנו מדות אלו לא שייך לומר כן שכך יכול להלביש שכל זה במדות אחרים, כי השכל המעורר את האה' אינו אותו שכל המעורר את היראה כו'. ונמצא השכל והמדות מתאחדים זע\"ז ואין המדות לגבי השכל כלבוש ודבר נפרד כו', וכן כללו' השכל והמדות לגבי\nעצם הנפש שא\"א שישכיל באופן אחר מעצם מהות נפשו כו', וכמו הנשמה האלקי' שכלה ומדותי' הכל באלקו' ואינו שייך בה השכלה אחרת ח\"ו. וכנודע בנה\"א ונה\"ב דנה\"א כל ההשכלות וההשגו' שלה הכל באלקו' ואין הנפש מסוגלת כלל לעניני' אחרים, והנה\"ב להיפך השכלתה והשגותי' רק בעניני הטבעי' כו', ורק ע\"י התלבשו' הנה\"א בנה\"ב ישכיל הנה\"א באלקו' ע\"י העניני' הטבעי', וכן פועלת בהנה\"ב שגם היא תבין ענין אלקי כו' וכמ\"ש במ\"א, אבל מצד עצם מהותם ה\"ה מחולקי' ומובדלי' זמ\"ז לגמרי בכל הכחות שלהם כו', וניכר הדבר ביותר גבי בע\"ת שמתחלה ההשגות והמדות הן רק להיפך מאלקו' ר\"ל, ואח\"כ ע\"י התשו' משתנים מהקצה אל הקצה שכל ההשכלו' וההנחות שבנפש וכן כל המדות הכל הוא לטוב כו', והיינו מפני שבתחלה היו הכחות דנה\"ב בהתגלו', וע\"י התשו' מתגלים הכחות דנה\"א כו'. הרי שלפי מהות הנפש כך הם הכחות שאא\"ל באו\"א כו', וכן כפי מהות נפשו בשרשה מבחי' חו\"ג כ\"ה שכלו והשגתו וכמו ב\"ש וב\"ה כו', ובד\"כ מה שזה תופס הענין שכלי באופן כך וזה באו\"א הוא מצד הנפש כו' (והגם שיש\nחילוקי' ג\"כ באותי' המלבישי' את השכל שזה אומר באותי' אלו דוקא וזה באותי' אלו דוקא שזהו ג\"כ מצד הנפש כו' וכמ\"ש במ\"א, זהו מן עצם מהות הנפש שלמע' מהגילוים דנפש כו' דמ\"מ בהגילוי' יכול לומר את השכל גם באותי' אחרים, ויכול להיות שבאותי' אחרים אין אור שכלו מתגלה כ\"כ (בא עם ווערט ניט אראפ גיטראגין דער שכל אזוי פיל אין די אותי' כמו שבאם הי' אומר אותם באותי' שלו), והיינו מפני שבהאותי' האחרים אינו מוצא את הענין כ\"כ כמו באותי' שלו אבל מ\"מ אינו נמנע הדבר ויכול לו' ג\"כ השכל באותי' אחרים, משא\"כ בשכל הרי א\"א שישכיל באו\"א שבאם הי' משכיל ג\"כ כמו הזולת הרי הי' בדעה א' אתו כו' רק מפני התכללו' הכחות יכול להיות מקולי ב\"ש כו'), ודבר זה נראה בחוש איך שהכחות מיוחדים עם הנפש ומגלים את הנפש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכמו\"כ בנפש לבושי מחדו\"מ ה\"ה מעלימים על האור המלובש בהם ועי\"ז הם מגלים, אמנם הכחות שכל ומדות שהן ג\"כ לבושים לגבי עצם הנפש, אבל הם מיוחדים וענינם הוא לגלות, ולכן האותיות יכולים להחליף (ואותיות</span>"],[3601330366,"<b>כאו\"א</b> הן מעצם מהות הנפש לא לפי השכל), משא\"כ א\"א להחליף, וכמו בשכל הנה\"א ונה\"ב, ולפי אופן שרש הנפש בחו\"ג כן הוא השכל והמדות.\nקו) <b>והדוגמא</b> מזה יובן למע' דהכלים דאצי' אין ענינם להעלים ולהסתיר ח\"ו, כ\"א תכלית ענינם הוא לגלות אוא\"ס, ועש\"ז נק' ספי' ל' ספירות ובהירות כו' וכמ\"ש כמראה אבן ספיר דמות כסא דכמו אבן ספיר הוא אבן טוב המזהיר, כך עד\"מ דמות כסא שהיא בחי' המל' דעם היות שהיא בחי' היותר אחרונה שבאצי' והיא שרש ומקור בי\"ע שבאצי', ושם הוא עיקר ענין הכלים ובבחי' הגבלת דבר בבחי' מספר כו' וכמשנת\"ל פ' פ\"ה, ומ\"מ אינה מסתרת ומעלמת האורות דאצי' לגמרי כו', ולכן באמת מבחי' המל' לא היו העולמו' מתהווים עדיין בבחי' יש וגבול, וכמ\"ש בלק\"ת ד\"ה מה יפו פעמיך בנעלים דגם מבחי' המל' הי' העולם מתפשט בל\"ג וקץ, ושיהי' התהוות בבחי' גבול מהלך ת\"ק שנה כו' הוא ע\"י המלאך סנד\"ל שהוא בחי' נעל החופה את רוב הרגל בחי' מל' כו', והיינו שע\"י המל' עדיין מאירים אורות דאצי' ואא\"ל מציאו' יש ממש עדיין כו'. וענין הגילוי דבחי' מל' הוא, דהנה נודע דעשרה מאמרות הן ע\"ס דמל' שהוא בחי' דבור העליון, ויאמר אלקי' יהי אור הוא בחי' חסד שבמל' כו', אין הכוונה\nשנראה כאלו המא' נמשך מספי' החסד שבמל' עצמו ממש ח\"ו, כ\"א עצמו' אוא\"ס ב\"ה מאיר הארתו ע\"י ספי' חסד שבמל' שיהי' התהוות האור, ואין הכלי דבחי' חסד שבמל' מסתרת כלל על אוא\"ס ב\"ה שיהי' נראה ח\"ו שההשפעה נמשך מהספי' ממש, ועש\"ז נק' ספירה שאינה מסתרת על האוא\"ס ב\"ה רק מה שע\"י נמשך האור במדרי' שלמטה להוות ולהחיות עולמו' בי\"ע כו', וה\"ה מחברת אוא\"ס ב\"ה עם העולמו' כו', אבל ההמשכה וההתגלו' מה שמתגלה ע\"י הוא בחי' אוא\"ס ב\"ה כו'. וע\"ה דהמל' הוא בחי' דמות לבד דהיינו שאין העצמי' דאצי' מתגלה ע\"י המל', ועש\"ז נק' כסא כס א' והיינו שאין גילוי עצמו' האור ע\"י הכלים דמל' רק בחי' דמות לבד, ומ\"מ מתגלה ע\"י גילוי אוא\"ס והיינו שנראה ונגלה שההשפעה היא מאוא\"ס ב\"ה, וכ\"ש במדרי' שלמע' מהמל' שע\"י מאיר גילוי אוא\"ס ממש להיותם בחי' עצמי' האצי' כו'. וכמו בתחלת הבריאה שהי' גילוי אוא\"ס למטה וכמ\"ש אלה תולדות השמים והארץ מלא ו', שהי' גילוי בחי' ו' דש' הוי' ולכן הי' גילוי אוא\"ס למטה כו' (וגם אז הי' הגילוי ע\"י המל' רק שבחי' המל' הי' ג\"כ\nבבחי' מאה\"ג, והיינו שהיתה בבחי' אספה\"מ והי' ע\"י המל' גילוי בחי' האור העצמי דאצי' כו', ומבו' במ\"א די\"ל שכמו בהתהוות הנשמו' עכשיו דגם בהיותם בחי' נברא ה\"ה אלקו' ממש, כמו\"כ הי' ההתהוות ע\"י המל' בכללו' העולם קודם הקטרוג שהי' הכל בבחי' אלקו' כו', וגם קודם החטא דעה\"ד הי' גילוי אוא\"ס וכמא' שהי' אדם מביט מסוף העולם ועד סופו, דהיינו בגילוי בחי' האור שנברא ביום הראשון דהיינו גילוי אור הכתר דביום הראשון בגימט' כתר כו', ובמד\"ר ע\"פ אלה תולדות הנ\"ל שהוי\"ו דברים נחסרו ע\"י חטא עה\"ד הרי שקודם החטא הי' גילוי בחי' ו' כו', ובלק\"ת מהאריז\"ל אי' דקודם החטא הי' כללו' ההשתל' במדרי' עליונה יותר והיו אז ז\"א ומל' במקום או\"א שהיו ו\"ה במדרי' י\"ה וכן יהי' לעתי' וכמ\"ש ביום ההוא יהי' כו', ומאחר שהמל' הי' במדרי' הבינה י\"ל שע\"י המל' הי' גילוי בחי' הוי\"ו בגילוי ממש כו', וזהו שאדה\"ר קודם החטא לא הי' צריך ללבושי' המסתירים כי הי' אז גילוי אוא\"ס בעולם, ובפרט לאדה\"ר הי'"],[3601330367,"האור בגילוי כו' וז\"ע כתנות אור שאינו מעלים כלל כ\"א רק מגלה כו'). וכמו במ\"ת שהי' גילוי אוא\"ס למטה והיינו שהי' גילוי האצי' למטה, וכדאי' בגמ' פ\"ק דסוכה ד\"ה ע\"א ע\"פ וירד ה' על ה\"ס למע' מעשרה טפחים והן ע\"ס דאצי' כו', והוא כמו שארז\"ל במכילתא הרכין הקב\"ה השמים כו' וכמ\"ש במ\"א, והיינו שהי' ירידת והמשכת הע\"ס דאצי' למטה והי' עי\"ז גילוי אוא\"ס ממש למטה כו'. וזהו שהכלים דאצי' הן בחי' ספי' ובהירות שמאיר ע\"י גילוי אוא\"ס ב\"ה כו', ועש\"ז נק' תיקונין לפי שבהם וע\"י מאיר גילוי אוא\"ס בעולם שזהו תכלית כוונת המאציל להיות גילוי אוא\"ס בעולמו' כו'. משא\"כ הלבושי' שאמר לקמן לבושין תקינת לון הם מסתירים על האורות והכלים ולכן אינן נקראו ספי' כו', וכמו עד\"מ הלבושי' באדם שענינם הוא להסתיר ולכסות על הגוף, כמו\"כ ענין הלבושי' למע' הוא להעלים ולהסתיר על האור, דגם לבושי' דאצי' וכמו לבוש החשמל שמקיף ומלביש לזו\"נ מצדדיהם ותחת רגליהם עם היות שזהו קדושה גמורה (ובע\"ח שמ\"ג פ\"א שהלבושי' דאצי' נק' אלקו' וקדושה כו'), והם מבחי' חיצוני'\nבינה וכמ\"ש מזה בתו\"א בד\"ה והבדילה הפרוכת, ה\"ה מלבישי' את הכלים ומעלימים ומסתירים עליהם לפי שאינן בחי' ספי' ובהירות כמו הכלים וממילא אינם מתייחדים כ\"כ עם הע\"ס וע\"כ הם מסתירים עליהם כו' (והנה ידוע דשרש הלבושי' הם מהאו\"מ ולכן המקיף שורה על הלבושי' כו', ולהיות שהמקיף הוא בבחי' העלם כמו\"כ הלבושי' המתהווים מהאו\"מ הן בבחי' לבוש המעלים כו', והגם שהכלים ג\"כ שרשם מהמקיף הנה באמת הכלים הם ג\"כ בחי' העלם בעצם והם בבחי' כיסוי והעלם על האורות כו', מ\"מ להיות דהתהוותם בסדר והדרגה הוא מן האורות דמהתעבות נעשה הכלי, ה\"ה בערך האור שמגלים את האור כו', והתהוות הלבושי' בסדר והדרגה י\"ל שהוא מהכלים (דכל השתל' ההעלמות הן מהכלים והגילוים מהאורות כו'), ולהיות דכללות ס' השתל' הכלים הוא שלא בבחי' דבקו' כו', לכן ההתהוות הוא בדרך אין ערוך ונעשי' בבחי' לבושי' המעלימי' גם לבושים דאצי' עם היותם אלקו' וקדושה גמורה כו'). ובריבוי השתל' הלבושי' יש בהם טו\"ר בלבושי' דיצי' ועשי' והן מעלימים ומסתירים לגמרי, וכמו המזלות שהן\nמסתירים לגמרי על אלקו' עד שנראה שההשפעה היא מהם בכח עצמן, דמשו\"ז יש שעובדים לשמש ולירח כו' ובאמת הן רק כגרזן ביד החוצב בהם כו' כנודע, רק זהו מפני שמעלימים ומסתירים מאד כו', משא\"כ הכלים גם בעשי' הן קדושה גמורה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והדוגמא מזה למע' באצי' דהכלים מגלים האור, גם הכלים דמל' מגלים, וכמו בהתהוות נראה ונגלה שזהו מאוא\"ס ב\"ה, ומהמל' עצמה לא הי' ההתהוות בבחי' יש ממש, וכ\"ש מדרי' שלמע' מהמל', דמבחי' תולדות מלא ו' הי' גילוי אוא\"ס, וג\"ז ע\"י המל' דקודם החטא היו הע\"ס במקומם האמיתי, ובמ\"ת הי' גילוי אצי' למטה, וזהו שהספירות נק' תיקונין, אבל לבושים דאצי' כמו לבוש החשמל מעלימים על הע\"ס (ושרשם מהמקיף ובהשתל' מהכלים, והתהוות הכלים בס' השתל' הוא מהאור), ולכן בהשתל' נעשים לבושים המעלימים לגמרי, משא\"כ בכלים דהכל קדושה.</span>\nקז) <b>וזהו</b> מ\"ש גבי יעקב ולבן לאחר שיעקב בירר צאן לבן ועשה מהם עקודים נקודים וברודים שהן כללו' עולמו' בי\"ע הכללי' כו' כתי' ויקח יעקב אבן"],[3601330368,"וירימה מצבה ויאמר יעקב לאחיו לקטו אבנים וילקטו אבנים ויעשו גל כו', ואמר לבן אח\"כ עד הגל הזה ועדה המצבה אם אני לא אעבור כו' ואם אתה כו', וכ' הבחיי שיעקב עשה מצבה לא גל, ואמר לאחיו לקטו אבנים היינו אחיו של לבן והי' כוונתו שיעשו ג\"כ מצבה והם עשו גל כו' (ושם דהכוונה שלהם הי' על גלגל החמה שזה הי' עבודתם). והענין הוא דהנה ידוע שיש ב' פי' בענין הגל שעשה לבן בינו לבין יעקב, הא' דלבן הוא בחי' לובן העליון שלמע' מעולם האצי' ויעקב הוא בחי' עולם האצי' כו', והגל שעשה לובן העליון הוא בחי' הפרסא שבין אוא\"ס המאציל אל הנאצלי', וכנודע דכשם שיש פרסא בין אצי' לבי\"ע, כמו\"כ יש פרסא בין הכתר אל החכ' בכדי שיהיו המשכת האורות באצי' בבחי' שיעור ומדה כו'. דהנה ענין הפרסא ידוע שנעשית מאותי' רק שהן בלתי מסודרים, דאותי' מסודרים ה\"ה כלים שבהם וע\"י נמשך ומתגלה האור וכמו אותי' הדבור כו', אבל אותי' הבלתי מסודרים הם להעלים האור וכמו החידות וכמו אותי' דקמיעות שהן להעלים הסוד שבהם כו', וכמו\"כ הוא בבחי' הפרסא שבין המאציל\nלנאצלי' שהיא ג\"כ מאותי' הבלתי מסודרים כו'. אמנם ידוע דהאותי' וכלים דכתר הן בחי' אותי' החקיקה שאינם בבחי' מציאות דבר, וע\"כ גם האותי' הבלתי מסודרים אינם מעלימים לגמרי, דגם ע\"י הפרסא אופן המשכת האור הוא שאינו בבחי' מהות אחר ח\"ו (ולא כמו הפרסא שבין אצי' לבי\"ע שהאור שע\"י הפרסא הוא אור של תולדה שאינו כמהות האור דאצי', והיינו לפי שהאותי' דאצי' הן בחי' אותי' הכתיבה שהן בבחי' מציאו' דבר, וע\"כ האותי' הבלתי מסודרים הן בבחי' העלם לגמרי כו' וכמשנת\"ל דס' ההשתל' דכלים אינו בהדרגה כו'), רק להיות שהאורות דאצי' הן בבחי' מדה ושיעור דבזה הן באין ערוך לגבי אורות המאציל שהן בבחי' בל\"ג כו', ע\"ז הוא הפרסא שבין המאציל לנאצלים שלא יהי' המשכת אור המאציל כמו שהוא בבחי' בל\"ג כ\"א ע\"י בקיעת הפרסא, וכמו אבא יונק ממזלא בחי' השערות שיוצאין בדרך בקיעה כו', וכמו יעקב אותי' יבקע בחי' בקיעת האור דרך הפרסא להיות בבחי' מדה ושיעור בס' והדרגה כו' (ובתחלה המשיך יעקב מבחי' לובן העליון גילוים אורות עצמי' שלא בבחי' צמצום כלל כו',\nוכידוע דענין צאן לבן הוא בחי' היציאה מעצם התענוג הפשוט כו' והמשיך משם אורות עצמי' כו', והוא המשכת האור דתומ\"צ שנמשך בזה מבחי' עצמו' א\"ס ב\"ה כו', וענין הגל והפרסא שנעשה זהו על המשכת בחי' האור דס' השתל' שהוא במדה ושיעור כו', ובאמת המשיך יעקב מבחי' לובן העליון כל האורות וההמשכות דבחי' פנימי' ובחי' חיצוני' והכל בבחי' ריבוי אור לא בהגבלה כו', וי\"ל שזהו ע\"ד עולם על מלואו נברא דבתחלת ההתהוות הי' גם למטה גילוי אוא\"ס והוא בכדי שיוכל להיות אח\"כ ההמשכה ע\"י עבודה כו', וכמו\"כ המשיך יעקב בתחלה גילוי אוא\"ס גם בבחי' חיצוני' ההמשכה ואח\"כ נעשה גל ופרסא להיות ההמשכה בס' והדרגה כו'). והפי' הב' הוא דלבן הוא למטה הרבה מבחי' יעקב שהוא בחי' האצי', ולבן הוא בחי' ק\"נ דברי' שנק' לבן למטה והוא בחי' חכ' דקלי' ארמי אובד אבי לנגד בחי' חכ' דקדושה כו', ונודע דחכ' דקלי' הוא בחי' יש שאינו רוצה להבטל ולהכלל בקדושה העליונה דבחי' יעקב דאצי' בחי' ש' מ\"ה כו', וע\"כ עשה מחיצה להפסיק ביניהם שלא יאיר בו אור הקדושה לפעול בו הביטול\nכו' וע\"ד פן בעיניו יראה כו'. וי\"ל דז\"ע מה דאי' בזהר דכאשר מכריזין למע' מאן בעי למחמי אפי שכינתא הסט\"א בורחת שאינו רוצה לראות איזה גילוי אלקו' שיפעול בהם הביטול כו' (ולכן"],[3601330369,"מ\"ת הי' דוקא ע\"י שהודה יתרו וכידוע שהי' בחי' חכ' דקלי' שנק' כהן און כו', וע\"י שהודה ונתבטל אל הקדושה הי' עי\"ז יתרון אור כו', והודאה שלו הי' ע\"י ששמע מהאותות ומופתים דיצי\"מ וקי\"ס וכמ\"ש וישמע יתרו כו' את כל אשר עשה אלקי' כו', וזה המשיך משה להיות גילוי האור האלקי גם בחכ' דקלי' לפעול שם הביטול כו', והתחלת ההמשכה הי' ע\"י יעקב כו').\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש והאבן הזאת אשר שמתי מצבה, דהנה ענין מצבה הוא הקמת המל' להיות בה גילוי אור כו', דהנה אבן הוא בחי' נקודה לבד שאין בה אור ומצבה הוא בחי' פרצוף שיש בה גילוי אור כו' וכמשי\"ת, וזהו מה שחידש בעשיית המצבה כו', ועי\"ז יהי' מבחי' המל' גילוי אלקו' בעולמו' ג\"כ היפך בחי' הגל דלבן כו', וענין בית אלקי' הוא שיהי' במל' גילוי בחי' פנימי' ועצמו' אוא\"ס ב\"ה מה שלא ע\"פ ס' והדרגה דס' השתל' (והו\"ע קיימא סיהרא באשלמותא שית' לקמן), ושעי\"ז גילוי אוא\"ס ממש בעולמו' וכמשי\"ת. ובכדי שיהי' תוס' אור זה במל' צ\"ל תחלה עליית המל' להיות בבחי' נקודה לבד כו', וזהו והאבן הזאת כו' יהי' בית אלקים דע\"י ההעלאה להיות בבחי' אבן נקודה נעשית בבחי' בית אלקי' כו'. וז\"ש יהי' בית אלקים ל' זכר להיות שבמל' מאיר גילוי או\"פ ועצמי והיא משפעת בבי\"ע ע\"כ נא' יהי' ל' זכר, וכמשנת\"ל (ד\"ה שובה ישראל) בענין אדון עוזנו דכד סלקין מילין לעילא מכנס\"י כולהו דכר אינון, וכן המל' כשמקבלת מהבינה נק' אדון וכמו\"כ כשמאיר בה בחי' אור\nעצמי נא' בה יהי' ל' דכר. וגם י\"ל יהי' הוא שו\"ה יהי' במדרי' י\"ה וכנ\"ל בש' הלק\"ת מהאריז\"ל שקודם החטא הי' באופן כזה וכן יהי' לעתיד כו' וז\"ש יהי' בית אלקים כו'. וזהו והאבן הזאת בחי' מל' שהיתה בבחי' נקודה, אשר שמתי מצבה בבחי' פרצוף כו', יהי' בית אלקי' בבחי' תוס' אור פנימי ועצמי כו', וזהו יהי' שהמל' תהי' בבחי' דכר ומשפיע, ומדרי' המל' יהי' כמו או\"א כו' ויהי' הגילוי ע\"י המל' למטה בבי\"ע כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וז\"ש עד הגל ועדה המצבה, יבאר ב' פי' בענין הגל שעשה לבן, הא' שזהו הפרסא שבין המאציל לנאצלים והיא מבחי' אותיות החקיקה, וע\"כ ההעלם הוא רק להיות בבחי' מדה וגבול (ובתחלה המשיך יעקב אור עצמי והוא האור דתומ\"צ, גם חיצוניות האור בבחי' גילוי), הב' שזהו הפרסא שבין אצי' לק\"נ ועשה לבן שלא יאיר בו האור להיות בבחי' ביטול, ומשה המשיך הביטול גם בנוגה, וההתחלה הי' ע\"י יעקב. ובזה יובן מ\"ש והאבן הזאת.</span>"],[3601330370,"<h3>בס\"ד. ש\"פ וישלח, תער\"ג</h3>\n<b>וישלח</b> יעקב מלאכים לפניו אל עשו אחיו כו' כה תאמרון כו' עם לבן גרתי ואחר עד עתה, וצ\"ל מה מודיע לו הספור שהי' עם לבן מה נוגע זה לעשו, ורש\"י פי' עם לבן גרתי ותרי\"ג מצות שמרתי, וג\"ז אינו מובן הלא אצל עשו לא הי' חשוב כ\"כ ענין קיום המצות ועל מה מודיע לו ששמר התרי\"ג מצות כו'. ולהבין זה ילה\"ק משנת\"ל בענין ויקח יעקב אבן וירימה מצבה, דיעקב עשה מצבה דוקא ולא גל ולבן עשה גל, ונת' ענין הגל דלבן הוא בחי' נוגה דבי\"ע והוא קלי' קשה שאינו רוצה להיות בטל לאלקו', וע\"ז עשה את הגל להפסיק בינו ובין הקדושה שלא יאיר בו אור האלקי לפעול בו הביטול כו'.\nקח) <b>וביאור</b> הענין הוא, דהנה ידוע דאת זלעו\"ז עשה אלקי', דכמו שיש ע\"ס דקדושה בחי' כח\"ב ומדות באצי' וברי' כו' שהכל הוא בבחי' תכלית הקדושה ובתכלית האחדות באוא\"ס כו', שהרי באצי' איהו וחיוהי חד ואיהו וגרמוהי חד, שגם הכלים דאצי' הם מיוחדים בתכלית באוא\"ס, דהכלים דאצי' הן אלקו' ממש וה\"ה מיוחדים בתכלית היחוד כו', רק שיש הפרש בין היחוד דכלים להיחוד דאורות דלכן נא' ב\"פ חד. וההפרש הוא ע\"ד ההפרש בין יחיד לאחד דיחיד הוא בבחי' יחוד עצמי שכולא חד ממש ואחד הוא בחי' התאחדות הפרטי' כו' וכמ\"ש מזה בתו\"א ד\"ה וארא ובלק\"ת ד\"ה בהעלותך, דהיחוד דאחד הוא ג\"כ בבחי' אחדות ממש כו', וכמו\"כ הוא היחוד דאורות בבחי' יחיד, ובכלים היחוד הוא בבחי' אחד כו', אבל הכל הוא בבחי' יחוד ממש כו'. והע\"ס דבי\"ע דלאו איהו וחיוהי וגרמוהי חד כמ\"ש בת\"ז מ\"מ ה\"ה בבחי' ביטול כו', שהרי אור הנשמה דבי\"ע ה\"ז אלקו' ממש והאורות נ\"ר והכלים שהן בחי' נברא מ\"מ ה\"ה בבחי' כלים אל האור דנשמה כו', ומבו' במ\"א שזהו כמו הגוף שהוא כלי אל הנשמה דמה\nשנדע ונרגשת הנשמה בגוף היא רק מציאותה לבד לא מהותה כו', וזהו ההפרש בין כלים דאצי' לכלים דבי\"ע, דכלים דאצי' משיגים מהות האור וה\"ה בבחי' ביטול ויחוד בתכלי' כו' (בבחי' הביטול דיחו\"ע כו'), וכלים דבי\"ע משיגים רק בחי' המציאו' לבד כו', ומ\"מ ה\"ה ג\"כ בבחי' הביטול וכמו הגוף שע\"י הביטול דוקא הוא חי מאור הנשמה כו' וכמ\"ש במ\"א, וכמו\"כ בחי' הע\"ס דבי\"ע גם בחי' הכלים הכל הוא בבחי' היחוד והביטול כו', ולכן בהכלים דבי\"ע אין בהם תערובות טו\"ר ח\"ו וכמשנת\"ל פק\"ו, הרי דע\"ס דקדושה הן בתכלית הקדושה ותכלית היחוד כו'. הנה כך בלעו\"ז יש ג\"כ ע\"ס כח\"ב ומדות והוא הרצון והתענוג דלעו\"ז, ובחי' חו\"ב וכמו חכמים המה להרע כו', רק שהן בבחי' הפירוד בתכלית מאלקו' בבחי' ישות וגסות כענין חומרי' עוה\"ז וחכמות חיצוני' כו' שהן היפך האלקו' לגמרי, רק דמבחי' צמצום האור במותרי השפע מבחי' חיצוני' הכלים דע\"ס דקדושה נמשך להם קצת יניקה כו' (ולא מבחי' הכלים ממש ח\"ו כ\"א מבחי' השערות דאחורי העור דמל' שזהו בחי' מותרות השפע כו'). וזהו בחי' לבן\nדקלי' שלמטה מהפרסא שבין אצי' לברי' ונת\"ל פק\"ז דלבן הוא בחי' חכ' דקלי' ואי' ג\"כ שהוא בחי' כתר דקלי' והוא תוקף הקלי' ביותר, דכמו בקדושה בחי' לובן העליון הוא בחי' פשיטת העצמי' דאוא\"ס שלמע' מבחי' החכ' כו', כמו\"כ בקלי' הוא בחי' תוקף הקלי' שלמע' מטו\"ד והו\"ע הרצון והתענוג"],[3601330371,"דלעו\"ז, וכמו השקוע ביותר ר\"ל בתאוות ותענוגי' הגשמי', וכמו\"כ יש עניני תאוות שהן בבחי' מקיפים דקלי' וכמו הכבוד וכה\"ג וכמשי\"ת בסמוך. וזהו בחי' לבן דקלי' שנפל בדרך שבירה ונפילה מבחי' לובן העליון דקדושה, והו\"ע שבה\"כ דתהו שהוא בחי' ס\"ג שלמע' מש' מ\"ה שירד ונפל למטה בבחי' ב\"ן דנוגה כו' כנודע, ולבן זה דקלי' עשה גל בינו לבין הקדושה היינו שלא יתגלה מאורות עליוני' דחכ' דש' מ\"ה דאצי' למטה בהיכלות דנוגה דבי\"ע להעלותם ולבררם ליכלל בקדושה דאצי' כו'. שהרי יש בירורי' למטה בתענוגי עוה\"ז שמתבררים ועולים למע' ע\"י התו' וע\"י קיום המצות בדברים גשמי' ובפרט ע\"י התשו' כו', וכמו\"כ יש בירורים בדרך מלמטלמ\"ע ע\"י העבודה דתפלה שמעלים באתעדל\"ת מהיכלות דנוגה דבי\"ע לאצי' בחי' ניצוצות דקדושה שנפלו לשם, וכמו והנפש אשר עשו בחרן בהגרים שגייר אברהם כו', וכמו נשמו' הגבוהות דר\"ע ור\"מ ושמעי' ואבטליון וכן בנביאים כעובדי' כו', דכל אלו ההמשכות והעלאו', דהיינו בכדי שיהיו הבירורים למטה ע\"י תומ\"צ ותשו' ושיהי' עליית הנשמו' כו', כ\"ז הוא\nע\"י תוס' אור והמשכה שלמע' מכפי המדה שנמדד ונקצב בס' השתל', כי ע\"פ המדה דס' השתל' נמשך האור בבחי' צמצום ומתמעט ממדרי' למדרי' כו', ועל האור המצומצם הנה המסכים והפרסאות מעלימי' ומסתירים (כי גם תחלת המשכת האור הוא ע\"י הצמצום שהי' בתחלה שהוא בבחי' העדר האור והגילוי כו'), שלאחר הפרסא מאיר אור מצומצם ביותר שאין בכח האור הזה לברר ולהעלות כו', כ\"א דוקא ע\"י שנמשך אור עליון יותר שמאיר גם ע\"י הפרסא כו', וכמו ויהי קול ממעל לרקיע שהוא בחי' קול התו' שלמע' מהפרסא היינו מה שאין הפרסא יכולה להעלים כו' (וע\"ה שזה בא ג\"כ במדה ושיעור מ\"מ הרי נמשך בזה בחי' העצמי' והמדידה היא ג\"כ מדידה עצמי' כו' כידוע ומבו' במ\"א). וזהו במסכים ופרסאו' דקדושה שאינם מעלימים לגמרי גם על האור דס' השתל' וכ\"ש שאינם מעלימים על האור שלמע' מהשתל' כו', אבל לבן הארמי רצה להגביר את המסכי' להיות בבחי' העלם לגמרי ח\"ו (וע\"ד כ\"א עוונותיכם היו מבדילי' כו' וכמ\"ש באגה\"ת פ\"ה שאין שום דבר חוצץ ומפסיק כ\"א עוונותיכם כו'), והיינו להעלים גם על ההמשכה\nדתומ\"צ ושלא יהי' ח\"ו התעוררו' תשו' בבע\"ת ושלא יהי' גילוים מאצי' לבי\"ע, כמו הגילוי אלקו' שהי' בבהמ\"ק וכגילוי הנבואה בנביאים וכמו כל האותות והמופתי' שלמע' מהטבע כו' (וי\"ל שזהו בחי' מקיף דקלי' שהיא קלי' קשה ביותר שמעלים ומסתיר גם על ההמשכות והגילוים דאוא\"ס שלמע' מהשתל', וכמו חוצפא כלפי שמיא מהני דהיינו שיכול לעמוד גם נגד הגילוי דאלקו' כו' כנודע ומבו' במ\"א. וכמו\"כ הוא בתאוות ותענוגי' שהן בבחי' המקיף דקלי' שמעלים גם על הגילוי כו' וכמו השקוע ביותר ר\"ל בתענוגי' גשמי' שמאבד באמת כל חלקי טובה שבנפש כו', וכמו התאוה והכבוד דתאוה הוא בחי' או\"פ דקלי' וכבוד הוא או\"מ דקלי' שזה גרוע יותר, שמי שרוצה להיות מכובד בעיני הבריות ה\"ז מרחיק אותו מאור הקדושה ביותר, דכל ענין הקדושה הוא הביטול והנחת עצמותו, ובזה הוא בבחי' הרגש עצמו ביותר כו', וכמו\"כ במלבושי כבוד שמלבישים ומקיפי' את הנפש (עס נעמט עם זייער ארום) שמשוקע בזה ביותר שנוגע לו מאד, וכנראה בחוש דמי שהוא בקלי' זו דמלבושי כבוד נוגע הדבר בנפשו הרבה יותר\nמעניני אכו\"ש וכה\"ג, מפני שמלביש ומקיף מאד את הנפש ה\"ז מעלים לו לגמרי על אלקו' כו', וגם מפני ששומר מאד את"],[3601330372,"הציור שלו, ובקדושה צ\"ל דוקא הפסד הצורה החיצוני' ומי שהלבושי' נוגעים לו ה\"ה שומר א\"ע מאד מהפסד הצורה החיצוני' וזה מניעה ועיכוב גדול מאד לעבודה והרגש אלקי בנפשו כו' (ועמ\"ש במ\"א בענין קלי' עמלק שאינו מניח א\"ע שיתפעל מענין אלקי בדרך עזות כו', וכמו\"כ הוא בענין הזה מצד התאוה דלבושי' אינו מניח שיהי' בו הרגש אלקי שעי\"ז יתבטל בציור החיצוני שלו כו'). וכ\"ז עשה לבן שלמטה אחר שכבר ראה שהצליח יעקב בעובדות שלו במקלות שהמשיך בחי' ש' מ\"ה דתיקון גם בצאן לבן דנוגה והפך חשך לאור ביתר מכפי המדה מאד, וכמ\"ש ויפרוץ האיש מאד כו' דמכל אשר לאבינו עשה כו' שבירר מצאן לבן דנוגה כו', והבין שלפ\"ע זה יוכל יעקב בעל עולם התיקון לתקן ולהעלות הכל מנוגה דבי\"ע שיוכלל באצי', וכמו שיהי' לעתיד דכתי' אז אהפוך אל עמים שפה ברורה כו' שיבורר הכל כו' (וי\"ל דבתחלה המשיך יעקב בחי' גילוי אור רב ביותר דבתחלת הבירור בכדי שיבורר בחי' נוגה דבי\"ע הי' צ\"ל המשכת אור רב ביותר, וכמו במ\"ת דכתי' וירד ה' על ה\"ס שהי' גילוי אוא\"ס ממש למטה וידוע שזהו\nבשביל הבירור דבכדי שהתחתון יוכל להתברר ע\"ז הי' תחלה המשכת אוא\"ס למטה, וזהו ג\"כ ענין מ\"ש וזרח משעיר למו הופיע מהר פארן שהחזירה על כל אומה ולשון כו' שכ\"ז הוא בשביל הבירור כו' וכמ\"ש במ\"א, כמו\"כ יעקב בשביל הבירור המשיך בתחלה גילוי אור רב ביותר ולא הי' ביכולת לבן לעמוד נגד זה כו'. אך לאחר שגמר עבודתו אצל לבן וצ\"ל ההמשכה דש' מ\"ה בתומ\"צ בבחי' מדה ושיעור שז\"ע ויעקב הלך לדרכו בבחי' ס' והדרגה כו', רצה לבן הארמי לעשות העלם והסתר ביותר כו', אך לא הועיל לו כי כבר המשיך יעקב בחי' האור והגילוי שלמע' מהשתל' שגם בההמשכה שבבחי' מדה ושיעור דתומ\"צ נמשך בחי' הפנימי' והעצמי' דא\"ס כו', וכמו\"כ המשיך שיהי' ענין התשו' דמשכין לי' בחילא יתיר שבכח האור הזה להסיר כל ההעלמו' וההסתרים כו', והעיקר שפעל יעקב בהמשכת האור העליון ששום מסך ופרסא לא יבדיל ולא יפסיק לגבי האור כו', והיינו שיהי' המשכה דתומ\"צ למטה ושיהי' ענין התשו' כו'. גם י\"ל מפני שקדם יעקב והמשיך את האור קודם שהספיק לבן לעשות את הגל, דבתחלה המשיך אור רב שלא\nהי' באפשר ללבן לעמוד נגד אור זה כנ\"ל, ואח\"כ כתיב וירימה מצבה קודם הגל שעשה לבן, והיינו שגם ההמשכה דתו\"מ בס' והדרגה קדם והמשיך יעקב קודם שהספיק לבן לעשות הגל וע\"כ לא הועיל לו עשיית הגל וההפסק כו', ומ\"ש כ\"א עוונותיכם היו מבדילים כו', י\"ל שהעון דישראל ר\"ל גרוע יותר שחוצץ ומבדיל כו', ומ\"מ שייך תשו' ואין לך דבר שעומד בפני התשו' כו'). ומפני היראה הזאת עשה לבן גל להפסיק בין נוגה דבי\"ע לאצי', וא' כי נסתר כו', היינו שיהי' בבחי' הסתר והעלם גמור כו', אם אני לא אעבור כו' בבחי' העלאה מלמטלמ\"ע ואם אתה לא תעבור בבחי' המשכה מלמעלמ\"ט כו'. וזהו שקרא את הגל יגר שהדותא ואי' בש\"ך על התו' שזהו בגימט' השם שהוא חילוף דה' אלקינו ה', והיינו שמקומו ואחיזתו הוא בחילופים ותמורות שהו\"ע הלבושי' והמסכים שכללו' ענינם הוא להסתיר והוא רצה עוד להגביר ההסתר ביותר כו' כנ\"ל.\n<span data-k=\"ks\"><b>קיצור.</b> והענין דהנה ע\"ס דאבי\"ע הן בתכלית היחוד, באצי' יחוד האורות ויחוד הכלים ע\"ד יחיד ואחד, וכלים דבי\"ע ג\"כ בבחי' יחוד גוף ונפש, ובלעו\"ז</span>"],[3601330373,"<b>יש</b> ג\"כ ע\"ס, ולבן הי' כו\"ח דקלי' מקיפים דקלי', ורצה לבן לעשות גל והפסק שלא יתברר, כי הבירורים דתומ\"צ ותפלה ותשובה הוא ע\"י אור עליון שאינו מתעלם ובכחו לברר, ורצה להעלים ע\"ז, ע\"ד חוצפה כלפי שמיא (ענין קלי' הכבוד ולבושי כבוד), מפני שראה הצלחת יעקב בענין הבירורים (דבתחלת הבירור הי' צ\"ל גילוי אור רב ביותר, וכמו במ\"ת), ועשה לבן גל חילופים ותמורות בכדי להעלים, אך לא הועיל אחר שהמשיך יעקב האור העצמי נמשך אח\"כ במדה ושיעור בתומ\"צ, וי\"ל שג\"ז המשיך קודם שהספיק לעשות גל.\nקט) <b>אך</b> יעקב עשה מצבה ולא גל, דהנה גל הן אותי' הבלתי מסודרי' שמעלימי' והו\"ע הפרסא כנ\"ל, אבל מצבה הן אותי' מסודרי' שהן כלים לאור השכל שמתלבש בהם ומתגלה ע\"י כו'. והענין דהנה במאו\"א מ\"ם אות פ\"ב אי' מצבה הקמת מל' מבחי' נקודה לעשותה פרצוף עכ\"ל, וזהו מה שעשה יעקב את האבן למצבה דאבן הוא בחי' נקודה וכמ\"ש במאו\"א א' אות ד' דכל אבן מורה על יו\"ד (וכדאי' בזהר אבנא למשקל בה דא י' כו'), והיינו בחי' נקודה ונקודה הוא בחי' מיעוט הכלים (עמ\"ש בבה\"ז בלק ע\"פ שחורה אני) שאינו בבחי' כלי עדיין לקבל את האור כו', ובנין המל' להיות בבחי' פרצוף הוא שתוכל לקבל את האור כו', וי\"ל דנקודה הנ\"ל זהו בחי' כתר מל', והגם שהיא מדרי' היותר עליונה שבמל' מ\"מ אינו בבחי' גילוי אור שז\"ע יו\"ד בבחי' שחרות שהיא אז בבחי' עלי' והסתלקו' כמו איידי דטריד למבלע כו' וכמ\"ש בבה\"ז שם שא\"ז בבחי' גילוי אור והוא מצד העדר הכלים כו' וכמשנת\"ל פצ\"א, וכשנבנית בבחי' פרצוף היינו בבחי' ריבוי כלים להיות בחי' גילוי אור כו' וע\"ה שזהו למטה במדרי'\nמבהיותה בבחי' נקודה, מ\"מ שרש ההמשכה הוא למע' דוקא וכמ\"ש במ\"א במאה\"ז ויקהל דר\"ד האי רוחא איהו אתפשטותא דהאי נקודה שזהו דוקא כד אתוסף קדשין וברכאן מלעילא כו', וי\"ל דלכן נק' זה קימה לגבי המל' להיות שזהו ע\"י המשכת אור עליון כו', וע\"ש במאה\"ז הנ\"ל דאתפשטותא דהאי נקודה זהו בשבת שבחי' מל' מאירה בבי\"ע שלא ע\"י הפסק והעלם הפרסא כו' (ושם שהוא ע\"י מעבר הפרסא לא בהתלבשו' והו\"ע מה יפו פעמיך כו'), והיינו מפני ששרש ההמשכה הוא מעתיק כו' (ועמ\"ש בע\"ח שער א\"א פ\"ב דשרש המל' הוא ברדל\"א, ומ\"מ אצי' המל' היא בבחי' נקודה לבד (וי\"ל להיות דרדל\"א הוא בחי' לא ידע שאינו בבחי' מהות ידוע בעצמו כו' וכמ\"ש בסי' בפי' ברוך שאמר, לכן נאצלה המל' ג\"כ בבחי' נקודה שאינו בבחי' גילוי כלל כו'), ובכדי שיהי' התפשטות המל' בבחי' גילוי צ\"ל ממדרי' עליונה יותר, וכמו שמצינו דנה\"י החדשים דז\"א נמשכים מן הכתר, דבכדי להשפיע צ\"ל שרש ההמשכה ממדרי' עליונה יותר וכמ\"ש במ\"א, כ\"ש דבבחי' מל' הוא דבכדי להיות בנין המל' בבחי' פרצוף שצ\"ל ההמשכה ממדרי'\nעליונה יותר כו'. וי\"ל דהנה בע\"ח שם בהג\"ה מק' מבי' האד\"ז דמבחי' נה\"י דע\"ק נעשה בחי' מל' דא\"א, ולפ\"ז י\"ל דעם היות דמל' מושרשת ברדל\"א היינו בחי' חיצוניות, ושרש התפשטותה הוא מבחי' הפנימיות (וצ\"ל ע\"ד מ\"ש בסוף הבי' דשבת שבתון ועמשי\"ל ד\"ה פדה בשלום עד\"ר). ובמ\"א מבו' ע\"פ מאה\"ז פקודי דרכ\"ט ע\"א בגין דהוו ממה דאשתאר מנהורא דזיווא עילאה, דהתפשטות והתגלות דבחי' המל' הוא ע\"י יחוד וחיבור הע\"ס שעי\"ז היחודים שורה מבחי' עצמות אוא\"ס כו' וכמ\"ש מזה בלק\"ת בהבי' דוהניף שזהו מבחי' א\"ס שלימותא דכולהו, והוא בחי' התכללות"],[3601330374,"הב' דתיקון שמבחי' עקודים ובשרשו מבחי' פנימיות ועצמות א\"ס כו' וכמ\"ש מזה באורך בתו\"ח ד\"ה ויהי כל הארץ שפה אחת (וכמו\"כ ביחוד זו\"נ נמשך אור עליון יותר והוא בחי' בעטרה שעטרה לו אמו ביום חתונתו כו' שזהו שרש ומקור המל' כו' כמ\"ש במ\"א), ומבו' שם משל ע\"ז כמו המלך כאשר הוא בשמחה גדולה בחתונת בנו וכדומה הנה אז בא בנפשו אור וגילוי בתוס' מרובה מאד עד שבאין כל כחות נפשו בגילוי גדול, ועיקר הגילוי הוא כאשר מתגלה לכל כקטן כגדול גם לפחותי הערך שאינם מבינים כלל גדולת המלך וחכמתו, ובמה יתגלה אליהם היינו במה שמספר לפניהם סיפורי מעשיות ודברים הרבה לפי ערכם, ובזה מלובשים ענינים רמים ונשגבים, והגם שהם אינם מבינים מפני ההלבשה וההעלמה מ\"מ ה\"ז גילוי ע\"י הדבור כו'. ומובן מזה ב' דברים הא' שמחמת ריבוי ותוס' אור בא לידי גילוי יותר מדאי, ועוד יובן שהגילוי יותר מדאי הנעשה מזה א\"א שיבוא בבחי' התגלות הפנימיות רק בבחי' הדבור שהוא לבוש חיצוני בלבד (ובזה יש דוקא ענינים רמים מבחי' הפנימיות שלמעלה מבגילוי השכל כו'). והנמשל מזה\nדמחמת בחי' הריבוי והתוספות מבחי' אור פשוט דעצמות אוא\"ס שע\"י היחודים דאצי' הוא בא לידי גילוי יותר מדאי, והגילוי הוא להיות בחי' המל' הנק' עולם הדבור כו', ובזה דוקא מבחי' פנימיות ועצמו' א\"ס ויתגלה לעתיד דונגלה כבוד ה' כו'. י\"ל דנקודת המל' הוא בחי' אין שנאצל באצי', דהנה אצי' הוא בחי' יש נאצל וגם בבחי' חכ' כתי' והחכ' מאין תמצא ליש, ומל' היא בחי' אין, והגם דחכ' הוא יו\"ד דש' הוי' בחי' נקודה לבד, מבו' ג\"כ דנקודת היו\"ד היא מ\"מ בציור אות, אבל נקודה דכתר היא נקודה בלי ציור כלל כו', וכמו\"כ י\"ל בבחי' מל' מפני שרשה בבחי' לא ידע כו' כנ\"ל. ובמ\"א מבו' דבחי' מ\"ה דחכ' הוא בחי' אין דכתר שנמצא בין הנאצלים כו' דמ\"מ הוא בחי' אין וביטול שע\"י החכ', וכמו בבחי' ראי' דחכ', ואין דנקודת המל' הוא בחי' העדר ואין בעצם והיינו בחי' מהות ביטול כו', ובחי' ההתפשטות וההתגלות הוא מבחי' עצמות א\"ס ב\"ה כו' כנ\"ל). וע\"כ זהו בחי' קימה בבחי' מל' והיינו שבמל' מאיר מבחי' או\"פ ועצמי דאוא\"ס ב\"ה. וזהו ג\"כ מה שההקמה היא ע\"י יעקב להיותו\nבחי' בריח התיכון כו', ה\"ה ממשיך מבחי' פנימי' הכתר שהו\"ע הברכה מלעילא להיות אתפשטותא דהאי נקודה כו' וכמשי\"ת לקמן. גם י\"ל דבחי' נקודה זהו בחי' המל' כמו שמתלבשת בבי\"ע דכל פרצופה היא בבחי' נקודה לגבי כמו שהיא באצי' כו', דהנה במאו\"א כ' דאבן הוא י' דאד', וידוע דש' אד' הוא בחי' נקודת המל' היורדת לברי' כו'. והענין הוא דלהיות שאין ערך ברי' לגבי אצי' גם לבחי' המל' דאצי' שהיא מדה א' ממדות דאצי' בבחי' האלקו' כו', ע\"כ בהכרח שיתעלם אורה להיות רק כנקודה א' בלבד ואז יכול להיות המשכה ושפע מבחי' המל' להתהוות נבראי' בע\"ג, וזשארז\"ל בענין מיעוט הירח לכי ומעטי א\"ע כי כדי שתהא המל' בחי' ראש לשועלים בבי\"ע להיות הנבראי' בבחי' גבול, הוצרך להיות בחי' מיעוט וצמצום אור בעצמותה לגמרי עד שאינה רק בבחי' נקודה א' לבד והוא הנק' מולד הלבנה, ואז תהי' מקור וראש לבי\"ע כו', וע\"כ גם כמו שנעשית בבחי' פרצוף בבי\"ע ה\"ז נחשב רק כמו נקודה לגבי אצי' כו'. והנה בזה יש ב' מדרי' הא' עצם בחי' המל' והיא הנקודה דמל' שבוקעת ושוברת את הפרסא\nויורדת בראש הברי' שנעשית בחי' עתיק לברי' וכמ\"ש בע\"ח שעמ\"ז פ\"א (וי\"ל דז\"ש ואראה את אד' יושב על כסא כו', דכסה\"כ הוא כח\"ב דברי' שבתוכה התלבשו' בחי' נקודת"],[3601330375,"המל' שזהו ש' אד' כו'), וגם בחי' זו מסתתרת בברי' כמ\"ש בע\"ח שם, והב' בחי' התפשטו' הארתה הוא שבא בבחי' התלבשו' ממש בבי\"ע בבחי' התלבשו' כח הפועל בנפעל כו', דבחי' זו באה בבחי' העלם והסתר בלבושי' דבי\"ע כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויעקב עשה מצבה כלים, במאו\"א אבן נקודה מצבה פרצוף, נקודת המל' בחי' כתר מל' (ושרשה מעתיק, וי\"ל שזהו בחי' אין שנאצל באצי'), ועשאה מצבה בחי' התגלות המל' ע\"י המשכת אור עליון (י\"ל מבחי' פנימיות עתיק, או בד\"כ משרש ומקור המל'), והו\"ע הקימה דמל', גם י\"ל דאבן הוא בחי' מל' כמו שהיא בבי\"ע, ובזה גופא יש ב' מדרי' הא' נקודת הבוקעת הפרסא ונעשית ראש הבריאה, והב' התפשטות הארתה המתלבש בבי\"ע. </span>\nקי) <b>והנה</b> בעבודה י\"ל שז\"ע פעולת נה\"א בנה\"ב בבחי' כפי' בפועל ממש, דהיינו לא מה שפעל בעבודתו שלא ירצה בעניני' החומרי' כ\"א מה שכופה א\"ע בכפי' בפועל כו', גם י\"ל שז\"ע מצות מעשי' בלי שום כוונה ורצון פנימי כ\"א רק הקיום בפו\"מ כו'. וענין הנקודה י\"ל שזהו בחי' נקודת הלב בחי' כנס\"י כמו שהיא בבחי' קטנות דהיינו בבחי' אמונה לבד דע\"ה שיש בזה תוקף גדול וכמו ויאמן העם דבזכות האמונה נגאלו כו', מ\"מ אין בזה התגלו' אור וכמ\"ש בתו\"א ד\"ה זכור דעמלק, והרחבת הדעת בעבודת ה' זהו הקמת המל' והו\"ע הגאולה כו'. גם י\"ל דהתלבשות הארת המל' בבחי' כח הפועל בנפעל ה\"ז בבחי' העלם והסתר שאין האלקו' נראה ונגלה, שזהו לא רק מן ההתעלמו' דהאור האלקי כנ\"ל בענין מיעוט הירח, כ\"א מה שמתעלם ע\"י הלבושי' דבי\"ע כו', וכמו בעולם התחתון שאין האלקו' נראה ונגלה כלל דע\"ה שבכ\"ד יש אור וחיות אלקי ה\"ז בבחי' הסתר לגמרי כו', שזהו מצד התגברו' היש דעולם התחתון כו'. דבדוגמא כזאת בנפש הוא בהתלבשו' הנה\"א בנה\"ב בחי' הסתר שהכחות דנה\"ב מתגברי'\nומעלימי' ומסתירי' על הנה\"א דאז נק' נש\"י בש' אסתר כו', וכידוע דלפעמים נק' כנס\"י בשם רחל ולפעמים בשם אסתר, והיינו כשיש התגלו' אור הנפש שרצונו להכלל באוא\"ס שרשו ומקורו נק' בשם רחל וכמו כרחל לפני גוזזי' נאלמה, דפי' נאלמה הוא ל' שתיקה שהו\"ע הביטול כו', וכמו כצאן טבחה שפושטת צוארה לשחיטה ברצון פשוט, וכ\"ה בכאו\"א מישראל שיהי' רצונו להבטל ולהכלל באורו ית' למהוי א' בא' כו', וכל זמן שהוא בהתגלו' ובהתלהבות נק' בחי' רחל כו', אבל בעת שאין הדבר בהתגלו' נק' בחי' אסתר כו'. והגם שיש רצון זה בכאו\"א מישראל אלא שמוסתר ונעלם כו' וההסתר הוא מהנה\"ב, וכמ\"ש כשושנה בין החוחי' שהחוחים הם המונעים ומסתירי' את השושנה והם כל עניני העולם ומעשה העוה\"ז הנעשי' בכל לב ונפש, דבאמת צ\"ל עשיית הדברי' הגשמי' בלא לב ולב כו' שבכ\"ד צ\"ל כוונה אלקי', וע\"ה שמוכרח אל הגשמי מ\"מ אצ\"ל בזה תאוה הגשמי' והחומרי' כ\"א לקבל חיות מהאלקו' שבזה כו', וכן בעסק מו\"מ צ\"ל בכוונה לש\"ש בכדי שיוכל לעסוק בתו' ולקיים מצות כו', וצריך לידע שהעיקר הוא ברכת ה'\nאשר היא תעשיר כו', וממילא לא יהי' מוטרד כ\"כ בהעסק באופן שלא יהי' לו מניעה ועכוב לתפלה בזמנה ולעסק התו' עכ\"פ פ\"א שחרית ופ\"א ערבית כו', אבל כאשר הדברים הגשמי' נעשי' בכל לב ונפש ה\"ה נק' חוחים ומסתירים בחי' זו מלהתגלו' כו', והוא כמ\"ש באגה\"ק סי'"],[3601330376,"ד' דמפני שהלביש בחי' פנימי' נקודת לבבו בזלעו\"ז כו' והיא בחי' ערלה המכסה על הברית (י\"ל הכוונה על מ\"ש בתו\"א פ' תשא ד\"ה שמאלו תחת לראשי) ונקודה הפנימי' שבלב כו', ועמ\"ש בלק\"ת ד\"ה וידבר כו' במד\"ס באוה\"מ, ושם דההתלבשו' וההסתר הוא בכדי שעי\"ז יהי' בירור הנה\"ב (דכמו\"כ הו\"ע התלבשות המל' מה שמסתתרת בבי\"ע הוא ע\"י נוגה דבי\"ע (דהתגברו' הישות הוא מנוגה כו' ועמ\"ש בלק\"ת בהבי' דראשי המטות) והכוונה הוא בכדי לברר כו'), והוא ע\"י התפלה ברשפי אש וצמאון וצעקת הלב כו' (והנה משנת\"ל זהו מהדרוש ותוסף אסתר, דמבו' שם שההסתר הוא על בחי' פנימי' הלב וכ\"נ הכוונה בדרוש במד\"ס הנ\"ל, והבירור הוא ע\"י רשפי אש וצעקת הלב בתפלה שהו\"ע התשו' כו', וי\"ל שזהו להפריד הרע כ\"כ עד שהטוב יתעלה באצי' כו' וע\"ש בהביאור, אמנם כמו\"כ הוא גם בחיצוני' הלב שמסתתרת בנה\"ב שהוא לצורך הבירור ע\"י העבודה בבחי' השגת אלקו' והתעוררו' אהוי\"ר כאו\"א לפי מדריגתו כו'). והנקודה י\"ל שזהו המשכת הארה מלמע' לעורר את הרצון וכמו עד יערה עלינו רוח ממרום וכמו ההתעוררו' שבא פתאום על נפשו כו' וכמ\"ש בלק\"ת ד\"ה אדם כי יקריב יעו\"ש.\n<span data-k=\"ks\"><b>קיצור.</b> ובעבודה י\"ל דוגמת ענין ההתלבשות הוא הכפי' בפועל, והנקודה היא נקודת הלב בבחי' אמונה. גם י\"ל התלבשות היא התעלמות הנה\"א בנה\"ב בחי' אסתר, רחל בחי' התגלות הרצון לאלקות, ואסתר הוא כשהנה\"ב מסתיר, והוא בכדי שיהי' הבירור ע\"י תפלה, והנקודה י\"ל שהיא האתעדל\"ע לעורר האתעדל\"ת. </span>\nקיא) <b>ועוד</b> י\"ל ע\"פ מ\"ש במ\"א בענין ותפול לפני רגליו שבזה\"ג כנס\"י היא בבחי' נפילה והו\"ע סוכת דוד הנופלת כו', כי הנה במ\"ת כתי' פב\"פ דבר ה' עמכם שהי' הקב\"ה עם כנס\"י בבחי' פב\"פ וכן הי' כ\"ז בהמ\"ק, ובחי' פנים של הנפש הוא התגלו' הכחות פנימי' שלה דהיינו התגלו' החיות שלה (וכמו עד שיאדימו פניו שמתגלה בזה החיות פנימי כו') ומה שהוא רצונה וחפצה האמיתי כו', וכמו שבפנים הוא עיקר גילוי חיות הנפש וגילוי כל החושים ראי' ושמיעה כו', משא\"כ מה שאינו כ\"כ חפץ ורצון הנפש אלא על צד ההכרח או אגב גררא ובקרירות הם בחי' אחורי' של הנפש שאין שם אלא חיות מועט. כך הנה בזמן בהמ\"ק הי' כללו' נפשות ישראל בטבעם נמשכים לעבודת ה' לאה' אותו ולדבקה בו מרצונם וחפצם האמיתי שזה הוא עיקר חיות הנפש, וצרכי עוה\"ז לא הי' אצלם כ\"א ע\"צ ההכרח ודרך עראי וקרירות שלא הי' חיות הנפש בזה אלא דבר מועט ונק' בחי' זו ידך בעורף אויבך כו' וכמ\"ש במ\"א. והי' אצלם בחי' ראי' ושמיעה באלקו' וכמו שלש פעמים בשנה יראה כו' דכשם שבא ליראות כך בא לראות\nשראו ממש גילוי אוא\"ס בבהמ\"ק, ועי\"ז הי' עבודתם כל השנה בבחי' ראיית המהות דאלקו' בעין השכל דבלבא בבחי' התאמתות ממש כו', שעי\"ז הוא הביטול בבחי' השתחוואה שהו\"ע ביטול פנימי ממש כו' וכמ\"ש במ\"א. ובחי' שמיעה הו\"ע השגה דבזמן בהמ\"ק הי' זה בבחי' השגה פנימי' בעצם הענין האלקי ולא בבחי' תפיסת ההשגה לבד כ\"א מה שתופס ומשיג עצם הענין האלקי המושג כו', שז\"ע התגלו' כח השמיעה כו', דבהשגה זו מאיר האור מן המוח אל הלב שיהי' לבו חפץ באמת באלקו' לדבקה בו, ולא רק מצד הכרח השכל שמכריח את הלב לאה' מצד ההשגה"],[3601330377,"כ\"א שהלב עצמה חפצה באמת כו' מפני שמאיר ומורגש בה האור האלקי כו', וז\"ע התגלו' הכחות פנימי' של הנפש וחפצה האמיתי באלקו' וממילא כל עניני עוה\"ז הן כדבר טפל לגמרי כו'. משא\"כ בזה\"ג הוא להיפך ממש, כי טבע נפש האדם להמשך אחר צרכי גופו ועניני עוה\"ז, ואפי' מה שעושה טוב וסור מרע ומעורר את האה' לה' לדבקה בו ובתורתו, הוא מצד יגיעת הנפש שמייגע א\"ע בעמל ויגיעה להתבונן בגדולת ה' להטות לבבו ונק' לעשותה לאה' שהיא העשוי' רק ע\"י התבוננו' לא שהלב חפץ בעצמה כ\"א מצד הכרח השגת המוח כו' וכמ\"ש בתו\"א בד\"ה זכור דעמלק, ונק' בחי' זו אחור וכמ\"ש כי פנו אלי עורף, פי' דאפי' מה שפנו אלי הוא בבחי' עורף שהוא בבחי' חיצוני' ואחורי' שאינו אלא חיות מועט כו'. וז\"ש אני ישנה בגלותא שכמו בשינה שמתעלמי' הכחות דראי' ושמיעה, כמו\"כ בזה\"ג בחי' ראי' הוא בבחי' העלם לגמרי כו' (רק בנשמות הגבוהות והן נשמו' דאצי' שהן בבחי' בני חורין כו'), וגם בחי' שמיעה הוא בבחי' חיצוני' היינו בבחי' תפיסת ההשגה לבד, דהשגה זאת אינה מאירה בלב רק צריכי' להביאה\nאל הלב כו', ומה שבא אל הלב הוא בחי' הארה לבד מן ההשגה כו', וע\"ה שזה פועל התעוררו' הלב ה\"ז בבחי' חיצוני' לבד כו', וממילא א\"ז פועל כ\"כ הביטול בחיצוני' וגשמי' העולם כ\"א בבחי' ביטול היש בלבד ובפרט לאחר התפלה שחולפת ועוברת האה' כו' (ויש בזה כמה חילוקי מדרי' בהעבודה בעת התפלה והרשימו הנשארת מזה על כל היום כו' וכמ\"ש במ\"א). ובחי' זו נק' נפילה לגבי מהות הנפש שמצ\"ע לפי מקור חוצבה ראוי להיות בטבעה כשלהבת העולה מאלי' לדבקה בו, אלא כ\"ז הוא לפי שנפלה וירדה בסתר המדריגה תחת ממשלת הגוף והנה\"ב והיא אצלם במאסר ובגלות כו'. והנה ה' מתיר אסורים וסומך נופלים שסומך את נש\"י להקימם מנפילתם לשוב אל ה' להיות בבחי' פב\"פ, וההמשכה היא ע\"י המצות שהן רצה\"ע ה\"ה מעוררי' את הרצון בנפש בבחי' אה\"ר שזהו בד\"כ התגלו' עצם הנפש, ועי\"ז יהי' התגלו' בחי' הכחות פנימי' הנ\"ל להיות עיקר ענינו וכל חפצו ורצונו באלקו' כו'. אמנם ארז\"ל אם ישראל עושין תשו' נגאלין דהכח מלמע' שע\"י המצות זה מספיק בנשמו' גבוהות דמ\"מ מאיר בהם אור הנפש ומתפעל\nמהאור המאיר ע\"י המצות כו', אבל בנשמו' שמבחי' עקביים הרי מצד הסתר הנה\"ב אין האור דמצות נרגש בהם להיות מתפעלים מזה, וכמ\"ש ואני בער ולא אדע שאינו יודע ומרגיש כו' וכמ\"ש בסש\"ב, וע\"כ צריך תשו' דוקא שהו\"ע התעוררו' ר\"ר על הנפש להקימה מנפילתה וכמ\"ש השיבנו כו' חדש ימינו כקדם כו', וההתעוררו' על התשו' י\"ל שזהו מבחי' נקודת המל' שיורדת לבי\"ע כו'. וכ\"ז הוא בבחי' המל' כמו שיורדת לבי\"ע דבד\"כ היא בבחי' נקודה לבד לגבי כמו שהיא באצי' כו' (רק שבזה גופא יש ב' מדרי' עצם נקודת המל' ובחי' התפשטו' הארתה כו' כנ\"ל).\n<span data-k=\"ks\"><b>קיצור.</b> ועוי\"ל דהנה בזה\"ב הי' גילוי בחי' הפנים, היינו החפץ לאלקות, וראי' דחכ' ושמיעה היינו השגה פנימיות, ובזה\"ג הפנימיות בהעלם והאהבה באה ע\"י יגיעת השגה שהיא אהבה העשוי', וזה נק' נפילה, וה' סומך נופלים ע\"י מצות, ובנשמות דעקביים ע\"י התשובה, וההתעוררות על תשו' י\"ל שזהו מנקודת המל'. </span>"],[3601330378,"קיב) <b>אמנם</b> יעקב הקים בחי' המל' שעשאה מצבה בבחי' פרצוף כו', והיינו בחי' המל' כמו שהיא למע' מהתלבשו' בעולמו' כו', דהנה מה שמתלבש בעולמו' הוא בחי' הארה לבד, אבל עצם המל' היא למע' מהתלבשו' ונק' סובב לגבי בי\"ע, וכמ\"ש כי נשגב שמו דבחי' שמו עצמו הוא נשגב ומרומם מהעולמו' ורק הודו וזיוו הוא על ארץ ושמים כו', וז\"ש (ירמי' י' י') אלקי' חיים ומלך עולם פי' מה שהוא אלקי' חיים שנמשך ממנו חיות להיות מתלבש בכל נברא בפנימיותו ממש, ולכן אלקי' ל' רבים ע\"ש ריבוי התחלקו' החיות לכל נברא כנודע, ה\"ז רק מבחי' מלך עולם היינו בחי' המל' שהארה מבחי' מל' נמשך להיות בבחי' התלבשו' כו', אבל שמו עצמו הוא נשגב, וכמו במלכותא דארעא אין המלך נתפס באנשי המדינה כו', וחוקי המלך שזהו חיות וקיום העם ה\"ז רק הארה כו' וכמ\"ש במ\"א. ובזה יובן ענין ד' רבתי דאחד שרומז לבחי' מל' כנודע, וא\"כ צ\"ל מש\"א אח\"כ בשכמל\"ו הלא כבר נרמז ענין מלכותו ית' בד' רבתי דאחד, אך הענין הוא כי הד' רבתי רומז על בחי' עצם מדת מל' ית' שהוא למע' מהתלבשו'\nבבי\"ע, ולכן הד' סטרין מזרח מערב צפון דרום הם בטלי' שם במציאו' כו', וכנודע שזה שהיש תופס מקום זהו לגבי האור האלקי שבא בבחי' התלבשו' בעולמו' כו', אבל לגבי בחי' סובב אין היש תופס מקום כלל והכל בטל במציאו' כו', ומש\"א בשכמל\"ו זהו ההארה דמל' שבאה בבחי' התלבשו' בבי\"ע כו'. והנה ד' רבתי הוא בחי' גדלות הדבור והוא כח הדבור, וכידוע דאותי' הדבור הקבועים בפה הם רק המשכה והתגלו' מהאותי' הרוחני' שבנפש שהן הכ\"ב אותי' שבנפש הכלולין בעצמותו, וזה עיקר בחי' כח הדבור שישנו באדם גם בשעה שאינו מדבר כו', וכמו\"כ הוא בבחי' דבור העליון הם כ\"ב אותי' שהן כ\"ב מיני המשכות והתגלו' חיות שונות זמ\"ז שהם מחי' את כל העולמו', וכמ\"ש ואתה מחי' את כולם אתה הן האותי' מא' עד תי\"ו וה' מוצאות כו'. ויש בהם ב' מדרי' בחי' כח הדבור והתגלו' הדבור והן בחי' חומר וצורה, וכמ\"ש באגה\"ק סי' ה' ד\"ה ויעש דוד שם דחומר האותי' הוא חיצוני' הבל הלב שנעשה קול ונחלק לכ\"ב הברות כו', וצורת האותי' הוא בחי' כח הדבור שבנפש כו', וידוע דצורה וחומר הן בחי' אור\nוכלי דחומר האותי' הן בחי' כלים שמהם נתהווה חומרי' העולם ומציאותו שז\"ע בדבר ה' שמים נעשו כו', וצורת האותי' הוא בחי' האור שזה פועל הביטול בנבראי' כו' וכמ\"ש בתו\"א ד\"ה מזוזה מימין, ומבו' במ\"א שזהו מה שהחכ' תעוז לחכם יותר מעשרה שליטים שבעיר שהן הע\"מ להיות מציאו' העולמו', והחכ' תעוז כו' להיות בחי' הביטול כו', והוא בחי' הביטול שמבחי' חפץ ורצון ה' שלמעלה מהביטול שע\"פ השגה כו' (וכמ\"ש במ\"א בענין ב' בחי' חיות שמבחי' בינה ומבחי' חכ' כו'), וז\"ע מה שהד' רבתי הוא הביטול דיחו\"ע כו' כנ\"ל. ונמצא דד' רבתי הוא בחי' גילוי האור ושיהי' ביטול בעולמו' כו'. והנה ד' הוא מל' דלת שהמל' היא הדלת והפתח שבה וע\"י הוא ההמשכה וההתגלו' מאצי' לבי\"ע ע\"י פתיחת הדלת, וכן ההעלאה מבי\"ע לאצי' כו', ומבו' במ\"א בענין דכל השערים הי' להם דלתות לבד פתחו של אולם שלא הי' לו דלתות, כי הנה השערים הם שערי ההשפעה כו', והדלתות הם לסגור השער כו', כי לפעמים נסגרים השערים לפי מעשה התחתוני' כו', אבל פתח האולם לא הי' לו דלתות שתמיד הי' פתוח לפי\nשהוא רומז לההשפעה היוצאה תמיד בלי הפסק ובלי מעצור כו', שזהו ההמשכה מבחי' עצמו' אוא\"ס שלמע' מס' ההשתל' כו'. והענין הוא בבחי' המל' שנק' דלת שלפעמים נסגר כו', והו\"ע כהדין"],[3601330379,"טיקלא דאסתחרת קמי' כו' וכמ\"ש במ\"א, וי\"ל דהדלת הוא בחי' מל' שבמל' שזהו בחי' המסך והפרסא כו' וכמ\"ש הפרד\"ס בערך פרוכת שזהו בחי' תחתונה שבמל' כו', אך ענין ד' רבתי י\"ל שזהו כענין ההמשכה דפתחו של אולם, והיינו המשכת בחי' עצמו' אוא\"ס והוא שהמסך והפרסא לא יסתירו ויהי' גילוי אוא\"ס כו', והו\"ע הביטול דבחי' רצון וחפץ ה' כנ\"ל, רק דפתחו של אולם הוא הגילוי בבחי' א\"ס ובבחי' בל\"ג והד' רבתי שהוא הגילוי דמל' י\"ל שזהו מה שבא בבחי' או\"פ ובבחי' מדה ושיעור כו'. ובעבודה הו\"ע כל המאריך בא' דהיינו להאריך ולהרחיב דעתו ובעומק לבו עד מקום שיד שכלו מגעת, איך שאני ה' לא שניתי ממש כמו קודם ברה\"ע כי גם עתה בשמים ממעל ובארץ מתחת אין עוד כי כולא קמי' כלא ממש חשיבי כי רק הודו וזיוו לבד על הארץ ושמים, ואי לזאת הכל בטלים אצלו ית' ואליו תכסוף נפש כל חי כו', שע\"י כ\"ז יהי' בבחי' רצון לה' לבדו וכמ\"ש מי לי בשמים כו' וכמ\"ש בתו\"א בד\"ה זכור דעמלק. וז\"ע הקמת המל' שעשאה בבחי' פרצוף להיות המל' בבחי' גילוי אור, וה\"ז היפך מהגל שעשה לבן\nשרצה להיות בחי' העלם והסתר לגמרי כו', ויעקב אדרבה הקים בחי' המל' להיות מנקודה פרצוף שז\"ע המצבה להיות בחי' המל' כמו שהיא באצי' שהיא בחי' גילוי אור ולהיות בה וע\"י גילוי אלקו' בעולמו' שיהי' היחוד והביטול דה' אחד כו', ועמ\"ש הש\"ך עה\"ת דהגל בגימט' ה' אחד דכאשר יש היחוד דה' אחד אין הגל והפרסא מפסיק כלל כו'. וזה הי' עבודתו בבית לבן להמשיך גילוי אוא\"ס מבחי' לובן העליון ולהיות קימת המל' שתהי' כמו שהיא באצי' שמאיר בה גילוי אור, ובה וע\"י נמשך הגילוי גם בבי\"ע להיות בהם בחי' הביטול, וכנ\"ל שז\"ע צורת האותי' שמהם בנבראי' הוא צורת הנבראי' שמבחי' חפץ ה' כו' שהו\"ע הביטול שבנבראי' כו', ובאמת המשיך במל' בחי' או\"פ ועצמי שלמע' מבחי' הגילוי הנ\"ל וכמשי\"ת לקמן.\n<b>ואחר</b> שגמר עבודתו בבית לבן הלך לברר את עשו, וזהו וישלח יעקב מלאכים אל עשו אחיו כו'. דהנה הבירורי' דיעקב הי' בדרך מלמעלמ\"ט ע\"י גילוי אור עליון, ולהיות דעיקר עבודתו אצל לבן הי' להמשיך אורות עליוני' מבחי' לובן העליון שהו\"ע עקודים נקודים וברודים שהן עולמו' בי\"ע הכללי', עד שהמשיך האור בבחי' מל' והקים בחי' המל' להיות הגילוי גם למטה כו', וגם המשיך ההמשכה דתו\"מ שזהו המשכה מבחי' פנימי' ועצמי' אוא\"ס ב\"ה שע\"י כ\"ז יכול להיות הבירור בכל הדברים התחתונים כו', וכמשנת\"ל פק\"ח שהבירור הוא בכח אור עליון דוקא כו', וע\"כ כאשר גמר עבודתו הנ\"ל הי' ביכולתו לברר את עשו שלמטה כו'. וזהו שמודיע לו מה שעשה בבית לבן היינו שכבר המשיך כל האורות והגילוי' העליוני' וגם המשיך בחי' התו\"מ וביכולתו לבררו כו', וזהו הסדר שתחלה הי' צ\"ל אצל לבן להמשיך כל ההמשכות הנ\"ל ואח\"כ הבירור דעשו כו', וז\"ש עם לבן גרתי ותרי\"ג מצות שמרתי והיינו דבכח זה יהי' הבירור כו', ולפמשנת\"ל דעבודתו בבית לבן הי' גם ענין הבירורי' הי' צ\"ל ג\"כ תחלה\nהעבודה אצל לבן שהוא בחי' כח\"ב דתהו ואח\"כ הבירור דעשו שהוא בחי' ז\"א דתהו, והגם דבהבירורי' דעכשיו הרי הבירור דכח\"ב יהי' לעתיד דוקא כנודע ומבו' במ\"א, הנה זהו בהבירור בדרך מלמטלמ\"ע, אבל גבי יעקב שהי' הבירור בדרך מלמעלמ\"ט הי' תחלה הבירור דכח\"ב כו'. וזהו וישלח יעקב מלאכים כו' דאחר שהמשיך כל האורות וההמשכות העליוני'"],[3601330380,"ובירר בחי' כח\"ב דתהו הלך אח\"כ לברר את עשו, וע\"ז הוא שמודיע לו מה שעשה בבית לבן ואו' עם לבן גרתי ותרי\"ג מצות שמרתי שבכח זה יש ביכולתו לבררו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם יעקב עשה מצבה שהמשיך בחי' המל' כמו שהיא באצי', והו\"ע ד' רבתי דאחד יחו\"ע, ובשכמל\"ו יחו\"ת, והוא בחי' חומר האותיות מקור המציאות, וצורת האותיות להיות ביטול, והחכ' תעוז לחכם, דלת ע\"ד פתחו של היכל והו\"ע כל המאריך באחד, וז\"ע הקמת המל', ואחר הבירור בבית לבן בא לברר את עשו. וזהו וישלח יעקב מלאכים.</span>"],[3601330381,"<h3>בס\"ד. ש\"פ וישב, כ' כסלו, תער\"ג</h3>\n<b>פדה</b> בשלום נפשי מקרב לי, כי ברבים היו עמדי, וארז\"ל אמר הקב\"ה כל העוסק בתו' וגמ\"ח ומתפלל עם הצבור כאלו פדאני אותי ואת בניי מבין האומות, ופרש\"י דבתו' כתי' וכל נתיבותי' שלום וגמ\"ח מביא שלום בין איש לרעהו, ומתפלל עם הציבור זהו כי ברבים היו עמדי. וצ\"ל מהו\"ע הפדי' למע' דהפדי' בנש\"י ניחא, אבל מה שייך ענין הפדי' למעלה, גם צ\"ל מה שהפדי' היא דוקא ע\"י ג' עניני' אלו דתו' וגמ\"ח ותפלה בצבור ולא תפלה סתם. ולהבין זה ילה\"ק משנת\"ל בענין ויקח יעקב אבן וירימה מצבה, שזהו הקמת המל' מבחי' נקודה לעשותה פרצוף, ונת' דבחי' נקודה זהו כמו שהמל' יורדת ומתלבשת בבי\"ע כו', ועשאה פרצוף שזהו כמו שהיא באצי' שנק' סובב לגבי בי\"ע כו', והו\"ע ד' רבתי דאחד שזהו בחי' כח הדבור והו\"ע בחי' צורת האותי' שמזה נמשך הביטול בעולמו' והו\"ע הצורה שבנבראי' שמבחי' חפץ ה', דכמו\"כ בבחי' מל' זהו בחי' כח הדבור שמזה נעשה הביטול בנבראי' כו'.\nקיג) <b>והנה</b> הפרד\"ס ערך מצבה כ' כי המל' בהיותה מיוחדת עם הת\"ת נק' מצבה, ולכן שייך זה ליעקב שהוא ת\"ת, וכ\"ה בזהר פ' נח דע\"ב ב' ע\"פ והאבן הזאת אשר שמתי מצבה מאי מצבה דהוה נפילה ואוקים לה, ויצוק שמן על ראשה דהא ביעקב תליא מלתא למעבד יתיר מבני עלמא, ומבאר שם שז\"ע ושלמה ישב כו' ותכון מלכותו מאד דהיינו דהוה קיימא סיהרא באשלמותא כמ\"ש בזח\"א דרמ\"ג סע\"א והקימה באופן כזה זהו ע\"י יעקב דוקא וכמשי\"ת. והנה ענין דקיימא סיהרא באשלמותא הוא שמאיר האור בכל המל' גם בה\"ס האחרונו' ואז מאיר האור בגילוי גם בבי\"ע כו', דהנה הע\"ס נחלקי' לב' מדרי' כללי' והן ה\"ס עליונות וה\"ס תחתונות והיינו כח\"ב ודעת הכולל פנימי' חו\"ג, ות\"ת הכולל חיצוני' חו\"ג ונה\"י. דהנה הת\"ת יש לה שני מציאו', הא' מציאו' עצמה שלמע' מהתכללו' חו\"ג, והב' מה שכוללת חו\"ג וכמ\"ש הפרד\"ס שע\"א פ\"ב והו\"ע משה מלגאו ויעקב מלבר כו', ובד\"פ זהו ב' מיני התכללו' שיש בת\"ת הא' ההתכללו' דחו\"ג שנותנים"],[3601330382,"מקום זל\"ז והיינו רק מה שסובלי' זא\"ז, והב' ההתכללו' שמקבלי' זמ\"ז עד מבלי אשר ימצא ראש וסוף כו' כידוע ומבו' במ\"א, ובבחי' זו הת\"ת הוא כמו הדעת כו', והתכללו' הא' הנ\"ל זהו בחי' חיצוני' הת\"ת כו'. ונמצא דה\"ס עליונו' זהו בד\"כ בחי' פנימי' הספי' וה\"ס התחתונו' זהו חיצוניותן כו'. וכשם שיש ב' מדרי' אלו בהע\"ס בכלל כמו\"כ הוא בכל ספי' בפרט, דה\"ס העליונו' הן הפנימי' שבה וה\"ס התחתונו' הן החיצוני' שבה כו'. וכמו\"כ בחי' המל' נחלקת לה\"ס עליונו' שזהו בחי' הפנימי' וה\"ס תחתונו' הן בד\"כ בחי' חיצוני' המל' כו', וענין דקיימא סיהרא באשלמותא הוא שיהי' האור בבחי' חיצוני' המל' כמו בהפנימי' ואז יהי' הגילוי בבי\"ע בבחי' גילוי אור ממש כו'. והוא עד\"מ כמו הלבנה שנודע שמתחלקת לב' חצאין חצי העליון שכנגד השמש ושמאירה תמיד מהשמש, והחצי הב' שכנגד חלל העולם פעמים מאירה ופעמי' אינה מאירה, דבסוף החדש חצי כדור התחתון חשוך מפני ריחוקה מהשמש, ובתחלת החדש אז מולד הלבנה שמתחיל להאיר גם חצי הכדור התחתון והולכת ומאירה יותר עד שבאמצע החדש\nמאיר כל חצי הכדור התחתון ונק' מילוי הלבנה. והדוגמא מזה למע' בבחי' מל' דה\"ס הראשונו' שלה מאירים תמיד מבחי' ז\"א, והן למע' מבחי' התלבשות בבי\"ע כו', אמנם בחי' המל' המתלבשת ומתפשטת בבי\"ע הוא בחי' ה\"ס האחרונות שבה וכדוגמת חצי כדור התחתון שבלבנה שכנגד חלל העולם כו', וכמו בלבנה דאין החלק הזה מאיר בשלמו' רק בחצי החדש, כמו\"כ הוא בבחי' המל' בחצי התחתון שמתפשט בבי\"ע אין האור מאיר רק בצמצום והעלם גדול בבחי' אחורים וחיצוני' לבד כו', דגם שמחי' כל העולמו' הרי החיות בא רק מבחי' חיצוני' האור שאינו מאיר שם אור הפנימי' כו'. וענין דקיימא סיהרא באשלמותא הוא שכל הי\"ס דמל' מאירים גם הה\"ס האחרונו' מאיר בבחי' גילוי אור ממש, לא רק אור מצומצם, וגם ההשפעה שמשפעת המל' לבי\"ע בא בבחי' פנימי' לא בבחי' אחורי' וחיצוני' לבד כו', וכמ\"ש כ\"ז בסי' בפי' ישיש כגבור לרוץ אורח כו'. וזהו דבימי שלמה קיימא סיהרא באשלמותא לפי שהי' דור ט\"ו לאברהם הי' אז זמן מילוי הלבנה שהי' מאיר האור בכל הי\"ס דמל' עד שגם למטה הי' גילוי אוא\"ס ממש, וכמו\nבבהמ\"ק שהי' גילוי אוא\"ס ממש בבהמ\"ק ועי\"ז הי' הגילוי גם בעולם, וכמשנת\"ל פקי\"א דכללו' העבודה הי' אז בבחי' ראי' ושמיעה שהי' האור מאיר בגילוי בנפשם כו'. וכנודע בג' זמנים דשלמו' אדם דוד משיח שהן ר\"ת אדם, דאדה\"ר קודם החטא הי' גילוי אוא\"ס למטה וכדאי' במד\"ר שה\"ש (ע\"פ באתי לגני) עיקר שכינה בתחתוני' הי' כו', והי' אדה\"ר מביט מסוף העולם ועד סופו בהאור שנברא ביום ראשון, שזהו גילוי בחי' עצמו' אוא\"ס ב\"ה דביום הראשון בגימט' כתר כו' כנודע, וכמו לעתיד שיהי' גילוי אוא\"ס למטה וכמ\"ש ונגלה כבוד ה' וראו כל בשר כו', כי עין בעין יראו בבחי' גילוי ממש כו', וכן הי' בבהמ\"ק שראו ממש גילוי אוא\"ס למטה כו', דכ\"ז הוא אינו ע\"פ ס' השתל' ע\"פ מא' קו המדה, דכללו' האור הוא אור מצומצם ומתצמצם ומתמעט ממדרי' למדרי' עד שלמטה אינו מאיר גילוי אור, והיינו דמה שיכול להיות הגילוי בבי\"ע הוא רק בחי' המציאו' דאלקו', דגם במלאכים דברי' שיודעים ומשיגים אלקות וכידוע ומבו' במ\"א בענין עולם הברי' שהוא יש הראשון שנברא מהאין האלקי שמאיר שם גילוי\nהאין כו', ואימא עילאה מקננא בכורסיא שמושג שם האור כו', הרי כ\"ז הוא בחי' המציאו' לבד לא גילוי המהות ממש דמבחי' גילוי המהות אא\"ל מציאו' הנבראי' כ\"א מבחי' המציאו' כו',"],[3601330383,"וכ\"ש למטה שהאור האלקי הוא בבחי' העלם והסתר, רק נש\"י יש להם השגה באלקו' והיינו מפני שבעצם מהותם הם אלקו' כנודע, ע\"כ גם למטה בתכלית ההעלמות וההסתרים יש להם השגה באלקו', וג\"ז הוא בבחי' ידיעת המציאו' לבד, אבל מהות אלקו' אינו מושג לנבראי', ואפי' בנשמו' דאצי' כתי' וראית את אחורי כו' וכמ\"ש באגה\"ק בקו\"א ד\"ה להבין מ\"ש בפע\"ח (ומובן שם שזהו בחי' המציאו', ופני שהוא בחי' המהות לא יראו כו', ובאגה\"ק ד\"ה עוטה אור משמע דוראית את אחורי זהו מהות בחי' אחורי' דחכ' והו\"ע נובלות חשמ\"ע כו', וע\"ש בד\"ה להבין מ\"ש בפע\"ח בענין המצות ולימוד הלכות וסודות המצוה כו'). ונשמו' בג\"ע שמשיגים מהות הזיו כו' זהו זיו תורתן ועבודתן וכמ\"ש בלק\"ת ד\"ה במד\"ס, שע\"י התו' נמשך בחי' מהות אלקו' והיא הנותנת כח לצדיקים שיוכלו לקבל את האור וכמ\"ש בסש\"ב פל\"ו, אבל מה שנמשך בעולמו' ע\"פ ס' השתל' הוא בחי' המציאו' לבד דאלקו' כו'. ובבהמ\"ק הרי ראו ממש מהות אלקו' למטה וכמ\"ש יראה כל זכורך כו', וכל ההמשכו' והגילוי' למטה הכל הוא ע\"י בחי' המל', ולהיות\nשהי' אז קיימא סיהרא באשלמותא שהי' הגילוי גם בה\"ס אחרונו' דמל' שזהו ג\"כ לא ע\"פ סדר השתל' כו', דע\"פ סדר השתל' הוא שרק בה\"ס העליונות יאיר בחי' פנימי' האור אבל בה\"ס האחרונו' יהי' רק בחי' אור מצומצם והיינו בחי' חיצוני' האור לבד שבא בבחי' צמצומים והעלמו' בכדי שיהי' מציאו' יש כו', ורק מבחי' אוא\"ס שלמע' מהשתל' נמשך האור והגילוי באופן כזה שגם חיצוני' המל' היא כמו הפנימי' ע\"כ הי' גם למטה גילוי מהות אלקו' ממש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והפרדס כ' מצבה יחוד ת\"ת ומל', והו\"ע דקיימא סיהרא באשלמותא, דע\"ס נחלקות ה\"ס עליונות בחי' פנימיות, וה\"ס תחתונות חיצוניות, ב' מציאות בת\"ת, וכן במל' פנימיות המאירה תמיד מז\"א, וחיצוניות המתלבשת בבי\"ע בחי' העלם, וקיימא סיהרא באשלמותא הוא שגם בהחיצוניות יאיר האור, ויהי' הגילוי למטה, וכמו קודם החטא, וכמו לעתיד, וכן הי' בבהמק\"ד, דעכשיו רק גילוי המציאות דגם בנשמות הגבוהות כתי' ופני בחי' המהות לא יראה, והגילוי הנ\"ל הוא בחי' גילוי המהות. </span>\nקיד) <b>ושרש</b> המשכה זו היא מבחי' פנימי' ועצמי' אוא\"ס שלמע' מע' מבחי' השתל' כו', דבחי' חיצוני' דאוא\"ס שיש לזה שייכו' לס' השתל' הרי ההמשכה היא בס' והדרגה כו' (שזהו המדידה ברצון דברה\"ע ששיער בעצמו להאיר במדה וגבול להיות ההמשכה בס' והדרגה כו'), רק מבחי' פנימי' אוא\"ס שאינו שייך להשתל' כלל משם נמשך שיהי' הגילוי שלא בס' והדרגה דמא' קו המדה כו', וז\"ש ישיש כגבור לרוץ אורח דישיש בגימט' כתר וישיש הוא ב\"פ יש שהן ב' חצאי הכתר, דמבחי' מחצה העליון שזהו פנימי' הכתר משם דוקא הוא שרש ההמשכה הזאת להיות גילוי מהות אלקו' עד למטה מטה כו'. וז\"ש הזהר דהא ביעקב תליא מלתא, דהנה יעקב הוא בחי' הת\"ת שעולה עד הכתר וידוע דהיינו בחי' פנימי' הכתר דוקא, וזהו בחי' בריח התיכון המבריח מן הקצה אל הקצה, וידוע דקו האמצעי חלוק מב' הקוין דימין ושמאל בב' דברים, הא' שמבריח מן קצה העליון ביותר למע' מב' הקוין דשרשן ג\"כ בכתר אך רק בבחי' חיצוני' הכתר, אבל קו האמצעי שרש"],[3601330384,"המשכתו מבחי' פנימי' הכתר כו', ומבריח עד קצה התחתון ביותר דהיינו בחי' המל' סוכ\"ד דאצי', דהנה חו\"ב הרי בינה רק עד הוד אתפשטת, ויסוד אבא ארוך שנמשך עד יסוד ז\"א, אבל קו האמצעי מבריח עד בחי' המל' סדכ\"ד דאצי' ובבחי' האחרונו' שבה כו'. והב' דאופן ההמשכה הוא דכללו' הקו היא כמהות א' ממש, ולא כמו הב' קוין כמו חח\"ן מימין הרי החסד הוא מהות אחר מבחי' החכ' וכן בג\"ה משמאל כו', משא\"כ דת\"י כולם הם מהות א' ממש כו' וכמ\"ש במ\"א באורך, והיינו שהדעת ממשיך מבחי' פנימי' הכתר ואותה ההמשכה ממש הוא שנמשך בבחי' ת\"ת ויסוד כו', וב' הדברי' הא בהא תליא דלפי שההמשכה היא מבחי' פנימי' הכתר דוקא ע\"כ אינה משתנית ונמשך בחי' המהות ממש בכל המדרי' כו'. וזהו מ\"ש הפרד\"ס דמצבה הוא בחי' המל' בהיותה מיוחדת עם הת\"ת, דהנה ע\"פ ס' השתל' המל' מקבלת מבחי' נה\"י דז\"א והיינו מבחי' חיצוני' המדות דנה\"י הן לבר מגופא כו', וכמו הדבור שמקבל רק מחיצוני' המדות שהרי בתוקף ההתפעלות אינו יכולי' לדבר כו', אמנם יחוד ת\"ת ומל' הוא שנמשך במל' בחי' עצמו'\nהמדות כו' וכמ\"ש בלק\"ת ד\"ה וכי תבאו ונטעתם כו', וכמו הדבור שמדבר דברי חול להדבור שמדבר דברי חכ' כו', כך ע\"מ נק' מלין דהדיוטא לפי שמאיר בהם רק בחי' נה\"י כו', אבל עה\"ד נמשך בהם מבחי' פנימי' חכ' ורצונו ית' כו'. וזהו יחו' ת\"ת ומל' וכמא' והת\"ת זו מ\"ת כו', ובשרש זהו בחי' יחוד פנימי דאו\"א והו\"ע יחוד שמשא וסיהרא להיות המשכת או\"ח כו', וידוע דיחוד פנימי דאו\"א הוא שנמשך מבחי' פנימי' הכתר דוקא וכמ\"ש במ\"א וזהו שנמשך במל' ע\"י הת\"ת דוקא כו'. וזהו ויצוק שמן על ראשה (דעז\"א בזהר דהא ביעקב תליא כו'), י\"ל דהיינו בחי' שמן הטוב שזהו בחי' ג\"ר דעתיק כו' וכמ\"ש במ\"א, ועי\"ז המשיך בחי' גילוי העצמו' גם בבחי' מל' להיות הגילוי בבי\"ע כו'. והענין הוא דהנה תכלית כוונת יעקב הי' להמשיך שגם למטה בבי\"ע יהי' איהו וחיוהי וגרמוהי חד כמו שהוא באצי', שזהו ג\"כ תכלית הכוונה במ\"ת שניתנה התו' למטה בהלכו' גשמי' ולהיות מושגי' בשכל גשמי היינו שכל הטבעי כו', שע\"י שלומד ההלכה ומבין אותה בשכלו הטבעי נעשה השכל הטבעי כלי לחכמתו ית', וכן\nבמעשה המצות וכמו במצות צדקה וגמ\"ח נעשה היד גשמי כלי לאוא\"ס ב\"ה, כמו חסד דרועא ימינא שהיא כלי לאוא\"ס, כמו\"כ הוא היד הגשמי הנותנת צדקה, ובהתגלו' יהי' כן לעתי' דאז יהי' היד גשמי כמו חסד דאצי' ממש, וזהו ע\"י העבודה דעכשיו בנתינת הצדקה דבאמת גם עכשיו כ\"ה רק שזהו בהעלם ולעתיד יהי' בגילוי כו'. וכן המדות טבעי' נעשי' עי\"ז כלי לאלקו' וכמו הנותן צדקה לעני כו' והמפייסו כו', שהעיקר הוא המדה שבלב שיתן בעין יפה שגם בעבודת הצדקה שהיא בדרך כפי' צריכה להיות הנתינה בעין יפה דוקא וכמו ולא ירע לבבך כו', ועי\"ז נעשה המדה טבעי' כלי לאלקו' כו', וכל המצות הן בכח המעשה דוקא (ויש מצות שהן חובת הלבבות ג\"כ הכוונה בהן שיהיו גם בכחות הטבעי', וכמו ואהבת כו' בכל לבבך בשני יצריך דעיקר מצות האה' היא שגם הלב הטבעי יתעורר באה' וכמו לבי ובשרי ירננו כו') ונתלבשו בדברים גשמי' דוקא כמו ציצית בצמר הגשמי ותפילין בקלף הגשמי כו', דתכלית הכוונה בכ\"ז הוא שתהא התלבשו' והתאחדו' אוא\"ס ב\"ה ממש בחכ' וחסד שלמטה במעהמ\"צ שהן בכח המעשה דוקא\nכנ\"ל, ובעשייתן בגשמי' בדברים הגשמי' כו' שזה הי' המשכת מרע\"ה שגם למטה יהי' היחוד בבחי' איהו וחיוהי וגרמוהי חד ממש כמו למע' כו'"],[3601330385,"וכמ\"ש בתו\"א ד\"ה משה ידבר. והנה נודע דהתחלת יחו\"ע דמ\"ת הי' מהאבות וכמ\"ש בלק\"ת מהאריז\"ל בפ' לך לך, אמנם עיקר התחלת היחוד הי' ע\"י יעקב וכדאי' במד\"ר פ' בחוקותי ע\"פ וזכרתי את בריתי יעקב הה\"ד ליעקב אשר פדה את אברהם משל לא' כו' וראה שעתיד להוליד בת שתהא נשאת למלך כו' כך אברהם כו' כדאי הוא להנצל בשביל יעקב כו', ומבו' במ\"א ביאור זה דהנה קודם כל מצוה אומרים לשם יחוד קוב\"ה ושכינתי' דשכינתי' הוא בחי' מל' ובד\"כ הוא בחי' ממכ\"ע כו', וקוב\"ה זהו בחי' סוכ\"ע שקדוש ומובדל כו', ויחוד קוב\"ה ושכינתי' הוא שיהי' גילוי בחי' סוכ\"ע בממכ\"ע כו', וז\"ע יחוד שהוא המשכת הדעת דאל דעות ה' ד\"ע וד\"ת והיחוד הוא שגם בד\"ת יהי' מושג כמו שהוא בד\"ע איך שכולא קכל\"ח כו'. ויחוד זה התחיל מיעקב, דכתיב שמאלו תחת לראשי וימינו תחבקני שאברהם הי' בבחי' וימינו תחבקני, ויצחק הי' בבחי' שמאלו תחת לראשי שכ\"ז הוא בבחי' מקיף שזהו הכנת היחוד, אבל בכדי שיומשך למטה בבחי' פנימי' שז\"ע היחוד הי' ההתחלה מיעקב, לפי שיעקב אותי' יבקע וכמ\"ש אז יבקע כשחר\nאורך שיעקב התחיל לבקוע את החשך להיות גילוי בחי' ד\"ע למטה כו'. וזהו שהלך יעקב לחרן בחי' עלמא דפרודא להמשיך שם האור והגילוי כו', וגם ע\"י הבירורי' שבירר והעלה למע' המשיך עי\"ז גילוי אוא\"ס למטה כו' (וכמו קודם מ\"ת הי' צ\"ל תחלה שעבוד מצרים, שעי\"ז העלו ניצוצו' הרבה וכמ\"ש וגם ערב רב כו', וע\"י תוקף הבירור שלהם במצרים הי' מ\"ת להיות תומ\"צ בגשמי' כו', וכמ\"ש בתו\"א ד\"ה לך לך, כמו\"כ ביעקב הי' צ\"ל היציאה לחרן בחי' נחר גרוני שזהו בחי' גלות ועמ\"ש בתו\"א ד\"ה לכן אמור ובהגהות לשם, ובירר שם בירור רב בצאן לבן, ועי\"ז המשיך להיות גילוי אוא\"ס למטה כו').\n<span data-k=\"ks\"><b>קיצור.</b> ושרש ההמשכה היא דוקא מבחי' פנימיות אוא\"ס, ולכן הוא ע\"י יעקב ת\"ת עולה עד פנימיות הכתר קצה העליון ומבריח עד המל' קצה התחתון ביותר, ובכל הקו בשוה, וזהו יחוד ת\"ת ומל', ושרשו מיחוד פנימי דאו\"א, וזהו ויצוק שמן י\"ל ג\"ר דעתיק. והענין הוא דהנה המשכה דתורה הוא שגם בבי\"ע יהי' איהו וחיוהי וגרמוהי חד, דההלכה המושגת היא מהות ח\"ע, ובמצות הרי כח היד הנותנת צדקה וכן המדות נעשים כלים, ולעתיד יהי' בהתגלות, וזהו שהמשיך משה, וההתחלה היא שהמשיך יעקב, יעקב יבקע, וזהו שהלך לחרן, וע\"י הבירורים המשיך פנימיות א\"ס ב\"ה. </span>\nקטו) <b>והנה</b> בכדי שתהי' ההמשכה צ\"ל תחלה ההעלאה למעלה, וזהו שבהתחלת הילוכו כתי' ויקח מאבני המקום וישם מראשותיו, דאבני המקום הן בחי' אותי' דדבר ה' שנעשו מקור לעולמו' דבריבוי השתל' נעשה עלמא דפרודא לגמרי כו', וישם מראשותיו היינו שהעלה אותם לבחי' החכ' שזהו מה שנעשו אבן א' בחי' י' דש' ה' בחי' חכ' כו', והיינו שהעלה אותם מן הפירוד אל היחוד כ\"כ להיות בבחי' ביטול אמיתי דחכ' כו', ואח\"כ ויחלום כו' שהובטח מלמע' בכל ההמשכות העליונו' וכתי' והנה אנכי עמך ושמרתיך בעבודת הבירורי' כו', והשיבותיך אל האדמה הזאת דהיינו בבחי' המשכת האור והגילוי עד למטה מטה ממש כו', וזהו ויקח את האבן אשר שם מראשותיו בבחי' העלאה מלמטלמ\"ע וישם"],[3601330386,"אותה מצבה ויצוק שמן על ראשה בבחי' המשכת האור מלמעלמ\"ט להיות הגילוי גם למטה כו', וכמ\"ש כ\"ז בתו\"א ד\"ה ויצא באורך. ובעבודה הו\"ע אותי' התפלה ואותי' התו' דאותי' התפלה הן בבחי' העלאה מלמטלמ\"ע דמט\"ט קושר כתרים לקונו מתפלותיהן של ישראל, וכמו הכתר שנעשה מאב\"ט כמו\"כ הוא בחי' הכתר לקונו שנעשה מאותי' התפלה המתבררים מכחות טבעי' דנה\"ב כו', ועי\"ז הוא ההמשכה אח\"כ ע\"י אותי' התו' כו'. דהנה אי' בזהר בהתחלה ד\"ד ע\"א מאן דמהפך חשוכא לנהורא וטעמא מרירו למתקא והו\"ע התפלה והתו' שע\"י התפלה מהפך מרירו למיתקא, כי מרירו הן תאוות עוה\"ז ותענוגיו שמושפעים מהיכלות הקלי' שאין לך דבר למטה שאין לו היכל למע' שממנו בא תוצאות הדבר ההוא והשפעתו, וכל תענוגי עוה\"ז אפי' דבר קל ואפי' המסלסל בשערו הנה החיות ההוא נמשך מהיכלות הטומאה (ועמ\"ש באגה\"ת פ\"ו), ולכן נענש יוסף בשבתו בבית האסורים י\"ב שנה על שהי' מסלסל בשערו כו', וצריך להפוך מרירו למתקא שלא ירצה בכל התענוגי' האלו, ותמורת זה יהי' כל תענוג נפשו באלקו' וכמו טעמו וראו כי טוב ה'\nוכמו אז תתענג על ה' כו'. והוא ע\"י התבוננו' בתפלה מהאור וחיות אלקי שבכל דבר ודבר המהווה ומחי' אותו ואיך שהעיקר הוא האלקו' כו', והיינו שמתבונן איך שבכל התענוגים יש בהם אור וחיות אלקי המחי' אותם, דבהתבוננו' זאת לא ירצה בהתאווה הגשמיות כ\"א בהחיות האלקי שבו והו\"ע מוצא פי' ה' שבהמאכל שע\"ז יחי' האדם כו', ובפרט כשמתבונן בפרטי' אופן החיות האלקי בכל עולם ועולם ובכל נברא ונברא בפרט, ואיך שכללות החיות שבעולם הוא חיות מצומצם ונעלם ביותר והחיות אלקי שבעולמות הוא בבחי' מעלה ומדרי' עליונה יותר ובגלוי ביותר כו', שעי\"ז מתקרב ומתדבק מאד באלקו' שכל חפצו ורצונו הוא באלקו' ואינו רוצה בהדברים הגשמי' כו'. וביותר כשיתבונן במ\"ש ראה נתתי לפניך את החיים כו' איך שכל התאוות גשמי' הם מות ורע כו', וכמ\"ש במ\"א דמ\"ש חיים ומות אין הכוונה בגשמי' דחיים הוא בשעת שהדבר חי ומות הוא בפירוד החיות ממנו דמי הוא פתי שלא ירצה בחיות, רק הכוונה שבכל דבר בעת שהוא בחיותו וקיומו יש בו חיים ומות והוא שהחומרי והגשמי הוא בבחי' מות שהרי הוא\nכלה ונפסד שגם בעת חיותו וקיומו ה\"ה נפסד, וכמו שהאדם מרגיש בעצמו שגופו וכחותיו הטבעי' נחלשי' מזמן לזמן, וחיים הוא החיות הרוחני שהנשמה היא בבחי' קיום שאין בה הפסדות ח\"ו, שג\"ז האדם מרגיש בעצמו שהנשמה אין בה הפסדו' אדרבה מתגלה ומתחזקת ביותר מזמן לזמן (ע\"י זיכוך ותיקון הכלים והסרת החומרי' כו'), וכמו ימים ידברו ורוב שנים כו', הרי שזה היפוך מהגוף שנחלש ונפסד מזמן לזמן וכמ\"ש הבחיי שמשעה שנולד מתחיל בו ההפסדו' ומצד הנשמה אדרבה ימים ידברו כו', וזקני ת\"ח כ\"ז שמזקיני' דעתם מיושבת עליהם וכמא' סבא דעתוהי סתים כו' שכח שכלו מתחזק ביותר שבא בשכלו על עניני' נעלים ועמוקי' שלא בא עליהם מקודם ובכל ענין בעומק ופנימיות שבו כו', וע\"כ הרוחני' נק' חיים והחומרי' נק' מות כו'. ורע הוא עוד גרוע מהמות, דמות הוא ההפסדות גם בעת שהחיות בו דבנמשל היינו גסות וישות החומרי' (שהוא הפסולת) גם כשאין בזה רע (והיא בחי' נוגה בעצם כו'), ורע הוא דבר איסור ר\"ל או תאוות היתר למלאות תאות נפשו שהן ג\"כ רע כנודע, שזהו עד\"מ כמו הגשמי\nבהפרד ממנו החיות שנרקב ונפסד ונעשה דבר מיאוס ושיקוץ ממש כו', וכמ\"ש כ\"ז באורך בד\"ה תקעו, עת\"ר. שע\"י אריכו' ההתבוננו' בזה"],[3601330387,"שמובן היטב הענין גם בנה\"ט הרי ניטל מהנה\"ט התענוג (בל\"א דער גישמאק) מעניני העולם עד שנעשים הדברים נמאסים אצלו ויהי' חפצו ורצונו באלקו' ויתענג בזה כו', וז\"ע הקרבנו' שהי' העיקר הקרבת החלב ודם דחלב הו\"ע התענוג והיינו שהתענוג הגשמי נהפך לעונג אלקי כו'. ועי\"ז נעשה אתהפכא חשול\"נ והיינו שחשך הגשמי של עוה\"ז מעשה שמים וארץ שנראים ליש ודבר גשמי יתהפך לנהורא להיות בו גילוי אוא\"ס להיות היש בטל אליו ית' ונגלה כבוד ה' למטה כמו שהוא למע', והיינו שע\"י דטעים מרירו למתקא שהיא מלמטלמ\"ע להפוך לבו מתאוות עוה\"ז ולדבקה בו ית' בתשוקה וצמאון כו', יאיר אור ה' מלמעלמ\"ט במקום החשך של עוה\"ז להאיר חלקו בעולם שלא יהי' העולם מעלים על אור ה' וקדושתו ויהי' גילוי אור כו'. וזהו ההמשכה דתו' וכנודע דתו' היא מלמעלמ\"ט להיות המשכת האור למטה כמו שהוא למע' כו', וז\"ע ויצוק שמן על ראשה להיות גילוי בחי' ח\"ע ממש למטה שהוא בחי' תומ\"צ שמלובשי' למטה בדברי' גשמי' המחליף פרה בחמור כשר פסול כו', עכ\"ז יהי' בהם גילוי בחי' ח\"ע ממש כמו שהוא\nלמע' וכמארז\"ל מה להלן באימה ויראה אף כאן כו', פי' מה להלן בשעת מ\"ת על ה\"ס שהי' באימה ויראה בבחי' ביטול אמיתי שאז הי' בחי' גילוי בתכלית ששמעו מפי עצמו' המאציל אנכי ה' אלקיך כו', אף כאן היינו גם כמו שהתו' מלובשת למטה בדברי' גשמי' יהי' ע\"י גילוי ח\"ע ממש כמו שהי' אז כו'. וז\"ע פותח את ידיך א\"ת ידיך אלא יודי\"ך והן ב' יודי\"ן דהוי' ואד' בחי' ח\"ע וח\"ת כו', והפתיחה דיודי\"ן הוא שיהי' גילוי בחי' י' דהוי' ביו\"ד דאד' דשרש ההמשכה ע\"ז הוא מבחי' עצמו' אוא\"ס כו', וזהו ומשביע לכל חי רצון דהיינו ההמשכה שבבחי' בל\"ג וכמ\"ש במג\"ד אות יו\"ד. וזהו שאחר כל העובדות שלו בבית לבן כתי' ויקח אבן וירימה מצבה שזהו כללו' בחי' ההעלאו' וההמשכו' שלו להיות גילוי בחי' אוא\"ס למטה כו', וכל הגילוי' האלו זהו ע\"י הכלים דאצי' שהן כלים לאוא\"ס שע\"י יהי' גילוי אור כו', וה\"ז היפך פעולת לבן שעשה גל שכוונתו הי' להעלים ולהסתיר כו', והיינו שאחז עצמו בהלבושין המעלימי' כנ\"ל בשם הש\"ך עה\"ת ורצה להעלים ביותר כו', אבל יעקב עשה מצבה (ונכלל בזה גם\nענין הצקת השמן כו' וכמ\"ש קודם אשר משחת שם מצבה כו'), היינו שהמשיך בחי' הגילוי בכללו' בחי' המל', והיינו שלא ע\"פ ס' השתל' דע\"ס שהאור מתצמצם ממדרי' למדרי' ולמטה אינו מאיר גילוי אור והיינו מפני שכללו' האור הוא אור מצומצם כו', ולגבי אור זה יכולי' הלבושי' להעלי' כו', והוא המשיך מבחי' פנימי' ועצמו' א\"ס שגם ההמשכה בע\"ס דאצי' תהי' ההמשכה שלא כפי ס' ההשתל' כו' (ע\"ה שזהו במדה ושיעור כו'), והוא ההמשכה כפי היח\"ע דמ\"ת כו', שיהי' הגילוי בבחי' המל' גם במדרי' התחתונו' ועי\"ז יהי' גילוי בחי' מהות אלקו' ממש למטה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וההעלאה לזה ויקח מאבני המקום אותיות דבר ה' מקור היש, וישם מראשותיו שהעלם לבחי' חכ' ביטול אמיתי, ואח\"כ וישם אותה מצבה ויצוק שמן, ובעבודה הוא אותיות התפלה המתבררים מנה\"ט, והוא דמהפך מרירא שהן התאוות למיתקא, ע\"י ההתבוננות בהחיות האלקי שבהם, ובאופן התלבשות החיות, וביותר בענין ראה נתתי לפניך החיים והטוב שזהו הרוחני והאלקות, והמות הוא הדבר הגשמי בעצם, והרע היא התאוה, שעי\"ז ניטל מהנה\"ב התענוג שלו</span>"]]});
